INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sport 1 Live: Duel', 'Which Team has won the last Champions League? Who scored the “Wembley Goal”, causing the 3:2 at the World Cup 1966? Which record established France in the UEFA Cup season 1997-1998? Do you have the answer for all questions? Then hurry up and play the ultimate Football Cup quiz SPORT 1 Live : Duel and boast your knowledge of football. Challenge your friends or compete against random opponents and compare your scores live. Will you be the one with the top international highscore?' FROM games WHERE igdb_id = 17397 ON CONFLICT (game_id, language_code) DO NOTHING;
