INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mage-gauntlet', 38736, '2014-10-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/uczwddsuyqbpm56d6wfz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qezcdx9exek64z9omhn3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mage Gauntlet', 'Mage Gauntlet is a classic-style action-RPG, designed from the ground up for mobile. It''s inspired primarily by 90''s action RPGs for the Super Nintendo, such as Legend of Zelda: LTTP and Secret of Mana. We wanted to make a fast-paced RPG that doesn''t waste your time with fetch quests. Fight and explore your way through a humorous storyline about eccentric wizards, powerful artifacts, and dangerous monsters. Find items to customize your character''s strengths and weaknesses. Enjoy smooth, responsive controls and fast, satisfying combat. When you beat the game, unlock a remixed Master Mode with overwhelming enemy numbers and new secrets to uncover.' FROM games WHERE igdb_id = 38736 ON CONFLICT (game_id, language_code) DO NOTHING;
