INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jurassic-life-tyrannosaurus-rex-dinosaur-simulator', 87577, '2014-06-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co306m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/cktvzedqvnamzzfhc8ub.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Life: Tyrannosaurus Rex Dinosaur Simulator', 'Travel back in time to a lost world of dinosaurs and live life as a ferocious Tyrannosaurus Rex! Explore a vast prehistoric jungle filled with danger at every turn. Raise a family, hunt down food, and battle for your life against legendary dinosaurs like the Pterodactyl, Triceratops, Velociraptor and many more! You''ll need to maintain your health, hunger, thirst and energy if you''re going to survive in a hostile prehistoric jungle! Use your powerful jaws, ferocious roar, and swift speed to catch a tasty snack and fight dangerous foes! Find a mate to bond with and raise your very own family of dinosaurs to help you hunt! Watch your babies grow in size and assist you in combat! Gain experience by defeating other dinosaurs and level up your T. Rex family to increase their health, attack damage, and even unlock new attacks! Look to your handy survival guide for information on enemy dinosaurs, a map of the island, and a bonus fossil scavenger hunt! Your T. Rex is free to roam a massive open-world tropical island filled with dangerous dinosaurs, towering trees, and hidden treasures!' FROM games WHERE igdb_id = 87577 ON CONFLICT (game_id, language_code) DO NOTHING;
