INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drifter', 'Drifter is an open-world sandbox space trading game with a procedurally-generated galaxy 100,000 light years across made up of tens of thousands of star systems to explore and features an original soundtrack by composer Danny Baranowsky. Take on the role of a spaceship captain attempting to eke out a living among the stars by trading goods between star systems, hunting pirates for bounties, mining asteroids for valuable ore, or even becoming a pirate yourself. The choice is yours!' FROM games WHERE igdb_id = 16772 ON CONFLICT (game_id, language_code) DO NOTHING;
