INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wyv-and-keep-the-temple-of-the-lost-idol', 16847, '2014-07-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/trgersrmg6df22tuzstd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yvukjqpst2lbhjbxp0zk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wyv and Keep: The Temple of the Lost Idol', 'Take control of two rookie treasure hunters as they adventure into an ancient Amazonian temple! Use teamwork to advance through 6 fiendishly difficult puzzle worlds - from a cannibalistic pygmy village to an active volcano. Dodge poisonous darts, venomous snakes, and deadly spike traps and use dynamite to blast through crumbling walls and floors. Discover hordes of hidden treasure, challenging secret levels, and even a mythical pygmy hat salesman.  Wyv and Keep is a game of action and puzzle-solving, where up to two players guide the treasure hunters through a gauntlet of confounding puzzles in search of the legendary lost idol. The game is presented in a style that would feel right at home on the 16-bit consoles of old, with beautiful pixel art, a catchy soundtrack, and finely tuned platforming gameplay.' FROM games WHERE igdb_id = 16847 ON CONFLICT (game_id, language_code) DO NOTHING;
