INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monument Builders: Alcatraz', 'In Monument Builders: Alcatraz, oversee the construction of the most famous prison in the United States, while learning many other anecdotes along the way! Help contractor Lloyd Andrews gather the resources needed to complete work on the prison. Manage your workers skillfully to finish the levels in time, while repelling attacks from Call Palone''s hired thugs as they try to send your project to the bottom of the bay!' FROM games WHERE igdb_id = 10556 ON CONFLICT (game_id, language_code) DO NOTHING;
