INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('carp-fishing-simulator', 35329, '2014-01-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5cin.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kwq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carp Fishing Simulator', 'Carp Fishing Simulator is the most advanced, authentic fishing experience on the market. Fish from any peg on 5 venues containing Mirror Carp, Common Carp, Grass Carp, Ghost Koi,Tench, Bream, Catfish, Sturgeon, Perch, Pike & Zander. Use up to 3 rods, a Spod rod, Marker rod and bait Boat. Earn coins by catching fish. Use the coins to purchase new tackle & unlock new venues. Real Time of day - Real accurate Time of day or night. Real Dynamic weather - Changeable weather conditions taken from the real world location of the venues. Seasons - Depending on the month you fish, you''ll see seasonal changes which also affect the water/air temperature. Full character customisation (COMING SOON) - Don''t just choose a character, make your own! Real AI - Fish are all completely controlled by complex AI, They are released in to the lake and do their own thing. No behaviour is pre-programmed.' FROM games WHERE igdb_id = 35329 ON CONFLICT (game_id, language_code) DO NOTHING;
