INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kart Stars', 'Welcome to the World Karting Championships! Race through a single player campaign or go head to head with players from around the world. Feel the rush as you play through vintage, sprint and super karts in a massive 300 round world championship season. Outrun the competition and finish on the podium to earn coins, upgrade your kart, and become the World Karting Champion!' FROM games WHERE igdb_id = 234497 ON CONFLICT (game_id, language_code) DO NOTHING;
