INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ground Pounders', 'Ground Pounders is a turn-based, strategy wargame. Inspired by classic strategy games like Panzer General, and steeped in the lore of the Sword of the Stars universe, Ground Pounders offers a new generation of gamers an updated taste of turn-based strategic warfare. Best of all, you can play it cross platform between desktop machine and mobile devices.' FROM games WHERE igdb_id = 36456 ON CONFLICT (game_id, language_code) DO NOTHING;
