INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander: The Great War', 'ake Command and Secure Victory in the Great War! Commander – The Great War features a Grand Campaign covering the whole war from the invasion of Belgium on August 5, 1914 to the Armistice on the 11th of November 1918 in addition to 16 different unit types including Infantry, Cavalry, Armoured Cars.' FROM games WHERE igdb_id = 17607 ON CONFLICT (game_id, language_code) DO NOTHING;
