INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('girls-go-fashion-party', 358589, '2014-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa7kz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3xnl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Girls Go Fashion Party', 'Use your eye for detail, your dress-up skills, and your makeover know-how to get the girls to the fashion party on time. First, find any missing items scattered around the house. You''re looking for things like shoes, clothes, and make-up. Then head over to their closet and get them all gussied up—don''t forget to apply make-up! Do all of this before time''s up to get them out the door in time. It can be played on Flash archive websites nowadays.' FROM games WHERE igdb_id = 358589 ON CONFLICT (game_id, language_code) DO NOTHING;
