INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QuAaargh!!!', 'QuAaargh is a great game for developing reflex skills, speed, and perceptivity. It features 150 fun randomly generated levels and 140 unique symbols to make each iteration one-of-a-kind. Within each level the player is given a set time limit in which they have to complete the challenge put forward. So be quick and share your score with friends through online leader boards.' FROM games WHERE igdb_id = 147306 ON CONFLICT (game_id, language_code) DO NOTHING;
