INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fritz-chess-14', 17050, '2014-06-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqkm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wvhdrv1indb9wu1muwkz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fritz Chess 14', 'Fritz Chess 14 is the most comprehensive chess program in the world. Whether you are new to the game or a Grandmaster, FRITZ 14 is suitable for all skill levels. The top-ranked Fritz Chess engine adjusts its playing strength automatically, offers coaching at all levels, explanation of chess positions, color coded danger warnings, openings statistics, automatic game analysis and training modules for openings, tactics and endgames. Whether you’re a chess beginner, club player or professional Grandmaster, Fritz Chess 14 has it all! Take your game into the cloud at playchess.com and enter a virtual world of chess where players of all abilities can play and train using revolutionary new functions! -- not to mention a database of over 1.5 MILLION games! JOIN THE COMMUNITY! Take advantage of “Let’s Check,” a database of over 200 Million extensively analyzed positions. This is a revolutionary new feature that allows players to join a giant, worldwide, community knowledge base for chess. Whenever you analyze a position in depth FRITZ 14 can send the main line and evaluation to a central server, to be shared by all participating users. Get deep analysis instantly for almost every position you analyze by the finest chess engines, running on the most powerful machines around. You will see the analysis of different chess engines and compare their results in the blink of an eye! This feature is available until December 31, 2015. FRITZ CHESS 14 offers chess players all the world class tools they need to study, train, and play: a new and more powerful chess engine, a further enhanced ergonomic interface, detailed 3D boards and graphics, engine management, adjustable playing strength, coach functions, move explanation, game analysis and commentary, training modules for openings, tactics and endgames.' FROM games WHERE igdb_id = 17050 ON CONFLICT (game_id, language_code) DO NOTHING;
