INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monzo-digital-model-builder', 115192, '2014-11-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1j97.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monzo: Digital Model Builder', 'Interactive digital model kits MONZO is a Game Connection Award winner in The Excellence In Art category. Monzo brings you the best in models from Revell. With Monzo you can take your real-life Revell models to digital form, working them into design variations that reflect the power of your own creativity. Easy sharing of your models via social media gives you the opportunity to show off your Revell collection to all your friends. MONZO is about discovery and adventure. It is more than model kit construction simulation. In MONZO you can build a model directly on your mobile device, providing the joy of model creation with an appeal that speaks to a broad audience of users, spanning from children to adults. With MONZO, everybody can easily build simple or complex models like cars, planes, machines, weapons, animals etc.' FROM games WHERE igdb_id = 115192 ON CONFLICT (game_id, language_code) DO NOTHING;
