INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psichodelya', 'Psichodelya pays homage to old-school style top-down shmups (shoot-em-up’s) such as DoDonPachi, Ikaruga, Espgaluda, R-Type Delta, Aero Fighters, Giga Wing, Raiden, and more recent Jamestown. Players control one of 3 playable ships - dodging bullets and destroying wave after wave of enemies for points in either single or 2 player local coop modes. There are 5 manic levels, each with an epic boss and 5 difficulty levels.' FROM games WHERE igdb_id = 17406 ON CONFLICT (game_id, language_code) DO NOTHING;
