INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titan Souls: Digital Special Edition', 'Titan Souls is an indie action-adventure game centered around battling powerful bosses in a minimalist world. Players are equipped with a single arrow and one hit point, emphasizing precision, timing, and strategic movement. The game features pixel-art visuals, atmospheric environments, and a focus on trial-and-error gameplay. The Digital Special Edition includes: the base game, a digital artbook, a world map, the original soundtrack, and desktop backgrounds.' FROM games WHERE igdb_id = 53807 ON CONFLICT (game_id, language_code) DO NOTHING;
