INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pitiri 1977', 'Pitiri 1977 is an adventure-platformer with much exploration in both world and story, and is paying tribute to its classic pioneers – not only by its gameplay, but also by its background story. A narrative, that is set in 1977 (the glorious year of Star Wars IV, the Atari 2600, the Voyager One spacecraft & Led Zeppelin''s “Presence”), in an imposing world, created by using hand-painted graphics, characters, solid physics and a 1970s soundtrack, gradually opened up by the player’s acquired abilities. You play as a kid with supernatural powers, whose brother has been kidnapped by an unknown evil. On your quest to get your brother back, you venture through a twisted 70s science fiction utopia that lies beyond the known…' FROM games WHERE igdb_id = 17513 ON CONFLICT (game_id, language_code) DO NOTHING;
