INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Club Nintendo Picross Plus', 'Club Nintendo Picross Plus is a Japan-only Nintendo 3DS eShop Picross title, sequel to Club Nintendo Picross. It is very similar to its predecessor, featuring all the original content from the first, as well as being packed with over 100 new puzzles. The game could only be downloaded through the Club Nintendo rewards program.' FROM games WHERE igdb_id = 165121 ON CONFLICT (game_id, language_code) DO NOTHING;
