INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contract Killer: Sniper', 'You are a master assassin, hired to infiltrate secure locations and eliminate high-profile targets. Perform lethal strikes and follow your only rule: Honor The Contract.  A new threat as appeared! Cyborgs and Mechanized Combat Units are invading cities around the world. Behind this nefarious act is a secret military organization which have been kidnapping scientists for use in developing their once-secret nanocrystal technology, which is at the heart of their cybernetic augmentation project. You have been hired to push back this invasion, at all costs!' FROM games WHERE igdb_id = 127049 ON CONFLICT (game_id, language_code) DO NOTHING;
