INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heileen 2: The Hands Of Fate', 'The game picks up directly after the end of the first game taking place on a mysterious Caribbean island where Heileen was shipwrecked with her friends. Heileen soon discovers a deck of tarot cards representative of the seven deadly sins and the seven heavenly virtues. The cards have the power to change both her dreams and her reality, and will help Heileen discover many hidden things from her past, and ultimately what she wants to be? A saint, or a sinner?' FROM games WHERE igdb_id = 17507 ON CONFLICT (game_id, language_code) DO NOTHING;
