INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('all-guns-blazing', 344863, '2014-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9uis.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwxja.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Guns Blazing', 'Pull the trigger on All Guns Blazing! Crime isn''t a game, it''s a way of life - so grab the all new social 3D crime shooter that will blow you away! Climb the criminal ranks, join a cartel and smash the competition. Create or join cartels to take down tough Raid bosses and attack other players'' bases in PvP mode - America is yours for the taking! Raid banks, armored cars and businesses to steal cash, gold, anything and everything of value. Use what you''ve stolen to build your own criminal empire. You want guns, you want property and you want to look good doing it! Start out small and expand until you''ve taken over the entire US and attack other players'' safehouses in Mexico. You''ll need help, so join a criminal Cartel with other players and help each other towards that one big score. Work together to take down mob bosses, destroy businesses and ensure your domination. There''s only room for one at the top - make sure that''s you and your cartel!' FROM games WHERE igdb_id = 344863 ON CONFLICT (game_id, language_code) DO NOTHING;
