INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ai-war-destroyer-of-worlds', 8890, '2014-08-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ajnwjhue4vfirmcfy5lm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sca5wh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AI War: Destroyer of Worlds', 'Go forth into the galaxy, steal AI technology, recapture those planets you must in order to achieve your ends, and save what remains of humanity. But draw too much attention to yourself, and the full might of the AI overlords will come crashing down. The inattention of the larger AI is our only hope: a small resistance, too insignificant even to be noticed by the AI central command, has survived. These are the forces you will command. The AI subcommanders will fight you to the death when they see you -- but your glimmer of opportunity comes from quietly subduing those subcommanders without alerting central processing to the danger until it''s too late.' FROM games WHERE igdb_id = 8890 ON CONFLICT (game_id, language_code) DO NOTHING;
