INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mibibli''s Quest', 'Mibibli''s Quest is a retro-style surrealistic platformer game. Join Mibibli as it blasts his way through over 20 crazy and eclectic levels! Conquer caves, dance through raves, wander the suburbs, and blow up eggs... travel through time and explore your nightmares along the way! Collect power ups and find the secrets that are scattered throughout this world.' FROM games WHERE igdb_id = 33229 ON CONFLICT (game_id, language_code) DO NOTHING;
