INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bouncing Slime: Impossible Levels', 'Do you live for the big challenge? Play thIs new amazingly addicting game and its impossible levels! It is deceivingly simple: just one control. Tap the screen to jump, guide your green slime over spikes and jump on platforms to get to the end of the level. Be careful, any mistake will result in instant death and a respawn at the beginning of the level.' FROM games WHERE igdb_id = 343985 ON CONFLICT (game_id, language_code) DO NOTHING;
