INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Land: Minigame Mayhem', 'Mario Land: Minigame Mayhem is a fan made game based on Mario Party minigames. Features: - Over 80 Minigames to discover and complete to test your wits, timing and skill! - Playing Minigames costs coins. Earn coins by completing Minigame and spend them on other games or cosmetic items! - Dozens of Achievements to unlock by completing various challenges! - Compete with other players for online high scores! - Buy outfits to style yourself in both Minigames and The Overworld! - Spend coins on over 60 different figurines! - Play Mario-styled versions of classic Arcade games such as Frogger, Space Invaders or even Tetris! - Listen to dozens of classic, Super Nintendo tunes from various Mario games! - Keep up to date with the Updater that will let you know when new content is available!' FROM games WHERE igdb_id = 134958 ON CONFLICT (game_id, language_code) DO NOTHING;
