INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '100% Hidden Objects 2', 'In an exciting journey around the world, 100% Hidden Objects 2 offers you picturesque hidden-object scenes just waiting for your keen eye to spot all the clues within them. Whether you prefer to play in classic mode with a checklist, or would like to track down the objects using pictograms 100% Hidden Objects 2 provides pure hidden object fun!' FROM games WHERE igdb_id = 177071 ON CONFLICT (game_id, language_code) DO NOTHING;
