INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poptropica: Forgotten Islands', 'Climb aboard your almighty blimp and explore the vast uncharted islands of Poptropica. Steer clear of hazards and discover exotic islands beneath the clouds. Take to the islands and embark on quests while discovering the secrets of Poptropica’s past, one artifact at a time. Poptropica: Forgotten Islands on Nintendo 3DS is an adaptation of the popular virtual world for kids. Customize your avatar and travel on foot or by blimp across multiple islands. Collect artifacts and other items and discover the mystery of the Forgotten Islands!' FROM games WHERE igdb_id = 85348 ON CONFLICT (game_id, language_code) DO NOTHING;
