INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game Over Gopher', 'Hungry space gophers are after the prized carrot. Defend the carrot by placing units on a coordinate grid. Game Over Gopher is Common Core-compliant and addresses topics such as plotting coordinate pairs, differentiating negative coordinates from positive coordinates, and identifying the four quadrants. A finalist in the 2012 Serious Games Showcase & Challenge and gold winner in the 2013 International Serious Play Awards.' FROM games WHERE igdb_id = 336924 ON CONFLICT (game_id, language_code) DO NOTHING;
