INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Will Escape', 'You are Brian Lowfield, you awaken on the cold floor of a prison cell with no recollection of what happened in the past 24 hours. You''ve lost your memory and you''re completely stripped from your gear. On the floor, you find a picture of a young girl. You don''t know who she is, yet she looks familiar to you. You have no idea what''s going on, but one thought strongly resounds in your mind: I Will Escape!' FROM games WHERE igdb_id = 17862 ON CONFLICT (game_id, language_code) DO NOTHING;
