INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic Space: Online', 'Epic Space is a Third Person Action MMO featuring unique voice communication, emergent gameplay, and twitch-based combat on a single shard. There is one persistent sandbox/universe, shared by the entire world. Players earn reputations for completing orders, securing objectives, recon and team play.' FROM games WHERE igdb_id = 36322 ON CONFLICT (game_id, language_code) DO NOTHING;
