INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Shooter 2', 'Dungeon Shooter 2 combines a bullet hell shooter with random monster spawns, and random level generation to create a fun and challenging experience. You are in a dungeon full of monsters, zombies, troopers, and turrets. Your goal is to find the key to get out while killing and looting to survive. No worries though ‘Murcia Mart has a convenient store location for all your weapon and ammo needs.' FROM games WHERE igdb_id = 36082 ON CONFLICT (game_id, language_code) DO NOTHING;
