INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2x0ng', 'Pronounced "TOO-zong", 2x0ng is a fun puzzle game, the sequel to Xong. Match colors to unlock new areas of each procedurally generated level while defeating enemies with your bouncing Squareball.' FROM games WHERE igdb_id = 342039 ON CONFLICT (game_id, language_code) DO NOTHING;
