INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drag Racing: Club Wars', 'Addictive! Play the Best Racing Game on Google Play, Makes a Great Time Killer - Not too Boring and Doesn''t have Too Many Ads.  Hit the Drag Strip with Race Clubs battling for Territory, Gold and Glory!  The best racing game that launched the legendary Creative Mobile Drag Racing series returns with new features, improved graphics and expanded game play. Supercars? Check. Street Racers? Check. Classic muscle? You bet!' FROM games WHERE igdb_id = 51480 ON CONFLICT (game_id, language_code) DO NOTHING;
