INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Souls II: Webhallen Edition', 'Dark Souls II: Webhallen Edition is a special edition of Dark Souls II, released exclusively by the Swedish retailer Webhallen. This edition is limited to only 740 pieces. This edition comes in a numbered bag and metal case includes the following: - Limited Dark Souls Hood - 30cm tall Warrior Knight Figurine - Limited Ring in a pouch and engraved text “Go Beyond Death” - Official Soundtrack CD - Authentic Cloth Game Map - Collectible hardbound artbook' FROM games WHERE igdb_id = 42996 ON CONFLICT (game_id, language_code) DO NOTHING;
