INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Rings III', 'The newest addition to the popular mobile RPG series is finally here! Chaos Rings III is a full-scale RPG series for smartphone devices as part of a continuing series. The rich game world, deep storyline, and high-quality soundtrack have been praised throughout the world. Unexplored lands, hidden treasures, monsters, legends... everything an adventurer could want could be found on this one planet. Worlds yet undiscovered, treasures that fulfill your wildest dreams, mythologies lost in the pages of history... a great journey, the dream of a thousand years, is about to begin.' FROM games WHERE igdb_id = 39228 ON CONFLICT (game_id, language_code) DO NOTHING;
