INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Journey', 'Embark on a magical journey in this addictive Mahjong Solitaire adventure!  Enjoy a new take on Mahjong Shanghai as you help a young girl and her grandfather traverse the globe in search of her lost parents. Make your way by pairing tiles in order to dismantle hundreds of layouts. Collect achievements for special accomplishments while taking advantage of innovative gameplay twists like Shuffle, which allows you to get out of a difficult situation, or Firecracker, a tool for blowing up multiple pairs of tiles. Visit the Forbidden City, Virupaksha Temple, the Taj Mahal and the famous Mount Fuji as you fulfill challenging quests and earn gold stars for completing levels as fast as you can!' FROM games WHERE igdb_id = 88898 ON CONFLICT (game_id, language_code) DO NOTHING;
