INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gran Turismo 6: Anniversary Edition', 'Gran Turismo 6 is a racing video game and the sixth main installment—and twelfth overall entry—in the Gran Turismo series. New features include the addition of more cars and tracks, enhanced car customization options, and partnerships with the Goodwood Festival of Speed, the Ayrton Senna Institute, the FIA, and NASA. In the United States, the Anniversary Edition was available exclusively through GameStop and included: - 5 cars featuring special liveries and performance enhancements - Custom paint chips, race suit, helmet, and in-game avatars In the United Kingdom, the Anniversary Edition was offered exclusively through GAME and included: - A Steelbook case - 20 cars with special liveries and performance enhancements - 1 million in-game credits - Apex II game guide app (e-book) - Custom paint chips, race suit, helmet, and in-game avatars' FROM games WHERE igdb_id = 43031 ON CONFLICT (game_id, language_code) DO NOTHING;
