INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shape-up', 20312, '2014-11-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22tw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzzx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shape Up', 'Exclusive to Xbox One, Shape Up combines a foundation of proven fitness methods with entertaining and rewarding workout routines displayed in a unique arcade style. Each of the three game modes keeps players engaged and motivated with quirky, points-driven fitness challenges. Using the Kinect camera, players will have a head to toe image of themselves projected into the game which will aid in keeping track of their workouts and calories burned each session. The innovative online mode uses rePLAY technology to push gamers to never work out alone. Shape Up is set to revolutionize fitness games by proving that the more fun you have while working out, the longer you’ll stick with it to achieve better results.' FROM games WHERE igdb_id = 20312 ON CONFLICT (game_id, language_code) DO NOTHING;
