INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Mix', 'Based on the infamous game described on the popular creepypasta of the same name. Mr. Mix from Castilan Games  is a faithful recreation of the mysterious typing game for PC. On Mr. Mix from Castilan Games  you can either challenge the practically impossible original game mode or play the hacked game mode so you can reach the ominous level 6.' FROM games WHERE igdb_id = 276278 ON CONFLICT (game_id, language_code) DO NOTHING;
