INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Puttz', 'Word Puttz is a hybrid word-tile and mini-golf puzzle game developed by Jackbox Games. Players progress through levels by creating crossword-style words on a grid, aiming to reach a designated goal marked as a golf cup. The game features a character named Octoputtz—an octopus—who operates themed mini-golf courses that introduce various gameplay elements such as environmental obstacles and unconventional challenges. As players advance, they can earn stars, interact with in-game objects like mollusks, and unlock additional stages or worlds.' FROM games WHERE igdb_id = 361232 ON CONFLICT (game_id, language_code) DO NOTHING;
