INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sengoku Basara 4', 'Sengoku Basara 4 is the latest entry to the Sengoku Basara series by Capcom and was released for the PlayStation 3 on January 23, 2014. The game focuses on the theme of Sengoku Genesis and centers around the beginning of the Sengoku Period. There is also an expansion to the game called Sengoku Basara 4 Sumeragi.  For this entry in the series, character design was passed to Tooru Ookubo, chief designer for the anime series, instead of series standby Makoto Tsuchibayashi.' FROM games WHERE igdb_id = 63628 ON CONFLICT (game_id, language_code) DO NOTHING;
