INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puyo Puyo Fever Rhythm', 'Puyo Puyo Fever Rhythm was a rhythm mobile puyo game released in 2014 through the PuyoSega service which used music and assets from Puyo Puyo Fever, Puyo Puyo Fever 2, Puyo Puyo 15th Anniversary and Puyo Puyo 7. The service ended on December 28, 2015 and music downloads for those that owned it ended on January 28, 2016.' FROM games WHERE igdb_id = 252126 ON CONFLICT (game_id, language_code) DO NOTHING;
