INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MH17 Strikes Back', 'MH17 Strikes Back was a controversial game on the Google Play store which was released shortly after the Malaysia Airlines Flight 17 tragedy. The game was a simulation of the flight which was shot down by Russian separatist forces. The game has since been delisted from Google Play after backlash from various news outlets with no known archives, currently making it lost media.' FROM games WHERE igdb_id = 329375 ON CONFLICT (game_id, language_code) DO NOTHING;
