INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronicles of Arcadia', 'Chronicles of Arcadia is a free-to-play fantasy MMORPG where your journey is shaped by the choices you make. Dive into a vast world of magic and mystery, conquer challenging dungeons, and fight alongside others in epic battles. With a flexible dual class system, constant updates, and a passionate community, it’s a game built for adventurers seeking both nostalgia and fresh discoveries.' FROM games WHERE igdb_id = 123541 ON CONFLICT (game_id, language_code) DO NOTHING;
