INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liquid Rhythm', 'Liquid Rhythm is a wildly innovative beat generator, sequencer, and software MIDI controller. It''s powered by a rhythm synthesis engine that gives you instant access to quadrillions of rhythmic patterns that can be manipulated with a comprehensive suite of MIDI effects called Molecule Tools. Paint drum patterns using a palette of note clusters that provide new visualizations for MIDI data, make beats using multi-sample drum instruments or your own samples, and run it standalone or integrate into your workflow through VST/AU/RTAS/Max for Live.' FROM games WHERE igdb_id = 16826 ON CONFLICT (game_id, language_code) DO NOTHING;
