INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knighttron', 'The hero wakes up in a world of infected dark magic and cannot remember anything, including his own name. Guide the hero in his journey to recover his memories while battling through hordes of aggressive enemies. Fight, trade, loot and complete quests to enlist the support of new allies. Who knows what secrets lay hidden in this world? Enjoy hours of exciting gameplay in this curious world of both might & magic. Control parties of up to three characters in this turn-based strategy adventure!' FROM games WHERE igdb_id = 314755 ON CONFLICT (game_id, language_code) DO NOTHING;
