INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pachislot Akumajou Dracula', 'Pachislot Akumajou Dracula is a pachislot game created by Konami Parlor Entertainment. Its aesthetics are based on Castlevania: Curse of Darkness and features most of its cast, including Trevor Belmont in the leading role. The game functions like a slot machine but also features cinematic scenes. A sequel, Pachislot Akumajou Dracula II, was released in 2010. It features much the same cast as the original game, which is based on the cast of Castlevania: Curse of Darkness and Castlevania: Lament of Innocence. It was followed by Pachislot Akumajou Dracula III in 2012. It features much of the cast of Castlevania III: Dracula''s Curse, including Trevor, Alucard, Sypha, Succubus, Doppelganger and Dracula.' FROM games WHERE igdb_id = 315523 ON CONFLICT (game_id, language_code) DO NOTHING;
