INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jockey-grand-prix', 47597, '2014-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3mus.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jockey Grand Prix', 'This game was released around 2001 and is basically a horse race betting game. Bets are placed just prior to the start of the race, different horses have different odds, and then the race begins. Some rather impressive Motion Capture graphics were used for the animation of the horses. After the race is over the winning horse is declared in a slow motion photo finish and the winning bets are paid. Again, the game can be set to "pay out" to either an installed coin hopper, or through a "credit" re-imbursement system set-up by the location or the operator. The Jockey Grandprix cartridge came complete with a harness cable and settings explanation sheet for just that purpose.' FROM games WHERE igdb_id = 47597 ON CONFLICT (game_id, language_code) DO NOTHING;
