INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Long Night', 'Long Night is a Third Person Survival-Horror video game series which aims to reconnect with the atmosphere of its ancestors, the old classics from the 90''s and early 2000 With this game Trickster Face wants to put Lurking Fear back to the center of the gaming experience, rather than pure action sustained by an escalation of noisy special effects. Here we have no shot guns nor giant monsters, but simply David, a youngster who can only count on your pugnacity and your instinct, to survive, and save his friends.' FROM games WHERE igdb_id = 16941 ON CONFLICT (game_id, language_code) DO NOTHING;
