INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wasteland 2: Director''s Cut - Digital Classic Edition', 'From the Producer of the original Fallout comes Wasteland 2, the sequel to the first-ever post-apocalyptic computer RPG. The Wasteland''s hellish landscape is waiting for you to make your mark... or die trying. With over 80 hours of gameplay, you will deck out your Desert Ranger squad with the most devastating weaponry this side of the fallout zone, test the limits of your strategy skills, and bring justice to the wasteland.' FROM games WHERE igdb_id = 124999 ON CONFLICT (game_id, language_code) DO NOTHING;
