INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('extreme-roads-usa', 16962, '2014-05-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jvp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/a93od0zvpw9xkxgdevau.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Roads USA', 'Off you go! Get ready for trucking challenges that will keep you on the edge of your seat as you hitch up and haul your way across the ‘extreme roads’ of this massive map and unforgiving terrain. Accept your assignments, select your trucks, and transport all sorts of goods along the toughest routes on their matching trailers. Earned cash can be spent on new trucks and their tuning – the investment will be worthwhile. Proceed to modify your truck visually (including logos and license plates). The customization can be extended with your own pictures for door logos, license and window plates. Same goes for the in game radio – enjoy a country music soundtrack or your very own playlist. Manhandle menacing road passages and cross demanding country sides and hill ranges. Each truck and every trailer offers unique function and handling designed to boost your driving skills. Progress and collect all the achievements. Test your nerves, put it all on the line, and determine if you have what it takes to become ‘king of the road.' FROM games WHERE igdb_id = 16962 ON CONFLICT (game_id, language_code) DO NOTHING;
