INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Once Upon A Life', 'In Once Upon A Life you play as Harry and in the game you collect the precious memories from your scrapbook (which got blown away at the start of the game). Harry has two walking sticks that have rockets in them, allowing you to temporarily fly. Each level has some small puzzles that you need to solve to get the memories. As you collect the memories you learn about Harry''s life.' FROM games WHERE igdb_id = 115656 ON CONFLICT (game_id, language_code) DO NOTHING;
