INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sally.Exe', 'Ready for Round 2? Sally.Exe - The Game is finally here! Following the success of it''s spiritual predecessor, the fanmade follow-up to the legendary Sonic.Exe creepypasta is now brought to life. There''s no stopping...''him''. ''It''. That...''thing''. Call it what you may, it won''t matter. Evil is coming. It''s little game is far from over. And you''re next.' FROM games WHERE igdb_id = 274050 ON CONFLICT (game_id, language_code) DO NOTHING;
