INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Egg Knight', 'Save the Egg Knight world by defeating the Dark Army!  Assemble your troops by collecting Knights that hatch from eggs! What Knight will you get?  A bold Miner Knight? A humble Farmer Knight? Or a mysterious Witch Knight? Or someone else?  Each Egg Knight is born with unique talent, from a dragon-born Farmer Knight to a ninja Farmer Knight!  Go collect all the Egg Knights!' FROM games WHERE igdb_id = 119425 ON CONFLICT (game_id, language_code) DO NOTHING;
