INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '6 Takes!', '6 Takes! - Wolfgang Kramer''s ingeniously simple card game with "bullheads". The aim of the game is to avoid getting cards. The player with the fewest bullheads at the end of the game is the winner. It sounds easier than it is, players will need some great tactics and perhaps a little luck.' FROM games WHERE igdb_id = 167498 ON CONFLICT (game_id, language_code) DO NOTHING;
