INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Doves', 'Endless Doves – Collect Doves, Don''t Crash! He dreams of flying...Who is he? Why does he crash? How does he fly? That doesn''t matter! What does matter is obsessive bird collecting!! Collect those birds and beat the scores of friends and people you don''t even know! Brag on the usual usual social network hangouts then collect even more birds and do it all over again!' FROM games WHERE igdb_id = 380641 ON CONFLICT (game_id, language_code) DO NOTHING;
