INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Global Outbreak: Doomsday Edition', 'Take control of Blackhorne Industries, an international private military contractor. When the world is hit by a sudden and unexpected meteor shower that unleashes a deadly pathogen, Blackhorne are called in to clean up the mess. Can you lead your elite troops to victory before the mysterious meteorites destroy life as we know it? The fate of the world rests in your hands!' FROM games WHERE igdb_id = 30254 ON CONFLICT (game_id, language_code) DO NOTHING;
