INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Traders: 4X Empires', 'Take command of humanity’s last survivors and rebuild an empire among the stars. In this immersive turn-based strategy game, you must lead the refugees of the great Exodus to a new home in hostile space and build a new galaxy-spanning civilization. To survive in the dark reaches of space, you will have to fight to protect your people, control rival factions, and unlock lost technology.' FROM games WHERE igdb_id = 36124 ON CONFLICT (game_id, language_code) DO NOTHING;
