INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cricket Captain 2014', 'Cricket Captain is back for the 2014 season, with a beautiful new interface, updated 3D graphics engine, and all the attention to detail that you expect from the series.  Cricket Captain has been hailed as the best cricket management simulation every created, and with one of the most exciting cricket seasons for a decade in prospect, it’s about time you took control.' FROM games WHERE igdb_id = 10113 ON CONFLICT (game_id, language_code) DO NOTHING;
