INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D.W.A.R.F.S.', 'D.W.A.R.F.S. is an abbreviation for Dapper Wacky Although Rather Fierce Squad. Welcome to the Magic Forest! Whenever there is trouble, every single animal, big or small, can count on the dwarves’ help. Although it may seem like the squad prefers relaxation to work, the dwarves are the greatest rescue unit in the Magic Forest, and they are always ready for action!' FROM games WHERE igdb_id = 36414 ON CONFLICT (game_id, language_code) DO NOTHING;
