INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul Guardians: Age of Midgard', 'Hack, slash and dispatch a barrage of attacks as you and the Soul Guardians protect Midgard from the Demon Army uprising. An intensive action RPG meets card collecting, choose to quest through single player dungeons or engage in co-op and PVP arenas with friends. Collect Soul Art Cards to evolve and fuse in order to construct extraordinary attacks!' FROM games WHERE igdb_id = 39177 ON CONFLICT (game_id, language_code) DO NOTHING;
