INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solar Struggle', 'Solar Struggle is an arcade action spaceshooter where the player takes control of one of the nine space ships and experiences a thrilling story of a young pilot in 11 missions or asserts herself/himself against tons of enemies in the skirmish mode. The whole game world is in 3D, but the action takes place on a 2D plane which makes the action and controls really easy.' FROM games WHERE igdb_id = 17984 ON CONFLICT (game_id, language_code) DO NOTHING;
