INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroine''s Quest: The Herald of Ragnarok', 'A Heroine must stand against the forces of frost and put an end to the lasting winter. Her might, sorcery, and cunning may be humanity’s last resort. Heroine''s Quest: The Herald of Ragnarok is a retro styled adventure/RPG hybrid with atmosphere and spirit reminiscent of the classics. Are you up to the task, or will you die trying?' FROM games WHERE igdb_id = 36441 ON CONFLICT (game_id, language_code) DO NOTHING;
