INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turkmenchay', 'The game "Turkmenchay" is a historical first-person shooter that tells the story of the historical events of the Qajar period and the battles of Prince Abbas Mirza and his companions with the Tsarist Russian forces. The game has various mechanics such as sailing and controlling heavy weapons such as cannons and machine guns. The game is designed based on real historical events and characters.' FROM games WHERE igdb_id = 362858 ON CONFLICT (game_id, language_code) DO NOTHING;
