INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return to Melanat', 'Return to Melanat is a King''s Field fangame. Is an attempt to recreate the environments of King''s Field 2 in a whole new light, while delivering an entirely new story. Like all King''s Field games, its gameplay centers around exploration, methodical combat, and light puzzle solving. All seven areas of Melanat are recreated to scale using nothing but the SOM toolset and very few custom resources.' FROM games WHERE igdb_id = 171785 ON CONFLICT (game_id, language_code) DO NOTHING;
