INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swamp Defense 2', 'Swamp Defense 2 is a classic tower defense game with unique weapons and monsters as enemies for any beginner or defensive specialists. Fight countless enemies with a huge selection of gun turrets (in the form of comic heroes) and additional helpers (mines, air support, block wall) on more than 60 maps. Earn coins to obtain improvements in the integrated shop system and to buy new towers.' FROM games WHERE igdb_id = 112113 ON CONFLICT (game_id, language_code) DO NOTHING;
