INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Piercing Fortress Europa', 'Piercing Fortress Europa is an operational wargame from veteran game designer Frank Hunter, which covers the campaigns of the Western Allies from July, 1943 through the end of April, 1945 in Sicily and Italy. Each area has its own map and time scale to best represent the campaigns for Sicily and Italy and the player is offered complete freedom, limited only by a historical order of battle and logistics model, to plan his operations and explore all of the many “what ifs” that the Italian theater has to offer. Tour Italy… with an Army!' FROM games WHERE igdb_id = 129591 ON CONFLICT (game_id, language_code) DO NOTHING;
