INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senjou no Waltz', 'Senjou no Waltz tells the story of village girl Ran, who obtained massive power from a cursed magic sword after losing her parents and hometown. She ended up at an ultranationalistic military school known as Nirvana. It was a unique school, a country in its own right gathering boys and girls that excelled in combat.' FROM games WHERE igdb_id = 61940 ON CONFLICT (game_id, language_code) DO NOTHING;
