INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rex Hightower and the Unicorn''s Kiss', 'You are Rex Hightower. You fucked a dragon once. Saved the kingdom. But now your dick shoots fire and that''s not really working for you. In this interactive fiction that had players laughing their asses off, Rex stumbles through the woods to find his way back to a normal life. Please consider donating, I need money to replace all these people''s asses.' FROM games WHERE igdb_id = 128675 ON CONFLICT (game_id, language_code) DO NOTHING;
