INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bayonetta-2-bonus-edition', 51154, '2014-11-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5rc2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bcy52hj11wopd02u0ukn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bayonetta 2: Bonus Edition', 'Bayonetta 2 is an action hack and slash video game developed by Platinum Games and published by Nintendo for the Wii U, with Sega as the franchise owners serving as its advisor. It is the direct sequel to the 2009 game, Bayonetta, and was directed by Yusuke Hashimoto and produced by Atsushi Inaba, under supervision by series creator Hideki Kamiya. It was announced on September 13, 2012, and will be exclusive to the Wii U, unlike the previous game which was only available on the PlayStation 3 and Xbox 360. The titular character, Bayonetta, sports a new costume and hairstyle and the game itself features a new two-player mode. The game is also the second Bayonetta product to receive Japanese voiceovers, using the same cast that voiced the Bayonetta: Bloody Fate anime film by Gonzo. The game was released in September 2014 and includes a port of the original Bayonetta as a separate disc inside the case. Also Available Bayonetta 2: Bonus Edition Bayonetta 2: Special Edition Bayonetta 2: First Print Edition Disc versions of both Bayonetta and Bayonetta 2, an art book, exclusive embossed packaging.' FROM games WHERE igdb_id = 51154 ON CONFLICT (game_id, language_code) DO NOTHING;
