INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('true-love-sweet-lies', 238887, '2014-04-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co66g8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclfk6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'True Love Sweet Lies', 'You are working as a freelance photographer when you run into a gorgeous reporter at the news agency. Could this be the blossoming of new love…? Or is he really just after one of your photos!? All of those sweet nothings whispered in your ear, all of those delicate kisses… Was it all just part of their elaborate lie!? Meanwhile, lurking in the shadows, the Tokyo underground is after that photo… and your life!' FROM games WHERE igdb_id = 238887 ON CONFLICT (game_id, language_code) DO NOTHING;
