INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nunchuck Charlie: A Love Story', 'It was just another afternoon in the Nunchuck-household when suddenly Mr.Teddington, Charlie''s life-comrade and teddy bear, gets taken away from him! Fueled by love, sorrow and guilt Charlie embarks on a journey down the Wishingwell of Forbidden Wishes, battling his way through egg-hatched-security-guard-bears, flesh-eating-mullets and pigeon-laser-farts. A journey to test the toughest man''s strength and intelligence. A journey that will uncover what might be best unknown.' FROM games WHERE igdb_id = 286611 ON CONFLICT (game_id, language_code) DO NOTHING;
