INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pentaction: Medieval', 'Pentaction: Medieval is a turn-based strategy board-game about chance and skill on the battlefield. Take control of your army in combat, annihilate your foe’s troops or capture their King to win. Play the enhanced Tactical game style for the ultimate strategic experience or jump straight into the action in quick battle. Challenge your friends in hotseat multiplayer or take on the AI in solo play. Do you have what it takes to lead your Kingdom to victory?' FROM games WHERE igdb_id = 174247 ON CONFLICT (game_id, language_code) DO NOTHING;
