INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweezy Gunner', 'Welcome to the crazy world of Sweezy Gunner! An eye melting, brain bending, mouse squeezing 2D Shoot em up. Are you hungry for action? Do you crave intense mayhem? The objective is simple, find out what killed the human terrafromers and destroy it. Thats what you were brought in to do and its what you do best. Landing on Terrafort is just the beginning.' FROM games WHERE igdb_id = 17306 ON CONFLICT (game_id, language_code) DO NOTHING;
