INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Spy: Find Hidden Objects', 'You think you can hide everything from me? Come on, man! No information can escape from my shrewd eyes. ''Cause I''m TINY SPY! In Tiny Spy, information is hidden in the unknown corners of the rooms. Challenge your brain to search for clues, solve puzzles and find the information out. 36 missions are prepared to knock you down. Ready for the challenge?' FROM games WHERE igdb_id = 344215 ON CONFLICT (game_id, language_code) DO NOTHING;
