INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('drakerz-confrontation', 16876, '2014-05-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2pzj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/n9g1gywofrwbgwzmwlio.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drakerz: Confrontation', 'Most other TCG play either with "virtual" cards or with "real" cards ( paper ). With DRAKERZ-Confrontation, you will enjoy the best of both gaming experiences in playing with your "real" premium cards , you will experience new sensations , halfway between the board game and tactical game cards. The calculation points and the cost of cards, entirely managed by the computer allows you to stay focused on the basics: the fight. As your virtual cards (no need to camera), they are accessible from your account on any connected computer. DRAKERZ: Confrontation is an online game where players from around the world embody Drakerz , the riders of Drakos . Alongside these mythical creatures, half-dragon, half- chimera, players compete in epic duels to register their name in the legend of Oniris , the dream world.' FROM games WHERE igdb_id = 16876 ON CONFLICT (game_id, language_code) DO NOTHING;
