INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond Space', 'Beyond Space is a cutting-edge 3D space shooter game that immerses players in the darkest plots in a similar vein to the best Space Operas. Scores of planetary systems, nebulas and asteroid fields to explore. Fully detailed 3D Graphics, mesmerizing, beautifully painted spacescapes, spectacular special effects, and rendered glows, lights, sun flares and reflections. All of which intensified with an ambient yet dynamic soundtrack and great sound effects.' FROM games WHERE igdb_id = 10044 ON CONFLICT (game_id, language_code) DO NOTHING;
