INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantom Rift', 'The Phantom Rift: a dark, ethereal world filled with mystery and powerful magic. You don''t know how or why you are there, only that you must find a way back to the True World at any and all costs... Phantom Rift is an adventure/RPG with a unique battle system (inspired by Mega Man Battle Network), hundreds of spells to collect and use, endless equipment combinations to customize your wizard with, and much more. Explore a vast over world, interact with ethereal wisps, take on side quests, journey through dungeons, collect loot, and take part in skill based, strategic battles!' FROM games WHERE igdb_id = 174351 ON CONFLICT (game_id, language_code) DO NOTHING;
