INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corto Maltese: Secrets of Venice', 'Let''s set off in the footsteps of Corto Maltese! Along Venice''s canals and narrow alleys, fight against a poison that ravages you, avoid bullets and explosions, face the unknown, and eventually open the doors of knowledge. This video game unravels a thrilling quest based on point and click riddle-driven gameplay within the worlds of Corto Maltese, the main character created by Hugo Pratt, the genius of graphic novels (more than 5 Million hardcopies sold worldwide). Searching for a fabulous emerald, you may find a magical balance and finally, utopia.' FROM games WHERE igdb_id = 8386 ON CONFLICT (game_id, language_code) DO NOTHING;
