INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal School 1st Grade Games', 'Help your animal friends through 100 challenges across 40+ first grade levels in this all new adventure across the African wild! Playable by kids of all ages with lots of positive encouragement, professional narration and catchy music. Cute characters include giraffes, meerkats, lions, hippos, zebras, warthogs, cheetahs and rhinos! Designed by parents and teachers, this app adheres to Common Core Standards for first grade math, science and more.' FROM games WHERE igdb_id = 241356 ON CONFLICT (game_id, language_code) DO NOTHING;
