INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rooster-teeth-vs-zombiens', 11248, '2014-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/npparlr0btziivzhaauk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/axxidqlzpoora6j8hfd1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rooster Teeth vs. Zombiens', 'The Zombien menace has, mostly unintentionally, descended upon the Rooster Teeth studio. It''s up to you and the RT cast members to survive their onslaught. After an Unidentified Flying Object becomes an Identified Grounded Object (it''s a space ship) right in the heart of the Rooster Teeth studio, legions of zombie aliens (Zombiens) start coming out of the woodwork and get all hostile up in the studio. It''s up to you, as one of six playable characters, to find and team up with the Rooster Teeth cast members to survive what will one day be known as the Rise of the Zombiens. For as long as possible, at least. In this action/strategy game, you will have to survive in the studio amidst a variety of randomized circumstances: random supporting party members (chosen from eight Rooster Teeth cast members in the game, each with their own unique VO), random weapons, random zombien waves, random crafting materials, and more. You never know what you''re going to get when you set foot in the studio, but you''re going to have to make the best of what you''re given. To survive, you''re going to have to get weapons from Weapon Dispensers, build traps, construct defenses, and stay on the move so the Zombiens don''t corner you and devour your innards.' FROM games WHERE igdb_id = 11248 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 11248 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
