INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gunship-x', 52240, '2014-05-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co81ia.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2vvj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunship X', 'Take control of an AC-130 Gunship to defend humanity from invading hordes. Push back the intruders and give the humans a chance to be airlifted to safety. For the people on the ground you are all that stands in the way of certain destruction. Use the overwhelming power of a 40mm Bofors cannon to subdue the countless waves of attackers before you. When the gibs really hit the fan, switch to the awe inspiring 105mm Howitzer, then take the fight in close with a 25mm Gatling gun. With upgrades your plane will become a weapon of tremendous capabilities. You will have the power to sweep this mysterious enemy aside. But be careful. You might not be the only one with a long reach. You are humanity’s last hope, now “let''s break some stuff"!' FROM games WHERE igdb_id = 52240 ON CONFLICT (game_id, language_code) DO NOTHING;
