INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Butterfly''s Poison: Blood Chains', 'Yuriko, a noblewoman in the Taisho Era, has a big party on her birthday. She then discovers her father is trying to find her a rich husband at the party, but she doesn''t want to have that fate. Suddenly, some rogues break into her place and start trashing the place. She grabs a wooden sword so she can fight them, but a man saves her...' FROM games WHERE igdb_id = 136525 ON CONFLICT (game_id, language_code) DO NOTHING;
