INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rune-rhetoric', 280902, '2014-01-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7jit.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsjjr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rune Rhetoric', 'In Rune Rhetoric’s Earth, a portion of humans are able to use their Inner Rune, a mysterious and personal source of magic that they may channel through weapons or through spells. The game takes place on a fictional continent, named Midmund, which is occupied by two dominant empires; The Reme Empire of the western half and the Hon Empire of the eastern half. Guess what? They''re at war. But the war isn''t the real point here, it''s just what is happening at the time. The player will experience the perspectives of several individuals in a nationalistic and hostile environment. Why do they fight in wars? Are their reasons for fighting good enough? Are they really fighting for what they think they are fighting for? Step into the shoes of a lowly villager, Dahnzell, entranced by images of glory and a reclusive prince, Nero, starved of answers for profound questions in a fight for clarity and change.' FROM games WHERE igdb_id = 280902 ON CONFLICT (game_id, language_code) DO NOTHING;
