INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Wave', 'No Wave is a tribute game to New York in the 80''s and its noisy bands : Sonic Youth, Swans, Birthday Party, Foetus, etc.  You are Jim, a man from Brooklyn. You discover the underground life of New York. Someone told you to go out, but you''re asking "Why?". And the answer is: "Life is in the streets, in music, not only in your flat". You decide to visit one of these clubs known for their wild side. They are repulsive but attractive in many aspects. So there you are, ready to try anything.' FROM games WHERE igdb_id = 128583 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 128583 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
