INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dark-avenger', 38510, '2014-08-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dqbgc5fq5mcufnc4oq3m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scieaa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Avenger', 'Discover 4 unique classes to fight the evil! • - Choose from Templar, Archer, Berserker, and Sorceress in your fight against new evils that have awoken! • State-of-the-art Graphics • - Over 10 million players are fighting the evil every day! - Brilliant 3D Graphics featured in Full HD with Dynamic Lighting!! - Side Camera View feature added for dynamic gameplay! • Boss Raid: Strategic Co-Op Battle • - Play simultaneously with 3 other players in Boss Raid mode! - Formulate strategies with all 4 heroes to defeat the new and advanced World Bosses! • New 3:3 PvP Battle Network • - No wait times and queues! Players can join anytime in epic real-time 3:3 Death Matches! - Reign over others! Play and compete in the warlord match! - Accumulate wins/losses & kills/deaths to compete in the weekly ranking for awesome rewards! • Infinity Tower: The Hunting Never Stops • - Compete against the best players around the world every week! - Reach new heights and become the ultimate warrior! - Meet new event bosses at certain floors! • 18 vs 1: The Ultimate In-Game Action • - The brand new semi-targeting system allows players to maximize the in-game experience! - Combine full effects and skills in a devastating combo to fend off multiple enemies at once!' FROM games WHERE igdb_id = 38510 ON CONFLICT (game_id, language_code) DO NOTHING;
