INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Axle', 'Axle is a mobile platformer set in a world of gears. You play as an exuberant little gear named Axle who maneuvers through dangerous machines, repairing them from the inside out. The game features a vibrant hand-painted art style and an original electro-swing soundtrack in a unique and exciting world. Seamlessly fusing traditional platforming gameplay with innovative touch controls, Axle is an thrilling clockwork adventure for all ages.' FROM games WHERE igdb_id = 9652 ON CONFLICT (game_id, language_code) DO NOTHING;
