INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Card Wars: Adventure Time', 'Card Wars: Adventure Time is a creature-collecting, card based role-playing game set within the fun-filled world of Adventure Time. The game features 20 playable characters from the Land of Ooo, craftable cards, hundreds of creatures, spells and abilities and much more. With more than 200 cards featuring unique abilities, over 250 playable quests and 90 tournament battles, players will get to summon creatures, build buildings, cast spells and watch creatures literally come to life on their holographic game board!' FROM games WHERE igdb_id = 39175 ON CONFLICT (game_id, language_code) DO NOTHING;
