INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('abyssia', 39261, '2014-04-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1j2k.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abyssia', '태초에 신들에게서 추방당한 신.  선과 악 그 어느쪽에도 속하지 안았던 어비시아(심연)은 기억 저멀리 사라졌다.  오랜 시간이 지난 후 인간들은 신의 존재를 연구했지만,  신들은 인간들의 경외의 대상이기만 했지, 자신들의 지식을 쉽사리 알려주지 않았다.  하지만, 어비시아는 "금단의 서고"를 만들었고, 어디선가 신의 지식, 금단의 지식이  있는 "어비시아 대서고"가 존재한다는 소문이 돌기 시작했다.  초대받은 자만이 출입할 수 있는 곳.  지금 당신도 어비시아의 비밀을 파해치기 위해 출발하세요.  "어비시아"는 무료 플레이가 가능합니다.' FROM games WHERE igdb_id = 39261 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 39261 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
