INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cheating Tom', 'Help Tom get through school without studying! Quick, cheat and copy answers off other students before you get busted! Avoid angry teachers and nerdy students! Outsmart your teachers to receive high scores and advance levels. Over 100 challenging and addictive levels! Over 100 cheating challenges! This game is easy to play, hard to beat! Compete with friends and check out their progress on the map! Master the art of cheating and you’ll never have to study or worry about school again!' FROM games WHERE igdb_id = 344015 ON CONFLICT (game_id, language_code) DO NOTHING;
