INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Saga of the Candy Scroll', 'The text intro presented at the start of the game: "This is a game made in two days for #candyjam. Enjoy!" A puzzle game about lining up candy gems, inspired by match-3 games but playing more like a top-down grid-based puzzle game. Cover taken from the freeindiegam.es page. Exact release date is unknown but presumably was posted some time in early 2014 when the Candy Jam was held.' FROM games WHERE igdb_id = 345609 ON CONFLICT (game_id, language_code) DO NOTHING;
