INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War of Nations', 'Become the strongest Commander and a fearless leader by building a military empire and conquering your enemies. Forge an alliance between empires so you can take over the world. Command YOUR powerful army into battle and march into enemy territory with force and power in this PvP strategic game! Get ready to report to alliance base, explore new locations, construct new buildings, and collect the latest supplies in your march to victory. Defeat your enemies in epic single-player campaigns and recruit new commanders, and war experts to seize the day!' FROM games WHERE igdb_id = 323324 ON CONFLICT (game_id, language_code) DO NOTHING;
