INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyper Square', 'Simple but challenging The game has only one goal, under the pressure of time, try to place all the squares shown on the screen into the designated target as quickly as possible in order to get the highest score in each round. As the game progresses, the arrangement and layout of the blocks will become more and more complex. The only way to solve a puzzle within the time limit is to use different gestures to move the blocks at the same time.' FROM games WHERE igdb_id = 345275 ON CONFLICT (game_id, language_code) DO NOTHING;
