INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rogue-soul-2', 300605, '2014-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86vo.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rogue Soul 2', 'Rogue Soul 2 is an action platformer game developed by SoulGame Studio. It''s the sequel to Rogue Soul. Much like its predecessor, Rogue Soul 2 is a platformer game in which you control the titular hero, Rogue Soul, who runs automatically, and wreak havoc on enemies who would rather have him dead. However, Rogue Soul 2 is more story-driven and has a set of levels to be completed in linear progression rather than simply trying to get the best score you can. The game also has many other bonus modes that can be unlocked by reaching various milestones in the game.' FROM games WHERE igdb_id = 300605 ON CONFLICT (game_id, language_code) DO NOTHING;
