INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nineteen', 128654, '2014-08-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x53.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7k7y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nineteen', 'This is pretty different. I heard about the tragic suicide of Aaron Swartz last spring and made this game in ten hours. It loops around a lot; there’s some debate over what the ending of the game is, I guess, but my point is that there’s not an ending.  When I was twelve, I tried to kill myself. I’ve dealt with depression my whole life, but that was the last time I succumbed to suicidal ideation. It’s been nineteen years. This game discusses a lot of things pretty frankly— completed suicide attempts of friends, being rushed to the ER, using Christianity to prop up my self-discipline for a while, my fears for my children.  You can argue whether or not this is a GAME, I guess, but it’s definitely me.' FROM games WHERE igdb_id = 128654 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 128654 AND c.slug = 'elizabeth-sampat' ON CONFLICT DO NOTHING;
