INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dequivsia', 'Dequivsia is a puzzle game developed by Nishikigatsuo in which you navigate to a maze-like structure and collect keys. Some rooms are holes, and entering them costs a life. Each room has an hint of how many solid rooms are around, needing a minesweeper-like strategy for navigating the maze.' FROM games WHERE igdb_id = 326603 ON CONFLICT (game_id, language_code) DO NOTHING;
