INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slip', 'Slip is a fast paced side scrolling platformer featuring a two color, swap mechanic. Using your two colors flee from Steve and his wretched purple beam through a multitude of obstacles and enemies. Slip combines the elegant simplicity of platforming with a polarity mechanic to create an easy to learn, but extremely difficult to master platforming experience. Simply put, Slip is the real deal.' FROM games WHERE igdb_id = 36357 ON CONFLICT (game_id, language_code) DO NOTHING;
