INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Witch 2 Saga', 'From the makers of Candy Crush Saga, Bubble Witch Saga & Farm Heroes Saga comes Bubble Witch 2 Saga! Stella and her cats need your help to fend off the dark spirits that are plaguing their land. Travel the realm bursting as many bubbles as you can in this exciting bubble shooting puzzle adventure. Win levels and free Witch Country piece by piece. Play this epic saga alone or with friends to see who can get the highest score!' FROM games WHERE igdb_id = 61369 ON CONFLICT (game_id, language_code) DO NOTHING;
