INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Comet Moon: The Journey Begins', '"Comet Moon: The Journey Begins" by Xiong Da tells the story of a New Year''s Eve in the late 1990s, in a port city in northern China. Ulan, a first-year student at Hongxing High School, arrives at Jiawu Square in the Fen Dan district to begin her routine duty — sweeping away the resentment in people''s hearts...' FROM games WHERE igdb_id = 339845 ON CONFLICT (game_id, language_code) DO NOTHING;
