INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 4: Limited Edition', 'Far Cry 4 Limited Edition is a special edition of Far Cry 4, there comes with the DLC Hurk''s Redemption. The Limited Edition includes three additional Hurk bonus missions and an exclusive Impaler Harpoon Gun and "More Monkeys". The single-player story follows Ajay Ghale, who initially returns to his home country Kyrat–a wild region of the Himalayas struggling under the regime of despotic self-appointed king Pagan Min (played by Troy Baker)–to scatter his mother''s ashes, but becomes caught up in a civil war.' FROM games WHERE igdb_id = 42943 ON CONFLICT (game_id, language_code) DO NOTHING;
