INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Etherlords', 'Immerse yourself in Etherlords, a marvelous fantasy universe where the Vitals, Kinets, and Chaots are locked in a deadly confrontation for the world’s most vital and important resource. Crush your enemies, collect and evolve your creatures, and discover new strategies to dominate in PvP battles and daily tournaments.' FROM games WHERE igdb_id = 344027 ON CONFLICT (game_id, language_code) DO NOTHING;
