INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth Under Siege', 'Earth Under Siege is an action tower defense game based on frenetic shooting mixed with strategy and upgrades. The Earth is being attacked by an Alien Empire. All nations started working together to create the best defense system humankind could possibly assemble. Great offense turrets were created to attack any incoming threat! You are the chosen commander to take control of them and bring hell to outer space!' FROM games WHERE igdb_id = 17867 ON CONFLICT (game_id, language_code) DO NOTHING;
