INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foresight', 'Foresight is an epic space-based RTS game that throws you, the player, into the thick of the battle as a commander. Lead huge fleets, armed with fighters and bombers across wormholes to fight it out with your enemy. Launch bombing missions, fighter patrols, plant observation posts or fire support base with reconnaissance units. Intelligence is key.' FROM games WHERE igdb_id = 17677 ON CONFLICT (game_id, language_code) DO NOTHING;
