INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ship Simulator: Maritime Search and Rescue', 'You set sail as others return to dry land. Wind force 12. Breakers beat on the bow deck, spray blows across the bridge. On the high seas: face the sheer force of the elements! And you’re steering them – the most powerful rescue vessels of the Maritime Search and Rescue Service in search of castaways.' FROM games WHERE igdb_id = 27185 ON CONFLICT (game_id, language_code) DO NOTHING;
