INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kawaii Killer', 'Kawaii Killer is an intuitive & fun game taking place in an environment where super cute graphics meets cartoon gore. You are Davy, a young trapper killing every single cute animal in the Kawaii Forest. But beware! Each animal is different! When the fox needs only a simple tap to be killed, you''ll have to perform a slice to kill a rabbit, while the frog needs to be torn apart using two fingers! You''ll have to face 14 different animals in Arcade mode, beat the timer in Speedrun mode, grab the gold medal in 36 challenges, and unlock all the badges in the game!' FROM games WHERE igdb_id = 121929 ON CONFLICT (game_id, language_code) DO NOTHING;
