INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('air-conflicts-vietnam-ultimate-edition', 44546, '2014-07-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/xlosquevlgcjkknzqc4j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1chq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Air Conflicts: Vietnam Ultimate Edition', 'Take to the skies above Vietnam and fly for both sides of this explosive conflict. All-out aerial warfare Experience the horrors and heroism of the Vietnam War and prove your worth in aerial dogfights, daring helicopter missions and intense multiplayer battles. Immerse yourself in an emotionally charged storyline as Joe Thompson, a courageous and determined pilot in the US Navy fighting for the ideals of his country - then experience the fight from the other side as Vietnamese pilot Nguyen An Toon in the "Lost Letters" campaign.' FROM games WHERE igdb_id = 44546 ON CONFLICT (game_id, language_code) DO NOTHING;
