INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('touhou-tougenkyuu-riverbed-soul-saver', 213902, '2014-06-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co53od.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scifac.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Tougenkyuu: Riverbed Soul Saver', 'Fan-made Touhou Project game programmed by ido (known for previous fangames The Last Comer and Mystical Power Plant) and Len (known for the fangame Phantasmagoria Trues). The main gameplay mechanic involves a gauge that the player fills up by collecting items. Once full, holding down the bomb key will ''unlock'' the player''s full strength with a powered-up mode for a short period of time.' FROM games WHERE igdb_id = 213902 ON CONFLICT (game_id, language_code) DO NOTHING;
