INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Man''s Shit: An Interactive Trash Adventure', 'Here is the 0.1 edition of my twine for Naked Twine Jam!!!!! Enjoy and share trash with friends! Preorder now for the low cost of $0 dollars and you will be locked into receiving all the fresh One Man’s Shit: An Interactive Trash Adventure content. The final version will include: 1. Over 30 explorable dumpsters! 2. At least three routes to find trash! 3. One to eighty hours of gameplay! 4. The feeling of young adulthood! 5. And more! Don’t miss out, play today!' FROM games WHERE igdb_id = 128638 ON CONFLICT (game_id, language_code) DO NOTHING;
