INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bvs-solitaire-collection', 93360, '2014-05-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/w37yxoex9pddbyyzdsnd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sfunrr8glzxeme7yatlp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BVS Solitaire Collection', 'Enjoy classic and original solitaires with this popular set of 510 games. BVS Solitaire Collection includes all classic solitaire games like Monte Carlo, Seahaven Towers, Klondike, Scorpion, Spider Solitaire, Golf, Russian Solitare, Freecell,Cruel etc. BVS Solitaire Collection also features a lot of original solitaire variations. You won''t find so many original games in other programs. You can even modify rules of any of the included games, thus creating your own solitaire variations. The "You are stuck" feature and unlimited "Undo" function will allow you to come back and try another approach. If you are great solitaire fun, this unique solitaire collection is your best pass to the world of computer card games! BVS Solitaire Collection gives you the plethora of statistical and scoring screens. Track your performance and progress in playing solitaire, and even publish your personal statistics on the BVS Solitaire Collection web site to appear in the top scores list.' FROM games WHERE igdb_id = 93360 ON CONFLICT (game_id, language_code) DO NOTHING;
