INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('biz-builder-delux', 147773, '2014-10-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co573l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9ye.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biz Builder Delux', 'Ah, there''s nothing like the rhythmic bustle of a burgeoning business burg... especially when you''re the one building it! That''s right, from a video game store to the corner fast food joint, run what YOU want as the town''s entrepreneur extraordinaire! Once your coffers are comfortably padded, you''ll be ready to set sights on other ripe markets. Don''t be shy and branch out, erecting a diverse variety of establishments to inspire both pep in the town plaza and plenitude in your pockets! Remember, you''ll need to strategize if you want shoppers to show. Innovate to stock stores with quality products while devising battle plans to rout pesky rivals. Only then will your spot as the town''s top transactor be secure! It''s not easy to rake in those bucks with the free market in flux... but if you conquer that crux--you''ll be Biz Builder Delux! Try searching for "Kairosoft" to see all of our games!!' FROM games WHERE igdb_id = 147773 ON CONFLICT (game_id, language_code) DO NOTHING;
