INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hunters-of-the-dead', 17749, '2014-08-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co43f2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arr5o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunters of the Dead', '“Hunters of the Dead” is a survival/roguelike tower defense game with some micro management elements. You have to rescue your fellow Hunters and with their help locate and destroy Dracula. Dracula has raised an army of undead and has taken the whole city. You must defend your base while in the meantime you have to explore the buildings around and salvage what you can. However, better stay close to your base because as you get further and further you will be finding harder and more frequent battles. You can send your hunters to get healed in the hospitals or trained in the graveyards, but you won’t be able to use them in the battle. That means that you will have fewer units to defend your base in case a battle occurs! So you should manage your Hunters with caution. In case your base gets destroyed, you shouldn’t be discouraged. You will be able to use what resources you have acquired to make upgrades and restart stronger.' FROM games WHERE igdb_id = 17749 ON CONFLICT (game_id, language_code) DO NOTHING;
