INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roll Back Home', 'Roll Back Home is a physics puzzle platform game. Tilt to roll and jump with the lost ball through underground mazes full of mysterious riddles. Swing on large rams to smash walls, ride barrels to avoid being crushed and defy gravity, all to escape the dangers within the treacherous underground sewers. Presented in a sketched and animated flip book.' FROM games WHERE igdb_id = 103113 ON CONFLICT (game_id, language_code) DO NOTHING;
