INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dramatical Murder Re:code', 'Dramatical Murder Re:code is a remake of the original game, but is targeted towards a younger audience, as it is rated CERO – C for ages 15 and above. As such, some of the game''s contents were revised in order to make it more appropriate, such as lessening the blood and violence, and removing scenes with nudity and sex. Additionally, the character Mizuki has his own route in the game.' FROM games WHERE igdb_id = 22494 ON CONFLICT (game_id, language_code) DO NOTHING;
