INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unstrong Legacy', 'Face these daddy issues and watch your world burn. No more running! As your precious base crashes to the ground, you can''t help but wonder, ''WHY!'', ''What went wrong this time?'', and ''Where did all my cool stuff go?!'' But don''t worry, you''ll find out soon enough. You can''t run forever. Unstrong Legacy is a colorful retro-style pixel Metroidvania platformer.' FROM games WHERE igdb_id = 187458 ON CONFLICT (game_id, language_code) DO NOTHING;
