INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('farming-usa', 87490, '2014-02-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dobaixrljzaju3f1pxl6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/u4tahj52eaznuq8ihlea.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farming USA', 'Farming USA is a farming simulator that lets you take charge of your own farm in a realistic 3D world. Walk around your farm and drive tractors, combines, trucks, semis and more. Plant, grow, and harvest crops or hay as well as feed and raise cows, pigs, sheep, and horses. A real American farming simulator! Features: -Own over 30 farm vehicles and implements including tractors, combines, semi/trailers, trucks, planters, cultivators, mower, rake, and baler! -Walk or drive anywhere on your farm, which includes a house, barn, shed, and 5 fields. Visit the grain elevator, animal stockyard, equipment dealership, or fairgrounds -Actually sit in the driver''s seat, or switch to external camera angles. -Plant, grow, and harvest corn, wheat, soybeans, or hay. -Buy cows, pigs, and sheep and feed and raise them to resell. -Use money to buy bigger and better vehicles and implements. -Realistic sound effects - sounds like a real farm! -Compatible with game controller for driving. Guaranteed to be the best farming simulator available on iOS!' FROM games WHERE igdb_id = 87490 ON CONFLICT (game_id, language_code) DO NOTHING;
