INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bishoujo Mangekyou: Katsute Shoujo Datta Kimi he', 'In the middle of the mountains stands an isolated, rural hot springs inn. There works the beautiful waitress, Haru Inamori. Souta Kamijou, the lover of Haru, secretly pays a visit to the inn in order to surprise her... When the idiot couple of adults interlock, a steaming hot night of love ensues...' FROM games WHERE igdb_id = 115724 ON CONFLICT (game_id, language_code) DO NOTHING;
