INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dangerous', 'Dangerous is an epic 3D open and living world space sandbox combat RPG with an immersive and riveting story. You have been awoken from cryo sleep a century later, and must discover the truth. Are you the feared war criminal who will destroy all life or the savior of the universe? Gather your wingmen and travel the galaxy in search of answers. Along the way, you''ll encounter a Universal AI, a shadow group pulling history''s strings, a princess, a schizophrenic robot, a beautiful lieutenant of the Royal Navy, a fearsome mercenary, a suicidal slave, and a playboy fighter ace.' FROM games WHERE igdb_id = 17429 ON CONFLICT (game_id, language_code) DO NOTHING;
