INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '123 Kids Fun Flashcards', '123 Kids Fun Flashcards – early learning educational flashcard game for preschool kids and toddlers – This is the ultimate online flashcard tool for toddlers and preschoolers. With our flashcard game, kids learn first words with sounds, colors and pictures! Flashcards with great sounds and animations in many categories: Furniture, Insects, Fruits, Vehicles, Cutlery and Dishes, Clothes, Vegetables, Animals, Bathroom + four 22-level quizzes and a scoreboard to help keep track of your child’s progress.' FROM games WHERE igdb_id = 87397 ON CONFLICT (game_id, language_code) DO NOTHING;
