INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kitty Love -Way to look for love-', '“I want to be a cat…”. Odd-eyed black cat caught on this casual thought and was cursed to be a cat only at night… The fantasy-romance of human by day and cat by night! This game has been recorded with the popular voice actors Soma Saito, Atsushi Tamaru, Hiroki Yasumoto, Tomoaki Maeno, and Takahiro Sakurai! Enjoy the fully recorded voice throughout the story.' FROM games WHERE igdb_id = 111914 ON CONFLICT (game_id, language_code) DO NOTHING;
