INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jelly-truck', 322049, '2014-09-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91ck.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc11179.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jelly Truck', 'Ever wondered what it would be like to steer a truck through a jelly-filled world? Well, wonder no longer, Jelly Truck is here. Drive your Jelly Truck across all the obstacles to complete each level. Aim is to get the Jelly Truck to the finish flag to level up. Can you drive your wobbly jelly truck all the way to the flag at the end of each level? You will have to roll and jiggle your way across the many obstacles along the way. Everything is made of jelly, so this truck driving game is quite challenging! Good luck! Fantastic driving game, in which you are driving the truck made of… jelly! This wiggling vehicle is quite tricky to drive, so drive carefully and get to the finish line as quickly as possible. Get behind the wheel and try to reach the end of each level! Everything in this world has been made out of jelly, which can make it quite hard to get past certain obstacles.' FROM games WHERE igdb_id = 322049 ON CONFLICT (game_id, language_code) DO NOTHING;
