INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('evil-pumpkin-the-lost-halloween', 17387, '2014-06-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mfxtwgwfvy0gggcijose.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xsshtba8xatvdwbazaup.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Pumpkin: The Lost Halloween', 'Meet Lemuel Barnabas. He is not a protagonist in our story, but just look at him - he’s scrappy and funny, talks to himself, likes music and long walks behind the bar. In a word - he is quite mad, but as mad as he is, he’s the one you come to for help. Help? What happened? You didn’t hear? Apparently there is this thing called Halloween. I know, I know, it sounds stupid. But there’s candy involved! Now I have your attention. The city of Dern is ostracized from the Halloween community. Everyone around you seem to know something about it, but you’re a boy, nobody is going to tell you. In this step away from the classic HO gaming take things into your own hands and find out whatever happened to Halloween.' FROM games WHERE igdb_id = 17387 ON CONFLICT (game_id, language_code) DO NOTHING;
