INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8-Bit RPG Creator: Cuddly Creatures', 'Put together your own enemies and NPC''s using 90 body parts and over 10,000,000 possible character combinations! Build your own customized weapons and weapon shops; draw your own overworld maps using tiles for grass, snow, sand, stone and lava; and interlink as many overworld maps as you want for almost unlimited gameplay possibilities! This Cuddly Creatures edition includes an additional 60 body parts plus the original 90!!! These 60 parts are of the cute and cuddly variety (mostly)! In addition to the new parts, there are new tiles for the overworlds (INNs, shops, medkits, ice cream), as well as animated tiles for water and snow! This pack also includes four new heroes- A baby, a smiley, a zombie, and a mage! You also get four new songs for customizing your game!' FROM games WHERE igdb_id = 288683 ON CONFLICT (game_id, language_code) DO NOTHING;
