INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blood-bowl-tablet', 29030, '2014-12-31', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/mdi4y3dzloyb4wmp8syz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Bowl Tablet', 'Blood Bowl is the adaptation of Games Workshop''s famous Fantasy football board game inspired by the Warhammer world. Assemble your team from among six fantastic races* in the Warhammer universe (Humans, Orcs, Dwarfs, Skaven, Wood Elves, Chaos and Undead). Each race has its own strengths, weaknesses and numerous opportunities to develop which will lend an immense tactical depth to the game. Immerse yourself in single matches in Solo Player mode to enjoy fun, fast games, or set off to conquer the Blood Bowl in the extensive Campaign mode. Develop your team and players by gaining victories and experience as you progress in the game. In Multiplayer you can compete against a friend on your tablet in “Hotseat” mode, or launch yourself into the vast online world in a massive permanent league where you can create and develop your teams. Play against Blood Bowl players from all over the world thanks to our cross-platform multiplayer modes! *The base game enables you to play Humans and Orcs: the other races are available from the in-game store.' FROM games WHERE igdb_id = 29030 ON CONFLICT (game_id, language_code) DO NOTHING;
