INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bubble-cloud-spinning-bubbles', 86774, '2014-03-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vg1ey0jdrhhu47jwekmr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uemgxbljtfqjar6rzngt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Cloud: Spinning Bubbles', 'Shoot bubbles and climb your way up from the ground to the outer space in this fun twist of a “match three” bubble shooter game, inspired by such classics as Bubble Shooter and Bubble Spinner. Highlights: - Shoot bubbles and blast your way up through the clouds! - Bubbles are spinning: Precise aiming and bouncing off the walls are a must! - Explore 150+ challenging levels - Powerful boosters like the laser weapon and super spin - Full HD graphics optimized for Retina display - Free download and free level updates Your goal in each level is to clear the bubbles and break the glass in the middle to collect the stars. The more bubbles you clear, the more stars you get. Stars are needed to unlock new worlds and special boosters. Can you collect all 99 stars to unlock the special infinity level? Shooting bubbles has never been this fun. State of the art gameplay together with full HD graphics, unparalleled controls and a game experience optimized for iPad guarantees an experience unmatched in the bubble shooting industry.
