INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saints Row IV: Game of the Century Edition', 'The US President must save the Earth from alien overlord Zinyak using superpowers and strange weapons in the wildest open world game ever. Includes all available DLC! The epic conclusion to the game that changed all the rules! The Saints have gone from the crackhouse to the White House—but the Earth has been invaded and it’s up to you to free the world from Overlord Zinyak and his alien empire. With homies new and old, superpowers and strange weapons, you must save the world in the wildest open world game ever! And this edition even includes all available DLC!' FROM games WHERE igdb_id = 51869 ON CONFLICT (game_id, language_code) DO NOTHING;
