INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slightly Magic: 8bit Legacy Edition', 'The popular 1990''s arcade adventure Slightly Magic has been remastered and restored by the original author/programmer Colin Jones. Combine objects with spells to activate, turn into a bird, a fish or even invisible! Complete with director''s commentary, a newly-remastered soundtrack by legendary games musician Allister Brimble, enjoy this slice of gaming history!' FROM games WHERE igdb_id = 32573 ON CONFLICT (game_id, language_code) DO NOTHING;
