INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon: The Game', 'In this open world action role-playing game you will bring your dragon''s story to life. Become a terrifying or benevolent dragon powerful enough to threaten kingdoms and leave its claw-mark in history. WARNING: DRAGON IS IN EARLY ACCESS ALPHA. IT IS NOT A COMPLETED GAME. Please do not purchase unless you want to actively support development and are PREPARED TO HAVE FUN DESPITE BUGS AND UNANTICIPATED PROBLEMS. Thank you for your support, Early Access makes this game possible!' FROM games WHERE igdb_id = 36282 ON CONFLICT (game_id, language_code) DO NOTHING;
