INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panmorphia', 'The legend goes that in each generation a child is born, a sentinel, bound to the land of Panmorphia and the four elements that govern it.  The sentinels have the ability to wield each element and transform themselves into an animal that best represents it.  With the use of the amulet they are able to combine all four elements and travel through the aether.  They are called upon for help in times of need.' FROM games WHERE igdb_id = 96536 ON CONFLICT (game_id, language_code) DO NOTHING;
