INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Lands: Black Gem Hunting', 'My Lands is a free online RTS where dark and light forces fight for Black Gem and dominion in a vast fantasy world. Cooperation between players, joint economy development, creation of clans and alliances and elaboration of a team strategy serve as the very foundation of the game. Player chooses one of four races to lead it to the victory through ruthless wars over dominion in the universe of My Lands.' FROM games WHERE igdb_id = 10576 ON CONFLICT (game_id, language_code) DO NOTHING;
