INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dai-3-ji Super Robot Taisen Z: Jigoku-hen', 'Like Z2, the third and final chapter in the Super Robot Taisen Z tactical RPG series is split into two parts, starting with Jigoku-hen ("Time Prison Chapter"). The game features mobile suits and mecha characters from 32 anime series including the newly added Mobile Suit Gundam UC, Armored Trooper Votoms: Big Battle, Armored Trooper Votoms: Shining Heresy and Aquarion EVOL.' FROM games WHERE igdb_id = 80144 ON CONFLICT (game_id, language_code) DO NOTHING;
