INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wagamama Fashion: Girls Mode Yokubari Sengen! Tokimeki Up!', 'Wagamama Fashion: Girls Mode Yokubari Sengen! Tokimeki Up! is a game in the Style Savvy / Style Boutique series. It is a Japan-exclusive game which was released on 17th April 2014. It is an updated version of Style Savvy: Trendsetters (known as New Style Boutique in the PAL region) with more features. The new features includes additional items, as well as five additional modes.' FROM games WHERE igdb_id = 136906 ON CONFLICT (game_id, language_code) DO NOTHING;
