INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Remover Blast', 'Red Remover Blast is the explosive spin-off of hit puzzle game Red Remover. The gameplay is different this time around. Instead of tapping red shapes to remove them you must use explosions to knock them off the screen. Don''t knock any green shapes off though or you''ll fail the level. To add to the fun there are 8 planes of gravity - look at the shapes faces to see which way they will fall. Too easy? Try replaying the game in the extra challenging coin mode!' FROM games WHERE igdb_id = 253266 ON CONFLICT (game_id, language_code) DO NOTHING;
