INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asylum Night Shift', 'Can you survive five nights at the asylum? Welcome to your new job as nightwatchman at the Ravenhurst Mental Asylum. From your security office you must keep watch on the asylum patients throughout the night - and make sure that they don''t enter your room! Can you survive five nights of terror at the asylum!' FROM games WHERE igdb_id = 90392 ON CONFLICT (game_id, language_code) DO NOTHING;
