INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('time-of-fury', 17486, '2014-06-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vk9lu3i0f484xqjfqfg2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/myflvv4kl2kzzyhxcpzk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time of Fury', 'In World War II every single aspect of war was crucial: from troop movements to supply, from logistics to diplomacy, from innovation to careful use of terrain. Many games have tried to replicate the depth and complexity of this global conflict and only a few have managed to give an all around experience to players.  This is a game that truly replicates all these aspects. The developers of the highly successful Time of Wrath are back to the European theater of war with an ambitious project that allows players to truly experience what it was to be a decision maker of the period.  Time of Fury spans the whole war in Europe and gives players the opportunity to control all types of units, ground, air and naval. Player is able to pick a single country or any selection of countries and fight his way against enemy at the country-customized difficulty levels.Important notice  Time of Fury features unique gameplay options. Each country in the game is represented with dedicated attributes. Every country has got it''s pros and cons. This makes the game extremely replayable and provides hundreds of hours of play.' FROM games WHERE igdb_id = 17486 ON CONFLICT (game_id, language_code) DO NOTHING;
