INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coming Out Simulator 2014', 'A half-true story about half-truths. You play as a semi-fictional version of me, on a night that changed my life forever. Choose your (my?) words wisely. Every character will remember everything you say -- or don''t say -- as you figure out how to approach my (your?) hyper-conservative Asian parents. And if all that seems confusing or awkward... well, that''s the gist of coming out as queer, isn''t it?' FROM games WHERE igdb_id = 60030 ON CONFLICT (game_id, language_code) DO NOTHING;
