INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo! & Looney Tunes Cartoon Universe: Adventure', 'Solve the mystery of Kraken Cove with Scooby, Shaggy and the rest of the Mystery Machine Gang or help Bugs and Daffy discover who is behind the dastardly defective MOCME products that are creating chaos. Solve puzzles and fight enemies as you unlock the mysteries in this exciting cartoon world come to life. Find gifts, safes and treasure chests and use the loot you collect to customize your character and empower them with special ability upgrades.' FROM games WHERE igdb_id = 36326 ON CONFLICT (game_id, language_code) DO NOTHING;
