INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('2k48', 350669, '2014-03-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa0vq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxnhv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2K48', '2048 is an addictive and challenging number puzzle game that will test your strategic skills and mental agility. The game is played on a 4x4 grid, and the objective is to combine tiles with the same numbers to create a tile with the number 2048. To play the game, you need to slide the tiles in any direction using your fingers or the arrow keys. Whenever two tiles with the same number touch, they merge into one, creating a new tile with a higher number. The game starts with two tiles of the number 2, and you need to combine them to get the number 4. From there, you need to keep combining tiles to get higher numbers and reach the target of 2048.' FROM games WHERE igdb_id = 350669 ON CONFLICT (game_id, language_code) DO NOTHING;
