INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Love My Little Girl', 'Play with the baby of your dreams! Hair, face, clothes... Choose the baby of your dreams and discover lots of ways to look after her the way you want: preparing meals, dressing up in different outfits, bathing, playing, going for walks… Unlock new, even more adorable outfits for your toddler. Cute and colourful graphics with 3D babies Your baby laughs and cries just like a real one!' FROM games WHERE igdb_id = 84540 ON CONFLICT (game_id, language_code) DO NOTHING;
