INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Children of Liberty', 'Listen my children, and you shall hear of the midnight ride of Paul Revere... When four spies of the Sons of Liberty are arrested infiltrating The Province House, their children join Paul Revere, Samuel Adams, and the Sons of Liberty to finish their mission and break them out as the threat of Revolution looms over the Colonies... Join Joseph, Ally, Doug, and Sarah as they use their wits and their toy chest to defeat the Redcoats in this 2.5D stealth-action adventure retelling of Paul Revere''s Midnight Ride for kids and adults alike.' FROM games WHERE igdb_id = 16859 ON CONFLICT (game_id, language_code) DO NOTHING;
