INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Higurashi no Naku Koro ni Hou: Kamikashimashi-hen', 'The club has successfully made it to Okinomiya and evades more crazed villagers as they try to find the Sonozaki family''s stronghold, meeting a girl named Une who may hold the key to salvation. Meanwhile, Rika and Hanyuu stay behind in Hinamizawa and do some investigating of their own, encountering some old acquaintances.' FROM games WHERE igdb_id = 263493 ON CONFLICT (game_id, language_code) DO NOTHING;
