INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Might & Magic: Duel of Champions - Forgotten Wars', 'Enter the legendary universe of Might & Magic with Duel of Champions Forgotten Wars, the online strategy card game. Choose your hero and assemble an army to attack fierce opponents on the battleground. Play your creatures, spells, fortunes, buildings and events wisely to unleash killer combos and gain the upper hand. With more than 650 unique cards to collect and 100+ hours of game content to unlock and explore, the adventures you can have are unlimited!' FROM games WHERE igdb_id = 52586 ON CONFLICT (game_id, language_code) DO NOTHING;
