INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ambition: Strategy War Game', 'This is a time for heroes. This is World War II. This is Ambition. Ambition gives you all the control, and allows you to focus on winning through intense strategic calculation. Don''t be held back by generic rules or a lack of options - command your troops on three different maps using a mind-boggling amount of options and possible settings.' FROM games WHERE igdb_id = 200037 ON CONFLICT (game_id, language_code) DO NOTHING;
