INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('democracy-3-social-engineering', 11399, '2014-02-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/y4rwptyqrdoon0ztla7c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jsoloqdzl4lr67yaforn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Democracy 3: Social Engineering', 'Democracy 3: Social Engineering is an expansion pack that adds to the variety of policies and dilemmas available in the base game. The expansion is ‘themed’ in that it concentrates on those areas of policy where governments can influence the make-up of the electorate in subtle low-key ways over the long term. For example, subsidies to bicycles will encourage people to exercise more (in the long run decreasing health costs) and will also encourage less people to own cars and be members of the motorists group. Other policies to encourage entrepreneurship amongst young people will eventually lead to more people becoming self employed, and so on… A total of 26 policies and 8 dilemmas are included in the expansion, including food labelling, car-pooling, Labor Day bank holiday, witness protection schemes, a diplomatic service, armed forces week, free parenting classes, and much more. The social engineering expansion will allow you see the game as less of a simple win/lose challenge and more of a ‘society sandbox’ that gives you the power to change society over the long run whilst keeping everyone voting for you!' FROM games WHERE igdb_id = 11399 ON CONFLICT (game_id, language_code) DO NOTHING;
