INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soukai Buccaneers!', 'Rian Lawrence is a 16-year-old girl whose mother passed away when she was a child and now her father has gone missing. She dreams of becoming a seafaring adventurer, having been influenced by watching church plays, hearing epic heroic tales and learning that her missing father was also an adventurer who crossed the ocean. To fulfill this desire, she leaves the town where she has comfortably lived, and ventures to the port, King’s Bridge.' FROM games WHERE igdb_id = 61275 ON CONFLICT (game_id, language_code) DO NOTHING;
