INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('i-am-a-brave-knight', 121233, '2014-10-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4l9e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3gtw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Am a Brave Knight', 'I am a brave knight is a game created by Tree Interactive for the Global Game Jam 2014. It''s an emotional short story that tells the experiences of a man throughout his life. The topic of the Game Jam was: "We don''t see things as they are, we see them as we are", and we had 48 hours to complete it. We feel the main storytelling mechanic is unique and has not been tried before. It encompasses a combination of writing "blindly", backing off, and reading what you just wrote to make sense of the picture and situation the player is seeing. We also feel that the way we are telling the story, through main references on his life, is something few games have done before.' FROM games WHERE igdb_id = 121233 ON CONFLICT (game_id, language_code) DO NOTHING;
