INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JoJo''s Bizarre Adventure: Stardust Shooters', 'JoJo''s Bizarre Adventure: Stardust Shooters is a free IOS/Android game released in 2014 exclusively for Japan. The game is a mobile spin-off of JoJo''s Bizarre Adventure: All-Star Battle and focuses on the first three parts of the series: Phantom Blood , Battle Tendency, and Stardust Crusaders. As of December 2015, Diamond Is Unbreakable elements have been added to the game.' FROM games WHERE igdb_id = 62019 ON CONFLICT (game_id, language_code) DO NOTHING;
