INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destiny: Digital Guardian Edition', 'The Destiny Digital Guardian Edition is an edition of Destiny that can only be obtained as a digital download. It is available for PlayStation 4, PlayStation 3, Xbox One, and Xbox 360. The Digital Guardian Edition includes the following: - Digital download of Destiny - Pre-order bonus of early access to several pieces of Vanguard armor and weapons and Vanguard player emblem - Collector’s Edition Digital Content: The City has provided you with a cache of items to start you on your journey, including: - A Unique Ghost Casing - An Exclusive Player Emblem - An Exclusive Player Ship Skin - Includes the Destiny Expansion Pass (a season pass for two future Destiny expansion packs, including The Dark Below and House of Wolves)' FROM games WHERE igdb_id = 147720 ON CONFLICT (game_id, language_code) DO NOTHING;
