INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Trackers: Blackrow''s Secret', 'It''s been two hundred years since the plague swept through here... Authorities quarantined the area around Blackrow Mansion, and it hasn''t been opened since. But now, an up-and-coming starlet is receiving strange threats that have drawn her straight to the quarantine zone. What is hiding behind the rusted gates of the Forbidden District? Play innovative new mini-games and explore gorgeous hidden-object puzzles as you track down the truth behind Blackrow''s secret!' FROM games WHERE igdb_id = 201830 ON CONFLICT (game_id, language_code) DO NOTHING;
