INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('detective-masochist-3-the-case-of-the-naked-truth', 279062, '2014-10-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7g3e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpsl0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Detective Masochist 3: The Case of the Naked Truth', 'Our setting is the venerable city of Kanazawa... Our protagonist is the (Acting) Director of a Private Detective Agency, tasked with keeping peace in this fair city. As a detective, he''s still a little green, but as a super-masochist, he''s top-notch! His brave assistant is one Satomi Komatsu. The two of them have gotten wrapped up in a case involving strange rings. One such ring has twisted Satomi physically and mentally, and at times she transforms into a super sadist herself! Our hero investigates the rings hoping to return Satomi to normal, but he just can''t quite crack the case. Troubles plague him during his investigation, first when he takes another case by the well-endowed erotic novelist Kiriko Noto, and then when the Agency is taken over by the beautiful and mysterious Regina Kaga. A detective story filled with ups and so, so many downs!! And that''s even before the Queen of Dawn, an assassin for the sinister Association, shows up! What will tomorrow bring for a man who can never improve as a detective and can''t stop improving as a masochist?!' FROM games WHERE igdb_id = 279062 ON CONFLICT (game_id, language_code) DO NOTHING;
