INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stockfish-chess', 87155, '2014-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ugtrhiksvdkmjekcbesf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kk1hb3pctcv6ngyd9cx6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stockfish Chess', 'Stockfish is a powerful chess analysis app. Play two-player games on the beautiful chess board, or get instant accurate analysis of any game. Stockfish will tell you who''s winning and calculate the best move. Features: INTERACTIVE, IMMERSIVE BOARD Stockfish has a gorgeous board that looks fantastic on Retina Displays. It''s full of nice touches: when you click or drag a piece, its destination squares are highlighted in yellow, and the best move is shown with a red arrow. Plus, you can go full screen for the most immersive chess experience. TOP-NOTCH CHESS ANALYSIS Analysis is powered by the Stockfish chess engine, the strongest free chess engine in the world. You''re getting top-notch analysis that surpasses the strongest human chess grandmasters. ADVANCED FEATURES Stockfish has many enhancements for advanced users. You can browse through multi-game PGN files, copy and paste FEN strings, utilize Syzygy endgame tablebases, and use MultiPV. FREE AND OPEN SOURCE Stockfish is completely free, and the source code is available on our website (stockfishchess.org) under the GPLv3 license.' FROM games WHERE igdb_id = 87155 ON CONFLICT (game_id, language_code) DO NOTHING;
