INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Friend Pedro: Arena', 'Use acrobatics, reflexes and a sh*t tone of bullets to gain the highest score in one of the six available levels! This game has all the exciting bits from the original ''My Friend Pedro'', but put in the new context of Arena-mode, a mode which will put your survival instinct to the test! How long will you survive?' FROM games WHERE igdb_id = 289599 ON CONFLICT (game_id, language_code) DO NOTHING;
