INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hunger Games: Panem Rising', 'Katniss Everdeen has agreed to unify the districts of Panem against the Capitol. Help Katniss enlist other rebels in this Role Playing Card Collection Game that will immerse you in Panem’s unique districts. Explore each district in Panem, recruit rebels, and collect resources to aid you in victory. Train your rebels to upgrade your team’s skills or equip your squad with specific tools to unlock unique abilities for your journey.' FROM games WHERE igdb_id = 344829 ON CONFLICT (game_id, language_code) DO NOTHING;
