INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cow Flew Over the Moon', 'Cow Flew Over is a first person experimental adventure game driven by its narrative and level design, both of which have been based on the stimulus of dream interpretation. CFO focuses on its atmosphere and explorative gameplay mechanics to tell a mature and vague narrative, left open to the player''s imagination and interpretation of events. By only giving half the story through the level progression and leaving the rest for the player to piece together by inspecting and interacting with the environment, CFO aims to be a short 15 minute adventure game.' FROM games WHERE igdb_id = 8368 ON CONFLICT (game_id, language_code) DO NOTHING;
