INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Camelia', 'Camelia is an adventure story-telling game. There are no game overs, and only one ending. It''s nothing but a story. Camelia comments on many things in her house - make sure you explore it thoroughly and often. Please take the time to learn about the world with her - and make sure you stay after the credits, or you won’t be able to learn what gives her happiness.' FROM games WHERE igdb_id = 125144 ON CONFLICT (game_id, language_code) DO NOTHING;
