INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slender: The Gaze Of Horror', 'Slender: The Gaze Of Horror is a Slender game created by Italian game developer Luca Bersiga a.k.a. lukeberfiga and inspired by Slender: The Eight Pages. It was originally released in October 2014, then remastered in May 2021 with a patch which added improvements such as new features, visual effects and stalkers to the game (the 2021 Ultimate Hardcore Patch).' FROM games WHERE igdb_id = 321324 ON CONFLICT (game_id, language_code) DO NOTHING;
