INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thief-master-thief-edition', 53797, '2014-02-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2czi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2v9x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thief: Master Thief Edition', 'There is a rising tide of fear in The City. Hatred saturates every stone and whilst the rich prosper, the less fortunate face misery and repression. Ravaged with sickness and famine, they wait for something to change. The Master Thief Edition includes: - Official Digital Artbook - stunning concept art that offers a sneak peek into the shadowy world of Thief. - Digital Comic - Delve deeper into the shroud surrounding Thief''s obscure world with this complete collection of digital comic books. - Booster Pack - Get access to an exclusive bundle of optional in-game consumables that can empower you and hasten your progression through Thief. - Director''s Cut Original Soundtrack - a remarkable collection of Thief tracks.' FROM games WHERE igdb_id = 53797 ON CONFLICT (game_id, language_code) DO NOTHING;
