INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth Taken 2', 'The second part of a post-apocalyptic action-shooter set in the midst of an alien invasion. Most humans and animals have already been wiped off the planet, the eco system has been altered to suit the needs of the aliens, and the air has been made unbreathable for most earth creatures, including humans. Earth Taken 2 kicks off where the first game ended. You are the sole survivor of a car crash. You have lost all of your equipment except for a combat knife and a few gas mask filters. Your mission: Survival.' FROM games WHERE igdb_id = 365133 ON CONFLICT (game_id, language_code) DO NOTHING;
