INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fluster Cluck', 'Use explosives, rockets, turrets and mines to get your friends'' UFOs out of the sky. Drag them to the Chikkinizer and ignore their whining. Shout jibes at the flying chikkins in a loud voice, since they can''t mute the FLUSTER CLUCK MASTER! Earn bigger guns, faster ships, crazy hats! Free your friends and put them in the Chikkinizer. They will be instantly chikkinized with a MegaField, and laugh all the way up the ladder!' FROM games WHERE igdb_id = 52210 ON CONFLICT (game_id, language_code) DO NOTHING;
