INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motocross-meltdown', 343969, '2014-01-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tjh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwu01.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motocross Meltdown', 'Motocross Meltdown is a fast-paced drag race and trick based game that uses a one button control mechanic. Instead of driving the motorbike entirely, acceleration and speed is determined by timing icons that move over a bar at the bottom of the screen. As such, steering is also done automatically. The player is given the opportunity to upgrade their motorbike with multiple parts as well as trick out the bike with decals from real brands such as Monster Energy, Alpine Stars and Metal Mulisha. There are over 800 configuration options available and a custom rider can also be created. Players can also compete for weekly prizes playing in multiplayer tournaments. The game is free-to-play with in-app purchases for additional items.' FROM games WHERE igdb_id = 343969 ON CONFLICT (game_id, language_code) DO NOTHING;
