INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '9 Innings: Pro Baseball 2014', 'Get ready for the No. 1 baseball game on mobile! It’s back and better than ever- 9 Innings: 2014 Pro Baseball! Officially licensed with the Major League Baseball Players Association (MLBPA)! 9 Innings: 2014 Pro Baseball is the hottest, most realistic baseball simulation game that uses the names, photos, data, and league schedules of real baseball players!' FROM games WHERE igdb_id = 303969 ON CONFLICT (game_id, language_code) DO NOTHING;
