INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '0h h1', 'A lovely little logic game. 0h h1 is a logic game that follows three simple rules: - Three red tiles or three blue tiles next to each other in a row or column isn''t allowed. - A full row or column must have as many blue tiles as it has red ones. - No two rows are the same. No two column either.' FROM games WHERE igdb_id = 135741 ON CONFLICT (game_id, language_code) DO NOTHING;
