INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shall we date?: The Niflheim', 'Now included in the "Story Jar" app. Welcome to the world of Niflheim, the darkest and coldest kingdom for the dead, ruled by King Jean! This is the story of the princess, who has awakened from a millennium of sleep by three men (Orlando, J.J. and Philippe), and tries to find her true love, being demanded by King Jean to be his queen. Who will be her everlasting partner? Could the king be the one she can trust and promise, “till death again do us part?” Or, maybe the other?' FROM games WHERE igdb_id = 214842 ON CONFLICT (game_id, language_code) DO NOTHING;
