INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bik - A Space Adventure', 'Bik is a retro-style point and click adventure game. In Bik, we follow a young boy who is abducted by aliens while on a camping trip with his friends. After joining forces with two friendly alien mercenaries, Ammut and Tatenen, Bik escapes from his abductors and tries to find his way home. Along the way, Bik and his newfound friends outsmart hijackers, (eat some brownies), accept a perilous mission to find a missing alien, (make some sandwiches), foil a dastardly plot by an evil corporate empire, (argue with disgruntled robots), and save a planet on the brink of destruction.' FROM games WHERE igdb_id = 17878 ON CONFLICT (game_id, language_code) DO NOTHING;
