INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Always Remember Me', 'Amy is desperate! Her boyfriend Aaron doesn''t remember her anymore after a car accident! Will you be able to make him remember again? Or perhaps it''s time to move on. Maybe Amy will fall in love with someone else? It''s up to you to decide. Play this life simulation game with dating sim elements and shape Amy''s destiny.' FROM games WHERE igdb_id = 36356 ON CONFLICT (game_id, language_code) DO NOTHING;
