INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gurk-ii', 19125, '2014-03-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/drvllwy3easnbyvnmy73.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/situywkyulxqltijwrvl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gurk II', 'The super-charged sequel to the famous 8-bit RPG, Gurk II is a huge new adventure with all of the most requested features added: quests, music, sound, potions, and an improved look! Fans of the original will be shedding tears of joy as they roll for their character''s stats, board ships, summon monsters and cast powerful area of effect spells. Players not previously familiar with the realm of Gurk will simply stare in slack-jawed wonder at the beautifully pixelated graphics, all the while being serenaded by the lush and authentic MIDI soundtrack. Only the viscerally-compressed sound FX and challenging new combat tactics will snap them back to their senses. This game radiates a pure and unabashed joy of old-school RPGing; your $1 couldn''t possibly go any further now, or back in 1986 when these kinds of games were actually commercially viable.' FROM games WHERE igdb_id = 19125 ON CONFLICT (game_id, language_code) DO NOTHING;
