INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sam Glyph: Private Eye!', 'Bear witness to a mysterious phone call that will pull Sam into a dangerous underworld, where life itself is actually threatened and physical harm is a serious possibility! Revel in the popular First-Person view, as you investigate Sam''s environment and poke things with your mouse and human interface devices! Listen to Sam say things in a fairly amusing manner! Grr, he''s an angry chap isn''t he?! Escape danger at least twice! Move around with your legs and push things with your hands! Yes! This actually happens! Episodic format! What will/can/does happen next?! Classic Film Noir stylings! Suprises and actual music! From the creators of INIT. and The Tower! Also Polarium! Three games that you will never have heard of! Bust punks and celebrate with confetti showers! That''s telling them! Twice!' FROM games WHERE igdb_id = 17903 ON CONFLICT (game_id, language_code) DO NOTHING;
