INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pipes 3D', 'Pipes 3D is a simple, addictive, fun and challenging puzzle game which will make you think in 3D. It is inspired by numberlink aka flow type games, but instead of playing on a two dimensional plane, you get to play on a surface of a three dimensional cube. This game retains the enjoyment and simplicity of a regular flow-like games, as well as offers more challenging ways to play it for those who find regular numberlink type games just a little bit too easy.' FROM games WHERE igdb_id = 21985 ON CONFLICT (game_id, language_code) DO NOTHING;
