INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mission Control: NanoMech', 'Mission Control: NanoMech is set late in the 21st century in a high-tech Mars base. A rogue artificial intelligence named D-brain has taken control of the factory and most of its robotic workers, and refuses to let the humans go. It''s up to the player to defeat D-brain and save the humans trapped inside the factory.' FROM games WHERE igdb_id = 28585 ON CONFLICT (game_id, language_code) DO NOTHING;
