INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inescapable', 'Named the "Best PC Metroidvania You Didn’t Play of 2013" by Matthew Zulawski of metroidvanias.com and listed as a notable game in indiegames.com''s Top 10 Indie Horror Games of 2013, the game sees players unravel the mystery uncovered by a remote interplanetary mining operation.  What did they find? What threat does it pose? And ultimately, what does it truly mean to be a hero?' FROM games WHERE igdb_id = 17302 ON CONFLICT (game_id, language_code) DO NOTHING;
