INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shh, Zombies', 'Shh, Zombies is set in a cuboid word where the people, nature and even the architecture is cuboid! The poor people of Shh, Zombies evolved with their heads always looking to the sky, which gives them a much brighter outlook on life, especially since the zombie problem broke out. With a spring in his step our hero, Jim, happily bounces along the path set by the user to reach the safety of the level exit - and the safe house hidden below!' FROM games WHERE igdb_id = 21979 ON CONFLICT (game_id, language_code) DO NOTHING;
