INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoidtrip', 'Is it a squid? Is it a kite? Is it a triangle? We don''t know. It could be anything. In Zoidtrip you have to take control of a triangle-shaped character with two floppy tails! Your goal is to go as far as possible to get a better score... and ultimately unlock new triangle-shaped heroes!' FROM games WHERE igdb_id = 344908 ON CONFLICT (game_id, language_code) DO NOTHING;
