INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Agent P: Rebel Spy', 'The game places the player as Agent P within the Phineas and Ferb - Star Wars crossover universe. The game features three levels, in each of which the player must fight their way past Darthenschmirtz''s Normtroopers to rescue their fellow agents before battling Darthenschmirtz in an arena, where the agents they rescued return to help them out.' FROM games WHERE igdb_id = 143328 ON CONFLICT (game_id, language_code) DO NOTHING;
