INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utopia', 'Utopia is a free adventure game with elements of horror made by Shintaro in RPG Maker VX in 2014, that can be completed in about an hour that leads to three different endings. It was translated to English by Tosiaki and to Portuguese by Sissi and Yuuichi (Zero Corpse).' FROM games WHERE igdb_id = 142988 ON CONFLICT (game_id, language_code) DO NOTHING;
