INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amity x Li', 'Amity Watkins and her girlfriend Li Anderson are seniors in high school in the smallish, obscure town of Foxville, Massachusetts. It''s Saturday, only five episodes of Sailor Moon Crystal have been released, and Amity wants to give Li a flower pendant. A Twine story about two girls in love, chatting about life.' FROM games WHERE igdb_id = 142505 ON CONFLICT (game_id, language_code) DO NOTHING;
