INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Race to Mars', 'Race To Mars is a turn-based, space company simulation game. Become the head of the newly established "New Space" company whose goal would be to establish a colony on Mars. You begin as a startup - develop cutting edge aerospace technologies and use them to achieve orbit and fly beyond Earth vicinity, blazing the trail of a space pioneer and leaving the competition far behind on your way to victory.' FROM games WHERE igdb_id = 16737 ON CONFLICT (game_id, language_code) DO NOTHING;
