INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounce Original', 'Can you pass level 7? For those of you who spent hundred of hours passing levels in classic oldschool Bounce Game, we made this one - Bounce Original. Enjoy 11 teeth-shattering levels, collect all rings and beware of dangerous thorns. Stay in touch with your friends and beat their scores. Most popular game - now on your iPhone and iPad!' FROM games WHERE igdb_id = 344928 ON CONFLICT (game_id, language_code) DO NOTHING;
