INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('leonas-tricky-adventures', 17518, '2014-11-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86dv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xsiizitaa5kzqpipd1gm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leona''s Tricky Adventures', 'Accompany Leona in a clever puzzle adventure to save the inhabitants of a strange but lovely world. Featuring fresh puzzle mechanics, wonderful retro graphics, lots of exploration and an excellent soundtrack by legendary game composer Chris Huelsbeck. Leona’s Tricky Adventures is inspired by a clever puzzle game mechanic which was briefly explored in the very early 90s but sadly faded from prominence shortly after. The basic task is to match two increasingly complex patterns using increasingly complex mechanics. While it can’t be directly compared to any contemporary game the mental skills required by the puzzles put them somewhere in between "Picross" and "Bejeweled" – and in our humble opinion they can easily stand up against those games. All puzzles are embedded in a big and complex overworld full of exploration and humorous citizens constructed entirely using beautifully hand-drawn pixel graphics. Exploration and puzzle-solving is intertwined in clever and varied ways which draw you deeper into the game world.' FROM games WHERE igdb_id = 17518 ON CONFLICT (game_id, language_code) DO NOTHING;
