INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales from the Dragon Mountain 2: The Lair', 'It has been years since brave Mina Lockheart defeated Lord Strix. But dark shadows are rising once again! Spirits are restless! For he has awaken! Evil Lord Strix is breeding a new army to enslave all creatures from the Dragon Mountains! It is once again up to Mina and her best friend spirit Malik to travel to distant parts of the world and find clues how to open the passage to a hidden wasteland - Lord Strix''s lair. Meet different characters along your journey, help them and have them help you. Search and discover new places, but hurry! Lord Strix gets stronger by the minute!' FROM games WHERE igdb_id = 10951 ON CONFLICT (game_id, language_code) DO NOTHING;
