INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Home From Work 2', 'You arrive home from work after a long and late night working at the office. Upon arriving home you begin to experience paranormal occurrences. You soon discover that you are not alone in your own home. You begin investigating but in doing so, you aggravate the demonic presence in your home. Discover what a demonic presence is capable of doing in Home from work 2' FROM games WHERE igdb_id = 213371 ON CONFLICT (game_id, language_code) DO NOTHING;
