INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block City Wars: Mafia Town', 'Are you aching for some audacious daredevilness and real danger? Then it’s high time we set out to open the criminal world of Block City! Use our special Skins Exporter for Minecraft! It is a user-friendly tool for changing standard skins in Minecraft Pocket edition and Minecraft PC edition to a variety of exclusive ones which are created by our designers. Export can be used either from the first game screen, main lobby or the game interface. Skins can be exported either to Minecraft mobile or desktop version.' FROM games WHERE igdb_id = 86930 ON CONFLICT (game_id, language_code) DO NOTHING;
