INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('baron-wittard-nemesis-of-ragnarok', 10022, '2014-04-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hkgufi5zn5k2q0zs2itw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hsenp9atawkxddxqtje9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baron Wittard: Nemesis of Ragnarok', 'The eccentric architect Baron Wittard has built something really special: a city inside a building. This monumental pleasure dome, called ''The Utopia'', features 1000 apartments, a shopping mall, and hundreds of offices and leisure facilities. All under one roof. Its grand opening was supposed to have been two year ago. That event never happened. A chain of mysterious events has now left the Utopia abandoned and silent. People have gone missing. Electromagnetic disturbances are increasing. Armed with only a camera and a torch, you must journey there alone to explore its winding corridors, its secret passageways, and its gloomy halls. Local townspeople say Wittard kept a terrible secret. They speak fearfully of someone or something malevolent living at his city. They say it is waiting and growing in power. They say time is running out... players will have to face the lurking horrors of this desolate place and find out what dark secret the Baron kept from the world.' FROM games WHERE igdb_id = 10022 ON CONFLICT (game_id, language_code) DO NOTHING;
