INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Cow Rampage: Orion Needs Your Milk!', 'In an original boardgame that could be described as the jumpsuit-clad cousin of Chainsaw Warrior and Munchkin, you''re an alien on the run. Within 12 hours you need to make it through a mazy suburbs, abduct cows from heavily guarded pastures, and brave an Earthling military base in order to catch a ride on your mothership. There is little time. There are many dangers. But you CAN make it, and there are always cows.' FROM games WHERE igdb_id = 165509 ON CONFLICT (game_id, language_code) DO NOTHING;
