INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sinister Fairground: Horror Adventure Gamebook', 'This is a horrifying adventure through a fairground of weird characters, dangers, challenges and quizzes. The Sinister Fairground is a mind-altering world where nightmares and reality change places at every turn, and nothing is as it seems. An evolution of classic choose-your-own-adventure game-books, this darkly enchanting story puts you in control, and takes you on a journey through twisted fairground attractions that you''ll never forget!' FROM games WHERE igdb_id = 175303 ON CONFLICT (game_id, language_code) DO NOTHING;
