INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hippocampal: The White Sofa', 'Hippocampal is a satiric contemplative game. Satiric because we are mocking the hero, game characters, movies, comic books and video games we liked. And also the ones you like. Basically everything that tells you to be what you do not want to be. Contemplative because you just have to walk through this world to understand how it works.' FROM games WHERE igdb_id = 17394 ON CONFLICT (game_id, language_code) DO NOTHING;
