INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aviator-bush-pilot', 10007, '2014-11-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6i16.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/opxjqtsaznygqfsbm3ss.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aviator: Bush Pilot', 'Get ready to pack your gear and fly off into the wilderness of the endless plains! As the busy operator of a hangar and runway in the heart of a region like the Serengeti, there are countless ways to earn a living. As an ‘old school’ bush pilot, you must undertake challenging jobs to make the lives of both tourists and locals a lot easier. Fight bush fires, transport goods, find missing people & items, serve as a first responder & wildlife preservationist, or simply take some snapshots of archaeological finds. At the beginning, you must make do with small planes - but with increased success you will be able to upgrade your craft, buy more powerful machinery, and accept more lucrative missions. However, you must be careful - all machines have to be maintained properly and improved in order to operate efficiently. The accurate handling and realistic physics combine with full controller support to provide you with complete control over your aircraft. So get into the cockpit, head out to the Steppe, and indulge your passions – in ‘Aviator: Bush Pilot’.' FROM games WHERE igdb_id = 10007 ON CONFLICT (game_id, language_code) DO NOTHING;
