INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aritana and the Harpy''s Feather', 'Aritana is a platform game which the main aspect of its mechanics is the possibility of changing your stance. This stances define attributes such Speed, Jump Force, Attacks and Special Abilities. The player must choose between these stances to overcome obstacles and fight the Spirits of the Forest in a quick, intuitive and fun gameplay mechanic.' FROM games WHERE igdb_id = 17660 ON CONFLICT (game_id, language_code) DO NOTHING;
