INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Passing Pineview Forest', 'Passing Pineview Forest is a free mini-prequel set in the universe of Pineview Drive. Behind the abandoned house on Pineview Drive lies ominous Pineview Forest. The dark, foreboding forest trail leading directly to the Pineview property must be explored – but your every move and reaction is being watched. You must stay calm during your walk – or else IT will take you! To survive you will need steady nerves; for any trace of fear comes at a price — your life' FROM games WHERE igdb_id = 17988 ON CONFLICT (game_id, language_code) DO NOTHING;
