INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pacific Liberation Force', 'Are you ready to take up arms against El Presidente and his forces of evil? Taking place in a fully destructible environment, complete 18 challenging, trigger happy and arcade-like missions! You''ll be conducting aerial warfare versus a wide range of enemies, from simple footsoldiers to heavily armed tanks and from fighter jets to incredible carriers!' FROM games WHERE igdb_id = 17627 ON CONFLICT (game_id, language_code) DO NOTHING;
