INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('harmony-2', 175050, '2014-05-29', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sce49g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harmony 2', 'Escape the stress of the day and relax your mind... Featuring over two full hours of beautiful and mesmerizing ambient music. Even including rare and unreleased tracks! Music playlists are arranged harmoniously with the mood and style of each set of colorful puzzles… Hundreds of handcrafted levels, rich with color and organized into paths for your exploration. Awaken your mind to the bold colors of "refresh", relax to the peaceful pastels of "dream" or play the darker tones of "twilight" before you go to sleep... Each level becomes a journey with a destination as you strategically reassemble each color palette. Make a wrong move and you may take one step back. Venture too far the wrong way and you must start over. With a steady difficulty progression, levels go from fairly easy to insanely difficult. Think you can solve all of the levels? See how you rank in Game Center and challenge your friends! How far can you get? Enable Sleep Mode to quiet your mind at the end of a stressful day. Set the sleep timer and the dimming colors with unique music will help lull you to peaceful sleep... Adorn your iPhone, iPod or iPad with wallpapers rich with color! Every level you reach you can save its color palette as a wallpaper. Sit back... relax... and experience har•mo•ny 2.' FROM games WHERE igdb_id = 175050 ON CONFLICT (game_id, language_code) DO NOTHING;
