INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Cats vs Samurai Dogs', 'TIGA award nominated Ninja Cats vs Samurai Dogs combines the addictiveness of a tower defence game with the depth and tactical variety of a Real Time Strategy title. Choose your side in a fast paced and frenetic battle for canine or feline supremacy! Leading an army of Ninja Cats or Samurai Dogs has never felt so compelling! Construct buildings, gather resources and command your forces to victory across 65 exciting battles. Unlock new units, buildings and abilities through the deep skill tree and put your skills to the test to defeat your mortal enemies once and for all!' FROM games WHERE igdb_id = 16795 ON CONFLICT (game_id, language_code) DO NOTHING;
