INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney XD Grand Prix', 'Fans Can Burn Rubber as Animated Characters from Popular Disney XD Shows “Phineas and Ferb,” “Gravity Falls,” “Mighty Med,” “Kickin’ It,” “Lab Rats,” “Randy Cunningham: 9th Grade Ninja” and “Wander Over Yonder”. Disney XD has announced the launch of the “Disney XD Grand Prix” racing-game app for smartphones and tablets, which will have Disney XD fans revving up for victory with their favorite characters in a variety of high-octane game modes.' FROM games WHERE igdb_id = 361336 ON CONFLICT (game_id, language_code) DO NOTHING;
