INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Koopa''s Revenge 2', 'A Koopa’s Revenge 2 is a Super Mario fan game set in a parallel universe where Bowser and company are the good guys, while Mario and his pals are pure evil. After defeating Mario and his cohorts in the first game, Koopa sets off to a distant land where a kidnapped Bowser is being held by a mysterious robed figure. Play as Koopa, Goomba, or Shy Guy on your quest to free Bowser and restore justice to the Koopa Kingdom.' FROM games WHERE igdb_id = 307669 ON CONFLICT (game_id, language_code) DO NOTHING;
