INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Training Lair', 'Teenage Mutant Ninja Turtles: Training Lair is a free Xbox 360 Kinect game based on the 2014 film. The game is sponsored by Pizza Hut and features their advertising. Players will have the opportunity to use all four of the Ninja Turtles weapons and swipe at on-screen items for maximum ninja training.' FROM games WHERE igdb_id = 61291 ON CONFLICT (game_id, language_code) DO NOTHING;
