INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blinding Dark', 'You wake up in an entrance hall of, what seems to be, a mansion. You can''t remember who you are and how you got there. Step by step you adventure into the dark to discover your past and unfold your future. Collect ancient relics and discover what is their unique ability. Take your time and analyze the surroundings. Throwing yourself head on will often prove to be a deadly mistake.' FROM games WHERE igdb_id = 10053 ON CONFLICT (game_id, language_code) DO NOTHING;
