INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 4: Kyrat Edition', 'In Far Cry 4, players find themselves in Kyrat, a breathtaking, perilous and wild region of the Himalayas struggling under the regime of a despotic self-appointed king. Using a vast array of weapons, vehicles, and animals, players will write their own story across an exotic open-world landscape. The Far Cry 4 Collector''s Edition is the ultimate package. It includes: • Far Cry 4 Limited Edition game with a set of 3 bonus missions and a harpoon gun • 7.9 inch figurine of the villain Pagan Min seated on an elephant throne • 16.5x30 inch Pagan Min propaganda poster • Travel Journal • Map of the Himalayan open-world of Kyrat • Exclusive collector''s box' FROM games WHERE igdb_id = 41616 ON CONFLICT (game_id, language_code) DO NOTHING;
