INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Cruise Story', 'Get ready to take the helm of history''s grandest, most over-the-top luxury cruise liner for an unforgettably addictive excursion at sea! Deck your own ship with everything from lavish suites and first-class restaurants to casinos and hot tubs! You call the shots as you travel the world, visiting every country on the map--even entertaining royalty with tours truly fit for kings! Put the right facilities next to each other and you''ll score big points with passengers and reviewers. Amass enough fame and even celebrities will come flocking when you''re in port! Can you turn your sea buggy into a 5-star floating paradise? Put on your captain''s hat and find out in World Cruise Story!' FROM games WHERE igdb_id = 65518 ON CONFLICT (game_id, language_code) DO NOTHING;
