INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solar Wind', 'Blast your way through a galaxy of planets in this fast paced, campaign based shoot ''em up. Develop and customise your fleet to create the perfect defence to counter the threat of an unknown enemy. Fight in deep space, fly through asteroid belts, battle across desert, jungle and forest planets in an effort to stem the alien threat.' FROM games WHERE igdb_id = 76796 ON CONFLICT (game_id, language_code) DO NOTHING;
