INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choice: Texas', 'Choice: Texas is an educational interactive fiction game addressing reproductive healthcare access in the state of Texas. Play as one of five Texas women attempting to navigate the state''s reproductive healthcare system. Although billed as interactive fiction, Choice: Texas is based on extensive research into healthcare access, legal restrictions, geography, and demographics, and is reflective of the real circumstances facing women in the state.' FROM games WHERE igdb_id = 189279 ON CONFLICT (game_id, language_code) DO NOTHING;
