INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kahuna', 108548, '2014-02-06', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kahuna', 'Let the magical strategy game take you to paradise islands! As a powerful Kahuna priest, you‘ll fight exciting duels in order to conquer a paradisiac archipelago in the South Pacific. Build bridges to link the islands to each other, and try to expand your empire of islands as much as possible through three rounds of the match. You‘ll need a good strategy to do so; but only, if the gods are well disposed towards you, you’ll draw the right cards – and be able to conquer the beach paradise. In the single-player campaign, compete with the friendly fisherman, the skilful tattoo artist, the merciless warrior, or the ingenious chieftain; or prove yourself in multi-player matches against your friends or Kahuna players from all over the world. You’ll learn the simple rules of the exciting board game very quickly; however, conquering the island paradise will turn out well only for the best.' FROM games WHERE igdb_id = 108548 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 108548 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
