INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam: Extreme vs. Maxi Boost', 'Mobile Suit Gundam: Extreme Vs. Maxi Boost is an arcade game and updated version of Mobile Suit Gundam: Extreme Vs. Full Boost, released on March 6, 2014. Much like Full Boost, the game will introduce both new suits and characters as well as new game mechanics such as a revamped EX Mode and changes to forms for certain units. The theme song is Rave-up Tonight by Fear and Loathing in Las Vegas. It is later followed up by a portable spinoff, Extreme Vs Force and an update in Maxi Boost ON.' FROM games WHERE igdb_id = 79865 ON CONFLICT (game_id, language_code) DO NOTHING;
