INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mythos: The Beginning', 'Mythos: The Beginning is a survival horror/adventure role playing game based on the pulp-horror and monster movies of the 1930s. Set in London in 1934, Mythos tasks you with creating your own paranormal investigator from scratch and guiding them through an exploration of the infamous Harborough Asylum.' FROM games WHERE igdb_id = 36206 ON CONFLICT (game_id, language_code) DO NOTHING;
