INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Claustrophobia: The Downward Struggle', 'Grab your weapon of choice, polish your Rogue senses, and get ready to be thrown into the dark and oppressing dungeons of Claustrophobia! Experience deep character development, fast-paced tactical combat, and mountains of epic loot. Here begins a roguelike quest for glory, slaughter, and anything shiny!' FROM games WHERE igdb_id = 9797 ON CONFLICT (game_id, language_code) DO NOTHING;
