INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rabbids Invasion: Gold Edition', 'Rabbids Invasion, the kids hit animated TV show, is now an interactive game. Kids can now play in their living room with a selection of episodes from the TV show. Through fun, silly challenges, players have an outrageous time with family and friends and experience the Rabbids Invasion TV show in a brand new way. This edition also comes with the season pass.' FROM games WHERE igdb_id = 82425 ON CONFLICT (game_id, language_code) DO NOTHING;
