INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'POP: Methodology Experiment One', 'POP: Methodology Experiment One is an experimental game by Rob Lach which dissects the impact of reinterpreting the typical game development process and following a self-prescribed dogma to its creative conclusion. POP takes you on a visual and emotional roller-coaster, throwing at you a series of disjointed interactive vignettes of ranging purpose, visual style, and frustration.' FROM games WHERE igdb_id = 17515 ON CONFLICT (game_id, language_code) DO NOTHING;
