INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TPM Football', 'Inspired by football classics, TPM has 11v11 gameplay, team matches, skill challenges, community events and best of all, huge amount of customization! Style your player with dozens of hairstyles! Make your own team or join one! Become a goalkeeper if you want! Play on 4 different servers or make one for your friends! Limitless skillcap but easy mouse and keyboard controls.' FROM games WHERE igdb_id = 151536 ON CONFLICT (game_id, language_code) DO NOTHING;
