INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sharpe Investigations: Death on the Seine', 'Journalist-turned-food critic Taryn Sharpe and her assistant/photographer George Haske are sent on assignment to France to cover the opening of Paris''s hottest new restaurant, Le Roi Soleil. When they get there, they discover the restaurant''s celebrity chef is dead and the circumstances are suspicious. Strangely, the police rule the death a suicide and refuse to investigate. The restaurant''s owner (an old friend of Taryn''s) is convinced his star chef was murdered and begs her and George to find the culprit.' FROM games WHERE igdb_id = 10822 ON CONFLICT (game_id, language_code) DO NOTHING;
