INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gardens Inc. 2: The Road to Fame', 'Jill & Mike have established their gardening company in Sunnyvale and now they are ready for the next step. Unfortunately, the dastardly Cliff Gold escaped prison and it seems that he is out for revenge on those who brought him to prison. Help Jill & Mike to win a contest that will be followed by contracts all over the world and uncover, what the villain is really up to.' FROM games WHERE igdb_id = 17398 ON CONFLICT (game_id, language_code) DO NOTHING;
