INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-warriors-4-special-anime-pack', 178296, '2014-10-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7r7g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar17wi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors 4: Special Anime Pack', 'Samurai Warriors 4 is a hack and slash game, and sequel to Samurai Warriors 3. The game was made to celebrate the tenth anniversary of the series. The game features a character-switching feature, similar to the spin-off, Samurai Warriors: Chronicles, with which players can take two characters into battles simultaneously, and freely switch between the two. Two new moves, "Hyper Attacks" and "Rage Mode" are featured in this game: Hyper Attacks is a secondary moveset available to all characters that allows the player to sweep through and clear out crowd of enemies with a dashing animation, although it is useless against enemy officers, as they will either deflect it or are otherwise immune against it. Rage Mode renders the player invincible for a period of time, and also enhances the player''s attacks as well as empowering their Musou attack by using the Spirit Gauge. Exclusive Content: Special Anime Pack 10th anniversary Collector''s Edition packaging SAMURAI WARRIORS: Legend of the Sanada anime (Blu-ray Disc) SAMURAI WARRIORS 4 (PS4 game) SAMURAI WARRIORS 4 Official Soundtrack (CD) Special Costume Pack 4: Garcia, Ina, Nene and Oichi (DLC)' FROM games WHERE igdb_id = 178296 ON CONFLICT (game_id, language_code) DO NOTHING;
