INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-wolfenstein-hd', 50279, '2014-11-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21h4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc82bb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Wolfenstein HD', 'Super Wolfenstein HD is a short Wolfenstein 3D fangame made for the PewDiePie Game Jam developed in 72 hours. It offers a short amount of levels inspired by the original game with a full 3D engine as the main difference. Every level is built up out of blocks and the player can chip away at them Minecraft-style to break through walls and create passages. Enemies such as soldiers and dogs have exaggerated physics, causing them to stumble around. The three available weapons are throwing knives, a pistol and a shovel. The first two have a limited amount of ammo, but thrown knives can be picked up again. The shovel can be used to knock weapons out of enemies'' hands. There are also health packs and by breaking through certain walls secret areas can be discovered. Instead of the typical catchphrases enemies will for instance shout ''Oktoberfest''.' FROM games WHERE igdb_id = 50279 ON CONFLICT (game_id, language_code) DO NOTHING;
