INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Synonymy', 'Synonymy is a non-profit, educational word game narrated by Richard Dawkins where players are challenged to find a path between random words through their network of synonyms. By taking the synonym of a word, and then a synonym of that synonym, and so on, you can ultimately arrive at any other word in a language.' FROM games WHERE igdb_id = 35925 ON CONFLICT (game_id, language_code) DO NOTHING;
