INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('el-chavo-kart', 62461, '2014-02-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ia8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ofnkxaj37lwulcm457j5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'El Chavo kart', 'El Chavo Kart is a mascot-based kart racing game, in the same vein as Konami Krazy Racers, Nicktoons Racing, Mickey''s Speedway USA, Diddy Kong Racing, Crash Team Racing and the Mario Kart series. Players get to compete as characters from the series (except for Jamito and Gloria), along with tracks loosely based on locations from the animated series. The game offers three game modes: Cups, Exhibition, and Challenges. In "Cups", the player can unlock characters, while at the end of "Challenges" scenarios and tracks are unlocked. The player can collect power-ups along the race which can be used to benefit himself and gain an advantage in the race. Tracks include series features and scenarios such as Azteca Stadium, the city of Acapulco, the Maracana Stadium in Rio de Janeiro and also Stadium TFC in Toulouse. Each track can be raced in the opposite direction, and include alternative paths, traps and obstacles. The game features local multiplayer, allowing up to four players to compete against each other simultaneously. The game features 45 trophies or achievements that can be unlocked to progress through the game.' FROM games WHERE igdb_id = 62461 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 62461 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
