INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avoid: Sensory Overload', 'Avoid is a fast-paced arcade game that will test your reflexes. Drive your vehicle through an obstacle-filled course and try to go as far as you can. Grab bonus items to help you survive... just a little bit more. Climb up the online leaderboard and show the world who''s best! Are your fingers fast enough?' FROM games WHERE igdb_id = 17169 ON CONFLICT (game_id, language_code) DO NOTHING;
