INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daily Espada', 'In Daily Espada from Pidroh, players assume the role of a family man drawn into Brazil’s most bizarre game show, as he fights hordes of monsters from Brazilian mythology. Maneuvering through fireballs and dodging enemy attacks in Daily Espada’s fast-paced combat is simple when compared to the protagonist’s struggle with his dysfunctional family.' FROM games WHERE igdb_id = 34690 ON CONFLICT (game_id, language_code) DO NOTHING;
