INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Celestial Command', 'Celestial Command is a realistic sandbox space game which unites real space flight, real orbital mechanics, and all the fun of classic space action games. We want to show how games about space actually should look, without silly vacuum friction and the maximum speed limit. As in the real world, everything in this game is in continuous motion in orbit.Realistic Orbital Mechanic' FROM games WHERE igdb_id = 17978 ON CONFLICT (game_id, language_code) DO NOTHING;
