INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatblasters-iii', 9045, '2014-02-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2isd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xwxru28gbkcxqlekxjr7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BeatBlasters III', 'Steam Big Picture About the GameWelcome to Accapella! When Joey and Gina arrive in the musically starved town that outlawed groovy tunes, a chance encounter with the music hating tyrannical ruler of the town (and local butcher) sends them flying. Now lost in the wilderness outside town, Joey and Gina have made it their mission to return to Accapella and put an end to The Butcher’s reign of silence. To make it back they’ll need to earn the trust and aid of the zany locals by helping them with all manner of chores and tasks. Armed only with the power of music and rhythm, Joey and Gina are in for the adventure of a lifetime! Key FeaturesCombination rhythm game and action-platformer. Strange world filled with fantastical, original creatures. 3 music powered abilities : An attack power, a shield and a pair of rocket boots. Refill your powers by tapping your fingers to the groovy beat. An awesome electro soundtrack for each character. Unlock new powers as you advance through the levels. Unlock Insane mode for additional challenge.' FROM games WHERE igdb_id = 9045 ON CONFLICT (game_id, language_code) DO NOTHING;
