INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panic Crisis Mage Attack', 'Panic Crisis Mage Attack is a horizontal shooter in which you play as a mage and shoot things with magic on a magical adventure at a magical castle.  Features:  * Main scenario with 5 stages and 6 bosses  * Epilogue scenario for players with high endurance  * Vengeance scenario for masochistic players  * Four difficulty settings, from Casual to Master  * Two playable characters' FROM games WHERE igdb_id = 128636 ON CONFLICT (game_id, language_code) DO NOTHING;
