INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('living-playground', 125548, '2014-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6iv5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3jof.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living Playground', 'Siblings Octavio, Tony, and Pablo are exploring outside of an abandoned factory, looking for the world’s best snails. You can guess where this is going. Living Playground is a short puzzle-based adventure game with a dash of horror theming for flavor. The player controls Tony, the cheerful slide girl, as she attempts to reunite with her brothers and find an exit while avoiding multiple untimely ends. Conveniently, the children aren’t human but are living toys themselves, playground equipment which can take human form. Along the way, they uncover interesting details about the factory they''re trapped in. What happened to the rather cheery-sounding owner? How did things get this WEIRD? At least the monster parts make sense, because there are some strange playthings wandering the factory.' FROM games WHERE igdb_id = 125548 ON CONFLICT (game_id, language_code) DO NOTHING;
