INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('draconian-wars', 17324, '2014-08-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zngtqllwd9qg8bod7wkc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xdccdtchlframi5tlrjn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Draconian Wars', 'Are you ready for a new level in online card games? Draconian Wars is possibly the most strategic and challenging online card game out there. Engage in fierce combats, manage your limited resources and outmaneuver your opponent. Draconian Wars is a game of combat, resource management and battlefield tactics. The battlefield is the lands and skies of Hyperborea, an exotic continent rich in natural resources, with a wide variety of ecosystems and full of amazing and terrifying creatures. During thousands of years Hyperborea has been under the uncontested control of the Draconians, but now the Technocrats have arrived to the shores of the continent and they claim what once was theirs. The control of the land is what will bring victory to one or other. The Draconian extract their magic power from the earth, consuming the live and the natural resources around them. On the other hand, the power of the Technocrats comes from carbon and steel, both equal abundant in Hyperborea. A battle for supremacy over Hyperborea has begun and one thing is clear, no matter who wins, the scars on the lands of Hyperborea will last for centuries. In Draconian Wars players build their decks of 50 cards and try for their opponent to run out of resources. They can accomplish this by controlling as much areas of hyperborea as they can, or just crushing the opponent in battle. Players have a mixture of ground and air units to spread terror across the lands of Hyperborea. Also, they have a lot of surprises that can change the fate of any battle. The options are endless.' FROM games WHERE igdb_id = 17324 ON CONFLICT (game_id, language_code) DO NOTHING;
