INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Auro: A Monster-Bumping Adventure', 'Auro is a unique turn-based tactical dungeon-crawler all about bumping monsters into the water. Traverse randomly generated maps and create huge spell combos as you compete against rival Kingdoms and rise through the ranks. Auro is a different kind of game: no grinding, no IAPs, no chores -- just challenging tactical gameplay that forces you to think creatively to win. In other words: Auro is all bump, no grind.' FROM games WHERE igdb_id = 33099 ON CONFLICT (game_id, language_code) DO NOTHING;
