INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Next Stop', 'NEXT STOP is a game that will send you on a trip down a railroad, which needs to be pulled up from dilapidation and defended against a bank that wants to lay hands on it to offset its debts. By making a lot of stops, you can repair and build up all damaged parts of the railroad, but you need to ensure that you have enough resources. Trade and train passage on your reviving railroad will bring you a substantial income.' FROM games WHERE igdb_id = 87314 ON CONFLICT (game_id, language_code) DO NOTHING;
