INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('castlevania-lords-of-shadow-2-draculas-tomb-premium-edition', 112642, '2014-02-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3dby.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5qq2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Lords of Shadow 2 - Dracula''s Tomb Premium Edition', 'Sink your teeth into Castlevania Lords of Shadow 2 - Dracula''s Tomb Premium Edition, which includes: A copy of Castlevania Lords of Shadow 2. The exclusive Steelbook. 100 page hardback artbook. 3 miniature figurines (approx 10cm high) consisting of Zokek, Victor Belmont and The Lieutenant All sealed in a Collector''s Edition Tomb box. In-Game "Armoured Dracula" Skin - Includes a full length, leather textured coat with new filigree designs throughout and completely redesigned central belt armour. New battle greaves and pants with adorning paraphernalia add a powerful finish. Dracula himself has a new beard to complete the look. In-Game "Dark Dracula" Skin - Alternate colouring for Dracula’s iconic costume from Castlevania: Lords of Shadow 2. Taking its cues from the classic designs of past Castlevania games, this costume includes the classic white hair & beard colouring for the ultimate Prince of Darkness. In-Game Relic Pack - Gives you access to most of the game’s relics once you find your first drop. These each have a different effect, some enhance your skills, some enhance your abilities, while others have a more mysterious and surprising effect! Using the exclusive transmutation rune offered in this pack, players who pre order can change relics at will allowing them to always have the best one for any given situation.' FROM games WHERE igdb_id = 112642 ON CONFLICT (game_id, language_code) DO NOTHING;
