INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-boo-album', 373238, '2014-12-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaoa8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sczryi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Boo Album', 'Boo boo, hey you! It you love My Boo, you can''t miss the official sticker album from your favorite pet monster! Earn FREE packets every day and rip them open to find surprise themed stickers that you can stick to your album or even exchange with friends! Each page of your album has its own story to tell. Can you unveil them all?' FROM games WHERE igdb_id = 373238 ON CONFLICT (game_id, language_code) DO NOTHING;
