INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alias-carnival', 78478, '2014-03-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yim.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2232.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alia''s Carnival!', 'The Sakumo ward is well known for its cherry blossoms. In recent years, as part of the redevelopment of the ward, an experimental education system was introduced where the students would govern themselves in the newly constructed Sakumodai Gakuin to improve the student life. Those students who are capable and work hard to improve the learning environment would receive various benefits. Also, it seemed that the one with the top results would get a special privilege. Ren returned to Sakumo ward after a long time away and transferred into the school, reuniting with his timid little sister Karin and childhood friend Shiina, who had grown up to be very beautiful. On his first day at school, he was caught up in some trouble and ended up saving a girl. The girl Asuha asked him to join her club, aim for ALIA and change the school. He was puzzled over her sudden invitation, but was excited that his new school life will be surely be an exciting one.' FROM games WHERE igdb_id = 78478 ON CONFLICT (game_id, language_code) DO NOTHING;
