INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ACE Arena: Cyber Evolution', 'Arena: Cyber Evolution (ACE) is a futuristic physics-based sports game in which players confront each other in 3 vs 3 matches of wits and twitch reflexes. By featuring a MOBA-like champion logic, ACE brings an unprecedented twist to the sports genre by allowing players to choose from a variety of super-powered heroes and what style of gameplay they prefer to build their own team strategies.' FROM games WHERE igdb_id = 17155 ON CONFLICT (game_id, language_code) DO NOTHING;
