INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Hero: Unsigned Legacy', 'Save the world in ''Fantasy Hero -Unsigned Legacy-'', by choosing from one of four heroes, and reclaiming what was lost to the Decoders! Set yourself on fire and charge head on, or pulverize them with powerful throws. Like keeping a safe distance from your opponents? Then, pick them off with projectiles, or send your robot to do your bidding. The variety of combat styles and skills will let players build heroes to their liking.' FROM games WHERE igdb_id = 36546 ON CONFLICT (game_id, language_code) DO NOTHING;
