INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cognition: Game of the Year Edition', 'Winner of six 2013 Reader’s Choice Aggie Awards, including Game of the Year, this edition of Cognition includes all 4 episode, Volume 1 of the soundtrack, the prequel e-comic Provenance, plus brand new director commentary for all 4 episodes and exclusive content including concept art, storyboards, outtakes and other behind-the-scenes material about the development! Take on the role of Erica Reed, a Boston FBI agent with the power to see the past, as she follows the trail of four different serial killers, and a series of clues left for someone with her specific ability. Who’s leaving the clues? How do they know her secret, and what do they want from her?' FROM games WHERE igdb_id = 51700 ON CONFLICT (game_id, language_code) DO NOTHING;
