INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A.R.E.S. Extinction Agenda EX', 'A 2.5D action-packed side-scrolling game, takes players on a thrilling sci-fi adventure! Take control of combat specialist Ares, or the new playable character, Tarus, to battle deadly machines with a variety of powerful weapons and armor. Your goal: Save Minos Space Station’s survivors and uncover the nefarious Zytron’s extinction agenda!' FROM games WHERE igdb_id = 36270 ON CONFLICT (game_id, language_code) DO NOTHING;
