INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons: The Eye of Draconus', 'Dungeons the Eye of Draconus is a early 90’s arcade style, one to three player, comedy, retro brawler, with both local and online multiplayer support, complete with mounts; multiple attacks, and varied gameplay, all reminiscent of Battle Toads, Golden Axe and TMNT Arcade.' FROM games WHERE igdb_id = 17444 ON CONFLICT (game_id, language_code) DO NOTHING;
