INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Secret of Hildegards', 'Abigail Hildegard, daughter of the leader of secret order, once she was told that her father disappeared. She should go to the family estate, headquarters of the Order, to find out what happened. She finds the family butler there . He was lucky not to suffer in a raid on a house and told Abigail that a secret weapon is kept in the house. And with it help it will be able to rescue her father out of trouble.' FROM games WHERE igdb_id = 9482 ON CONFLICT (game_id, language_code) DO NOTHING;
