INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Obludia', 'Obludia is an old-school arcade arena action inspired by classics such as Robotron or Smash-TV with RPG elements. You play as a demon hunter whose purpose is to survive in a dangerous dungeons. Fight your way through 50 levels full of thrilling action with hordes of challenging enemies and tough bosses. Enjoy mighty power-ups and deadly weapons!' FROM games WHERE igdb_id = 17657 ON CONFLICT (game_id, language_code) DO NOTHING;
