INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ryuu ga Gotoku Ishin!', 'Ryuu ga Gotoku Ishin! is a historical action-adventure game developed by Ryu Ga Gotoku Studio and published by Sega. Released exclusively in Japan in 2014 for PlayStation 3 and PlayStation 4, it is a spin-off of the Yakuza series, set during the Bakumatsu period of late Edo-era Japan (mid-1800s). The game follows Sakamoto Ryoma, a samurai modeled after series protagonist Kazuma Kiryu, as he becomes embroiled in political turmoil and seeks revenge for his mentor''s assassination. The gameplay combines the brawler-style combat of the main Yakuza series with swordplay and gunfighting mechanics. Players can engage in the main story, participate in side activities, and explore the historical setting of Kyo (based on Kyoto).' FROM games WHERE igdb_id = 12736 ON CONFLICT (game_id, language_code) DO NOTHING;
