INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Kills', 'Action-packed death racing, this is what Speed Kills is about! Traditional, isometric, powered by Unreal Engine. Players compete in various championships, ranging from bootleg rallies on the outskirts of the galaxy to big-league circuits set against the goliath skylines of metropolis cityscapes. You can purchase offensive and defensive vehicle upgrades, buy new cars, collect power-ups and earn bonuses.' FROM games WHERE igdb_id = 10837 ON CONFLICT (game_id, language_code) DO NOTHING;
