INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Tale of a Common Man', 'Undefeated''s devs are back with a bigger, better tale of a man seeking revenge for the cruel murders of his wife and son. Can Jerrat achieve his aim without ceasing to be the man his wife loved? Find out in this great 16-bit style RPG, where the tale of a common man intertwines with the destiny of a nation.' FROM games WHERE igdb_id = 23489 ON CONFLICT (game_id, language_code) DO NOTHING;
