INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannons Lasers Rockets', 'Cannons Lasers Rockets is a fast-paced, bright and colorful space arcade equally enjoyable for hardcore and casual gamers. For victory you need only three tools - cannons, lasers and rockets! Discover a spaceship MOBA game with 2D combat in 3D environment, wide variety of play styles, and fun gameplay for casual and pro gamers alike. Cannons Lasers Rockets has both light-hearted gameplay and deep tactical potential that allows for sophisticated approach to team play.' FROM games WHERE igdb_id = 16870 ON CONFLICT (game_id, language_code) DO NOTHING;
