INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Talking Poppet', 'POPPET IS GOING SOLO WITH HER FIRST EVER APP! Talk to Poppet and she’ll repeat in her own funny voice! You can also poke, tickle and interact with her to bring her to life! Explore the Fun Room, do a photo shoot or have a boogie in the Disco! Talk to Poppet and she’ll repeat in her own funny voice! Feed, tickle & bathe Poppet. Let Poppet pose in your photos! Give Poppet her pencil & watch her draw. Watch Poppet dance to her favourite music! Explore the magical Moshling Garden. Play with 8 hilarious Moshling voices.' FROM games WHERE igdb_id = 395523 ON CONFLICT (game_id, language_code) DO NOTHING;
