INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic DJ', 'Cosmic DJ is a quick, "pick-up and play" musical experience about the joy of music creation for budding intergalactic musicians of all skill levels. Set among the stars, you will strive to become the legendary Cosmic DJ through six musical adventures as you’re tasked with repairing the all-important “Jamtennas” and bring harmony back to the galaxy.' FROM games WHERE igdb_id = 14400 ON CONFLICT (game_id, language_code) DO NOTHING;
