INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Acid Bunny 2', 'Acid Bunny returns! But this time, the action takes place on the beach, in the jungle, and in a whole new Down Below level. And in addition to these locations, the game also features a range of mini games, cut scenes, and a ton of other fun stuff!' FROM games WHERE igdb_id = 394888 ON CONFLICT (game_id, language_code) DO NOTHING;
