INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'School Bus Fun', 'School Bus Fun features a heart-warming story about a mother taking her daughter and her friends to school who takes this up as a profession investing in new cars and equipment. The game offers a variety of unique maps, vehicles, upgrades, characters, cutscenes, trophies and much more. Meet and transport all the kids with their different personalities and preferences! Learn to cope with varying demands and aim for the perfect scores and all gold trophies.' FROM games WHERE igdb_id = 17410 ON CONFLICT (game_id, language_code) DO NOTHING;
