INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cult of the Wind', 'Cult of the Wind is a game about people who pretend to be airplanes. "In an unknown time and place, a cult that worships the wreckage of ancient airplanes gathers to mimic the dogfights of old. With the peak of humanity far behind, their world is a mausoleum to a lush and verdant Art Deco past.' FROM games WHERE igdb_id = 9816 ON CONFLICT (game_id, language_code) DO NOTHING;
