INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla: Smash 3', 'Unleash the power of Godzilla and pursue the dangerous MUTO monsters in this unique mix of jaw-dropping 3D action and challenging puzzles. Control each stomp, slash, and bite by matching - or SMASHING - puzzle tiles to drive Godzilla through 80 levels in cities across the globe.  Upgrade Godzilla to match your play-style and call upon friends in times of need. Use powerful boosts to conquer new objectives and puzzles in each level, or build up energy to release Godzilla’s signature ATOMIC BREATH.' FROM games WHERE igdb_id = 61983 ON CONFLICT (game_id, language_code) DO NOTHING;
