INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danmaku Amanojaku: Impossible Spell Card', 'Danmaku Amanojaku ~ Impossible Spell Card is a danmaku game and the 14.3rd official installment of the Touhou Project, featuring Seija Kijin as the main protagonist. The game was released at Reitaisai 11. As the title implies, it is a spinoff game consisting mostly of (near-)impossible-to-beat spell cards.' FROM games WHERE igdb_id = 47026 ON CONFLICT (game_id, language_code) DO NOTHING;
