INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DIG IT! - A Digger Simulator', 'Do you love that moment when the engine starts and that rich diesel sound fills the air? Do you get a kick out of moving earth with a variety of high-powered diggers, bulldozers and dump trucks? Do you yearn for the feeling of power that flows through you as the hard steel of the bucket digs into the earth while you remain in keep complete control?' FROM games WHERE igdb_id = 17593 ON CONFLICT (game_id, language_code) DO NOTHING;
