INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Hakujinki: White Names Spoiled Past', 'A Touhou fangame developed by NRT. Unlike the regular Touhou games, White Names Spoiled Past incorporates mystery-solving elements in addition to danmaku. While playing the game normally, the player should pay attention to the story and the dialogue, which contain hints as to the identity of the culprit. The Extra Stage can only be unlocked by correctly answering the order of events and the true culprit. In addition, this game has 3 stages instead of the standard 6, with even more emphasis on replayability.' FROM games WHERE igdb_id = 246674 ON CONFLICT (game_id, language_code) DO NOTHING;
