INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('phantasy-star-nova', 42674, '2014-12-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co554a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8992.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantasy Star Nova', 'Phantasy Star Nova will be set in the same world as Phantasy Star Online 2 but will drop many of the online elements and take on a much more single player approach. If the idea of playing without your friends sounds horrifying, the game will include 4-player co-cop play. The title takes place on Planet Machia, a planet where ''Photon'' energy is useless. Without the ability to recover energy or upgrade your weapons, players must take survival into their own hands, exploring the planet of Machia and unlocking the secrets it has to offer. The creatures inhabiting Machia are giant beasts appropriately named ''Gigantes.'' In order to take these massive brutes down, you''ll need to find and hit their weak spots together with your allies. Sega also implemented tweaks based off the Phantasy Star Nova battle demo into the game. After the first demo, tri-Ace increased character movement speed by 1.4x, reduced input delay, fixed issues with locking on to enemies, and fine tuned the speed of the camera, among other improvements.' FROM games WHERE igdb_id = 42674 ON CONFLICT (game_id, language_code) DO NOTHING;
