INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asteria', 'Asteria is a fast paced indie platformer, wrapped up in a sandbox sci-fi world where everything is destructible, mineable, collectable, craftable and creatable. You play Ryker: the only surviving human colonist after your people were wiped out by local aliens. Now you’re stranded on Asteria, with no means of escape. This isn’t just about survival, it’s about revenge. Build your safe haven and go track down the aliens who destroyed your colony.' FROM games WHERE igdb_id = 17536 ON CONFLICT (game_id, language_code) DO NOTHING;
