INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Munich Bus Simulator', 'A new milestone in simulation: Citybus Simulator Munich, the successor of the popular City Bus Simulator 2010 - New York, covering the complete 100 line also known as the museum line. Starting at the main Rail Station Nord it passes 22 museums and other sightseeing spots to conclude its journey at Munich´s "Ostbahnhof". The true courses of the roads have been designed in an unbelievable graphical detail. For the first time ever the technical aspects of a bus simulator have been modeled and are based on a real training simulator making the driving characteristics absolutely realistic.' FROM games WHERE igdb_id = 36440 ON CONFLICT (game_id, language_code) DO NOTHING;
