INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo Trainz', 'Turbo Trainz is a fast paced train race which gets your heart thumping and your thumbs pumping! Take up the challenge and race against the best drivers from around the world to compete for the Turbo Cup! Your opponents are cunning and will stop at nothing to win. Watch they don’t fire a missile up your caboose, make you lose control with an oil spill or bully you off the rails with many other special tactics. You can fight back with many of your own abilities to even up the race!' FROM games WHERE igdb_id = 193702 ON CONFLICT (game_id, language_code) DO NOTHING;
