INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Loot', 'Deep Loot is an oceanic explore-’em up. There''s loot, deadly sea creatures and secrets to be found. On-the-fly procedural content means you can explore the ocean in every direction without limits and without waiting. There are hundreds of unique loot items to find as well as equipment and upgrades to spend your profits on. Soon you''ll be zapping the denizens of the deep with white-hot plasma as you plunder ancient ruins for legendary treasures, well on your way to becoming the world''s greatest Deep Looter!' FROM games WHERE igdb_id = 271930 ON CONFLICT (game_id, language_code) DO NOTHING;
