INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Found Horror Game 11.exe', 'An ''episodic'' horror game with 11 episodes/games, with a new one released every time the community accomplishes something. The games comes from the mind of Dusk Golem aka AestheticGamer, and weren''t channeled from someplace else. At least, that''s what I''d like to believe. What do you believe?' FROM games WHERE igdb_id = 74626 ON CONFLICT (game_id, language_code) DO NOTHING;
