INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Other Side: Tower of Souls', 'Beatrice and Lily might look like any other pair of sisters, but they have a dark secret: Hidden from human eyes is a magic tower that contains a portal to the Other Side. One sister wants to open the gateway to gain knowledge and power, regardless of the consequences; the other sister wants to stop her. But which one is good and which one is evil? Step into the shoes of a detective who must decide in The Other Side: Tower of Souls.' FROM games WHERE igdb_id = 53765 ON CONFLICT (game_id, language_code) DO NOTHING;
