INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Detective in the Pirate''s Cove', 'Solve the mystery in the Pirate''s Cove and uncover your lost memories in this hidden object game. After waking up on a deserted beach with no memory of who you are, you set out to find the one person who can help you. But when you arrive at the nearest seaside town, you learn that memory loss isn''t your only problem. The seaside village is buzzing with reports of strange events. Hold your breath and dive into this thrilling adventure in "Hidden Object - Detective in the Pirate''s Cove".' FROM games WHERE igdb_id = 194188 ON CONFLICT (game_id, language_code) DO NOTHING;
