INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lacrosse Arcade 2014', 'Dodge, pass, shoot, and defend like never before on your mobile device. Lacrosse Arcade 2014 is a simulation lacrosse video game featuring five lacrosse game modes, and intense lacrosse action! Download Lacrosse Arcade 2014 today! 1) 1v0 - Shooting on a goalie 2) Offense Transition - Work through 2v1, 3v2, 4v3, 5v4 situations 3) Fours - 4v4 mini game 4) Horde - Weave through over 10 players! 5) Practice - Want to work on fast breaks? No goalie? Play defense?' FROM games WHERE igdb_id = 87204 ON CONFLICT (game_id, language_code) DO NOTHING;
