INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantibus', 'A neon lit world filled with nightmare creatures and bizzare situations exists by the name of Tantibus. Journey from your very normal and totally boring home where nothing weird ever happens of Cobble''s Key to whatever exists past the first boss. Be there man eating clocks? Be there vomiting gardeners? Be there depressed lamps? Be there faceless men? Yup!' FROM games WHERE igdb_id = 124589 ON CONFLICT (game_id, language_code) DO NOTHING;
