INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Run for Cheese', 'Run to gather cheese! Jump to avoid obstacles and feed the mice! You’re the almighty shaman mouse. Gather as much cheese as possible to feed the starving mice in this original endless runner. Jump from one platform to the next, avoid deadly traps and enemies. Pick up powerups to rush farther and get even more cheese. Rediscover this cute and fun mice world on your mobile phone and computer tablet. Om nom nom, cheese is so good!' FROM games WHERE igdb_id = 174356 ON CONFLICT (game_id, language_code) DO NOTHING;
