INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Temple of the Faceless Minotaur Who Sees the Burning Light', 'Temple of the Faceless Minotaur Who Sees the Burning Light (TotFMWStBL for short) is made for #lowrezjam and is a roguelikelike with randomly generated levels. I''m extremely happy with how it turned out (especially considering the timeframe) and I hope you enjoy playing it. Expect to die a lot as you learn the ins and outs of the game.' FROM games WHERE igdb_id = 128616 ON CONFLICT (game_id, language_code) DO NOTHING;
