INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Bloopy Saves the World', 'In 1995 Rare Compedia decided to combine puzzle-based-platforming and a "save the environment" message to create a uniquely challenging children’s game for the Super Nintendo. The game was never released in the lifespan of the SNES, but in 2008 the game leaked online and later received an aftermarket release by Piko Interactive.' FROM games WHERE igdb_id = 42659 ON CONFLICT (game_id, language_code) DO NOTHING;
