INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '20 Useless Apps', 'Yes, 20 Useless Apps, from an egg-laying simulator to a scanner that counts the bacteria on your finger! This all-in-one useless app collection has it all! See what it''s like to be dead using the death simulator! Witness breakthrough cliff-jumping A.I. technology! This useless collection has it all!' FROM games WHERE igdb_id = 243962 ON CONFLICT (game_id, language_code) DO NOTHING;
