INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Long Way Home: Director''s Cut', 'You have been stranded 100 light years from Earth, can you survive the long way home? After a catastrophic ship explosion, you must make your way home 1 light year at a time. Encounter exploding asteroids, teleporting dark matter, comets, aliens and more on your epic journey home. A Long Way Home is a action / physics / puzzle game set in space. Making you way through 100 levels across 10 stages you must jump from asteroid to asteroid collecting enough dark matter to open a portal to the next level.' FROM games WHERE igdb_id = 201938 ON CONFLICT (game_id, language_code) DO NOTHING;
