INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatbuddy HD', 'Beatbuddy is an action-adventure where players solve puzzles and vanquish enemies in six beautiful hand-drawn worlds, each with their own amazing soundtrack composed by industry legends such as Austin Wintory, Parov Stelar, chiptune-genius Sabrepulse, the La Rochelle Band -- and more to come with free exclusive DLC''s post-launch. Can you save the music on Symphonia?' FROM games WHERE igdb_id = 175102 ON CONFLICT (game_id, language_code) DO NOTHING;
