INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackgate', 'A human unwittingly enters Blackgate, a strange town hidden between universes and inhabited by monsters who have been lured in from multiple dimensions. Unable to leave, he must acclimate to his new environment and begin a new life. However, having heard rumors about the nature of humans, Blackgate''s current residents fear him, and whisper among each other of what his relationship could possibly be to The Eternal—a frightening and powerful force beyond comprehension. A currently in-development visual novel.' FROM games WHERE igdb_id = 138226 ON CONFLICT (game_id, language_code) DO NOTHING;
