INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flapple Bird', 'Flapple Bird is a 1-player arcade game for the Apple II. Designed as an Apple II variant of Flappy Bird, the player controls a small bird that flaps its wings when the player taps a button, rises, and then shortly thereafter loses altitude. The player must guide their bird through a series of breaks in tubes, gaining one point for every tube successfully navigated. It''s game over if the player hits a barricade, with goal to maximize score.' FROM games WHERE igdb_id = 222746 ON CONFLICT (game_id, language_code) DO NOTHING;
