INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Storm Rush', 'Storm Rush is an relentless test of speed, skill and concentration. Easy to learn, hard to master, impossible to put down. Storm Rush places you on a never ending road that is created before your eyes! Move left and right to avoid the glowing towers. Or Hit one and watch as the world explodes spectacularly. Its mixture of fast paced, adrenaline fuelled game play and unique visuals makes Storm Rush a compelling experience.' FROM games WHERE igdb_id = 200098 ON CONFLICT (game_id, language_code) DO NOTHING;
