INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quing''s Quest VII: The Death of Videogames', 'You are a young monarch of mysterious and indistinct gender, valiantly trying to survive exile from your home planet - or whatever''s left of it since the invasion, anyway. This game features music, sound effects, incisive social commentary, old-school adventure game references, a cute genderfluid pirate NPC, a working toilet, and glitter.' FROM games WHERE igdb_id = 128593 ON CONFLICT (game_id, language_code) DO NOTHING;
