INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alchemy 1000', 'This classic alchemy puzzle game starts off with the four basic elements - Air, Water, Earth and Fire. Mix them together and create new elements. Make Santa Claus, a crocodile, a skeleton, sushi, or an elephant! Can you create and discover all 1000 elements? This premium brain teaser provides hours of exploration, creativity and fun. Play and share your progress with your friends. Caution - this game is addictive, and could keep you busy all day! :)' FROM games WHERE igdb_id = 134383 ON CONFLICT (game_id, language_code) DO NOTHING;
