INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'De I Cide', 'De I Cide is a traditional Yume Nikki fangame. This game features mostly dark and disturbing themes and has a rather unusual soundtrack, consisting of metal and trance tracks in contrast to calm piano music. It stars a girl with messy hair named Inahoozuki and a silver haired child named Ginmokusei. Like most traditional fangames, the objective is to explore dream worlds and collect effects. There are six endings to find, three for each character.' FROM games WHERE igdb_id = 166589 ON CONFLICT (game_id, language_code) DO NOTHING;
