INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Mouse', 'Guide Alice, cat astronaut extraordinaire, to the top of the building without being caught by the vicious Space Mice. The original version of this vertically-scrolling maze game was released in September 1981 for the PC-8001. It was designed by Takanari Suzuki, Japan’s first star game creator.' FROM games WHERE igdb_id = 30874 ON CONFLICT (game_id, language_code) DO NOTHING;
