INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Clash', 'Star Clash is a gesture based puzzle fighter with light RPG mechanics. The player is tasked with creating shapes by tapping stars as they randomly appear creating a fast connect-the-dots feel.' FROM games WHERE igdb_id = 60992 ON CONFLICT (game_id, language_code) DO NOTHING;
