INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jurassic-life-velociraptor-dinosaur-simulator', 87579, '2014-08-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co304r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hrv8fs2v8qigg0flstd3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Life: Velociraptor Dinosaur Simulator', 'Explore a lost world of dinosaurs and live life as a Velociraptor! Survive in a prehistoric world filled with massive carnivores! Start your own pack of raptors, raise baby dinos, stalk your prey through the tall grass, and battle for your life against ancient predators like the Tyrannosaurus Rex, Spinosaurus, and Pterodactyl! Download the Jurassic Life: Velociraptor Simulator today while it''s 50% OFF for a very limited time! Game Features + REALISTIC SIMULATOR - You''ll need to maintain your health, hunger, thirst, and energy if you''re going to survive in the hostile Jurassic jungle! + EPIC BATTLES - Use your powerful bite, razor sharp talons, and swift speed to catch tasty snacks and fight dangerous dinosaurs! + START A PACK OF RAPTORS - Find a mate to bond with and raise your very own pack of raptors to help you hunt! Watch your babies grow in size and assist you in combat! + LEVEL UP YOUR DINO - Gain experience by defeating other dinosaurs and level up your raptors to increase their health, attack damage, and even unlock new raptor skins! + JURASSIC SURVIVAL GUIDE - Look to your handy survival guide for information on enemy dinosaurs, a map of the jungle, raptor customizations, and much more! + HUGE 3D ENVIRONMENT - Your raptor is free to explore the massive open-world jungle filled with dangerous carnivores, tall grass, and a sparkling pools of water! + NEW TOUCH-BASED CONTROLS - Brand new intuitive controls let you navigate your dinosaur like never before! Pinch to zoom and play from your raptor''s perspective or get a bird''s eye view of the action! + HD GRAPHICS - Stunning High Definition graphics will transport you millions of years back in time to the land of dinosaurs! + GLUTEN-FREE PROMISE - With all of our games you will always get the full game with no ads or additional purchases! Download the Jurassic Life: Velociraptor Simulator and control your very own pack of the smartest, fastest dinosaurs to ever roam the Earth! If you liked living as a Velociraptor then you''ll love our other animal simulators! Download Jurassic Life: Tyrannosaurus Rex Simulator to rule as the King of Lizards or check out the Wildlife Simulator: Wolf and start your very own Wolfpack! Follow us on Facebook for more awesome animal games and simulators! facebook.com/glutenfreegames Follow us on Twitter too! We love hearing feedback and suggestions! twitter.com/glutenfreegames' FROM games WHERE igdb_id = 87579 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 87579 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
