INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Prisms', 'In this strategic gem puzzle, drag your finger across unwanted gemstones so that the rest can fall into place and make complete horizontal lines. Make a row of red gems for added time and points, or match blue and green gems to receive special gem-busting items! Purple gems can''t be removed by touching them, so you''ll have to use your special items to clear them from the playing field! Time drains faster as you progress through the levels!' FROM games WHERE igdb_id = 243972 ON CONFLICT (game_id, language_code) DO NOTHING;
