INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psych', 'Pretending to be a psychic is as fun as it looks! Based on the Hit USA TV show, Shawn Spencer is a private detective who has an almost supernatural gift for crime-solving – so much so that the local police department hires him as their Psychic Advisor! Shawn quickly finds that his gifts, although formidable, don’t exactly keep him out of trouble. Help Shawn and his best friend Gus find clues, solve puzzles, and unravel mysteries in this humorous Hidden Object adventure game!' FROM games WHERE igdb_id = 86179 ON CONFLICT (game_id, language_code) DO NOTHING;
