INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxcar Brats', 'Boxcar Brats is a wacky, top-down, multiplayer, "anti-racing" game. Your box car is out of control, so do everything you can do stay in last place! Swerve, skid and smash everything in sight to build up your brake meter and spin out your opponents! So hop into your boxcar, cause some mayhem and eliminate your buddies - nothing is off limits when you''re a brat!' FROM games WHERE igdb_id = 313385 ON CONFLICT (game_id, language_code) DO NOTHING;
