INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hay Ewe', 'Hay Ewe is a ewe-nique puzzle adventure game centering on the adventures of Matilda the sheep! Navigate seriously challenging puzzles and avoid treacherous obstacles with your chain of lambs to deliver them to safety. Have fun using an array of boosts and cool items along the way. Get ready for a baaa-rilliant time and beware the farmageddon!' FROM games WHERE igdb_id = 22736 ON CONFLICT (game_id, language_code) DO NOTHING;
