INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MineCart - 3D Mine Cart Game for MineCraft', '!! MineCart Survival !!  MineCart Survival is the newest, fastest paced 3D game on the App Store!  Run away from the evil dragon, ride and shoot your way through sunny skies, dark tunnels and more!  Face off against your favorite mobs, barricades; collect lives and bonuses.  The most exhilarating game on the App Store!  Enjoy!' FROM games WHERE igdb_id = 86692 ON CONFLICT (game_id, language_code) DO NOTHING;
