INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Isolani', 'Isolani is a free-to-play, first-person shooter may not offer anything novel to a well worn genre, but it still delivers a solid gameplay experience. Although it gives gamers an epic storyline as its backdrop, the app succeeds as an uncomplicated shoot ''em up that may be too easy for its own good.' FROM games WHERE igdb_id = 22394 ON CONFLICT (game_id, language_code) DO NOTHING;
