INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knightfall 2', 'Help Knight conquer an ancient evil in this epic puzzle RPG, set in a world of monsters, treasure and adventure!  You must guide Knight around the board through a combination of destroying block groups and rotating the entire play area, grabbing the key for the exit as you go. Rotate the board by clicking the arrows on either side of it, or by using the left and right arrow keys. To clear a group of blocks, just click the group to highlight them then click again to destroy them.' FROM games WHERE igdb_id = 128659 ON CONFLICT (game_id, language_code) DO NOTHING;
