INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crafting Story', 'Feel the Earth in your hands, manipulate it and make it inhabitable. Build worlds from the ground up by combining different pieces and parts of the Universe, then move on to other planets. Be the Master of Universes, create your own custom planets and build them like never before! Make humans, build cities, grow and develop your very own planet! Tricky puzzle to master but easy to learn! Create everything from a wooden wheel to Facebook and smartphone! How about a spaceship or a dishwasher?' FROM games WHERE igdb_id = 175326 ON CONFLICT (game_id, language_code) DO NOTHING;
