INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sisyphus Reborn', 'Sisyphus Reborn is a short atmospheric existential adventure game. Light on puzzles and heavy on atmosphere, the game focuses on exploring philosophical ideas in a short form context. You wake up in a world where everyone digs forever and no one dies. You will never know why or how you came to be there, but now that you are... How do you find meaning in a meaningless world?' FROM games WHERE igdb_id = 31601 ON CONFLICT (game_id, language_code) DO NOTHING;
