INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sacred 3: First Edition', 'Sacred 3 is an arcade Hack ''n'' Slash game for up to four players, set in the war for Ancaria. Choose from legendary heroes and fight together against the rise of evil. You will face hordes of grimmocs, brute beasts, legions of mercenaries and undead wizards. Develop your character''s skills and abilities and band together to use powerful co-op abilities and tactics. Victory is Ours. Glory is Mine.' FROM games WHERE igdb_id = 51287 ON CONFLICT (game_id, language_code) DO NOTHING;
