INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Partia 2', 'Partia 2 is a SRPG (Strategy Role-playing) video game inspired by Fire Emblem and Tear Ring Saga series. In a high fantasy setting, the game will take players through an adventure where magic and sword collide and friendship and betrayal intertwine. Partia 2 : The Pretenders War is a sequel to Partia: The Broken Lineage. The game packs 22 stages that could present challenges to any SRPG fan.' FROM games WHERE igdb_id = 197994 ON CONFLICT (game_id, language_code) DO NOTHING;
