INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chef', 'Chef is an HTML5 based interactive stopmotion piece. You play as Chef, a happy-go-lucky cook who is bombarded by an angry customer, and you have decide what you want to do for the customer. Maybe you should be professional and just take his order, or maybe you can accidentally slip a few drops of the rat poison that''s behind the hot sauce, or perhaps just make his soup extremely hot. It''s up to you!' FROM games WHERE igdb_id = 128575 ON CONFLICT (game_id, language_code) DO NOTHING;
