INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winds of Destiny - Duels of the Magi', 'This game is a retro head to head arcade style strategy game that combines many different mechanics in a fun and challenging new way that is accessible to all ages. Taking elements from fighting games, trading card games, and RPG''s, With its easy to learn/difficult to master gameplay style, Winds of Destiny serves as a perfect coffee break game that you can play head to head against your friends.' FROM games WHERE igdb_id = 39002 ON CONFLICT (game_id, language_code) DO NOTHING;
