INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Len''en Reiretsuden: Reactivate Majestical Imperial', 'Len''en Reiretsuden ~ Reactivate Majestical Imperial (連縁霊烈傳 ～ Reactivate majestical imperial) is a vertical-scrolling danmaku shoot ''em up and the third game of the Len''en Project. It was made by Trick Nostalgie''s sole member JynX and released for the Windows operating system.' FROM games WHERE igdb_id = 125795 ON CONFLICT (game_id, language_code) DO NOTHING;
