INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fluid SE', 'Fluid SE is a thrilling time-trial racer mixed with the arcade gameplay of Pac-Man, brought to you by Radiangames, creator of Inferno+, JoyJoy, Super Crossfire, and more. Speed through the mazes to collect the dots, find the optimal path, and avoid the swarms of spectres. In Fluid SE, zoom around in 10 new levels. Try to finish all the levels in the shortest time possible!' FROM games WHERE igdb_id = 197645 ON CONFLICT (game_id, language_code) DO NOTHING;
