INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xump-the-final-run--1', 153828, '2014-05-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3c9w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru2l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xump: The Final Run', 'This version of Xump is an extended remake of the puzzle game Xump: The Final Run (which in turn is similar to the C64 game Sensitive) with improved graphics and new levels. The goal is still the same: With your bot "Xump" you will have to remove all blue tiles on platforms somewhere in the sky by moving over them. A bit of planning is required, as you (obviously) can move onto such a blue tile only once. The levels have a time limit, so it''s required to think quickly. Apart from the blue tiles the game also contains solid grey tiles that won''t disappear, teleporters to move between two locations, bombs that act as a second layer for the tile (so you have to visit the tile twice to remove it) and arrows that will automatically push you into the arrow''s direction.' FROM games WHERE igdb_id = 153828 ON CONFLICT (game_id, language_code) DO NOTHING;
