INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fall of the New Age: Premium Edition', 'In the dark times of the Medieval a baleful society of the Cult and its adherers strived to seize the rule over the city, control its inhabitants and destroy all sources of knowledge and culture. Help Marla uncover the secret conspiracy, release her kidnapped brother and save the city! Solve numerous quests and puzzles, display courage and wit, and don''t let the Cult take control over the Kingdom!' FROM games WHERE igdb_id = 36265 ON CONFLICT (game_id, language_code) DO NOTHING;
