INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cargo Bridge 2', 'Cargo Bridge is back. Build bridges and test your construction skills — Now with more levels, more bridge connections, more cargo and more fun! Design a blueprint of a bridge and test it when you are done! The game''s workers will then try to cross your masterpiece to pick up cargo from the other side of the valley and bring it back. Your goal is to collect all items in each level.' FROM games WHERE igdb_id = 197233 ON CONFLICT (game_id, language_code) DO NOTHING;
