INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme Landings Pro', 'Test your piloting skills and handle the most critical flight conditions known to man. Cope with emergencies and incidents inspired by real life scenarios in a climactic adrenaline rush. Start each engine individually, navigate between the equipment dashboard panels and be ready to solve over 5,000 possible situations in order to reach the highest pilot ranking. The simulator includes 36 missions to accomplish, 216 challenges to pass, cartography and worldwide navigation with over 500 accurate airports replicas as well as real time weather conditions.' FROM games WHERE igdb_id = 86898 ON CONFLICT (game_id, language_code) DO NOTHING;
