INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devtheism', 'Devtheism is a short story-driven game made with RPG Maker VX Ace. The game is inspired by other RPG Maker titles such as Mattie Brice’s Mainichi and Wiil O’ Neil’s Actual Sunlight. The difference with those 2 games is that Devtheism will tell the story of me, the developer, dealing with one or more stereotypes people love to throw around on the internet.' FROM games WHERE igdb_id = 134512 ON CONFLICT (game_id, language_code) DO NOTHING;
