INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-denpa-men-3-the-rise-of-digitoll', 63170, '2014-05-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4whb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1keq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Denpa Men 3: The Rise of Digitoll', 'The Denpa Men are mysterious creatures that live among radio waves. Invisible to the naked eye, they can only be seen and caught by looking through your Nintendo 3DS. In this game, catch Denpa Men, form your team, and head out on an exciting adventure across the world. All to save a special someone! This time, some Denpa Men can capture monsters, turning them into allies who can be summoned to your side. Capture powerful monsters to turn the tide of battle. Also, your Denpa Men friends now have their own little homes, which can be customized and decorated to suit your style. Network play is now better than ever. Trade items with players worldwide, and lend or borrow Denpa Men. You can import your hero and bring all your friends from the previous two THE “DENPA” MEN titles, too.' FROM games WHERE igdb_id = 63170 ON CONFLICT (game_id, language_code) DO NOTHING;
