INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samantha Wins', 'You are stuck in a strange house that is filled with dark secrets and obscure riddles. Try to find a way out of this weird, surreal place by exploring your surroundings as best as you can. Discover your destiny by melting the events of the past, present and future together.' FROM games WHERE igdb_id = 128561 ON CONFLICT (game_id, language_code) DO NOTHING;
