INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starbot', 'Starbot is a light, melancholic RPG Maker game tribute to The Little Prince. You play as a work-in-progress robot who befriends a star, explores satellites, and fetches parts for his engineer and mechanic. His journey takes him through strange dream worlds, and he crosses paths with a cast of wistful NPCs and eccentric, slightly intimidating sloths.' FROM games WHERE igdb_id = 133848 ON CONFLICT (game_id, language_code) DO NOTHING;
