INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DeckEleven''s Railroads', 'DeckEleven''s Railroads is an addictive railroad empire building game in full 3D. You are in charge of building your own railroad empire, from track layout to cargo management. Choose your train configuration wisely, from steam-powered locomotives to modern diesel and electric engines. From India to USA, From Canada to France, your empire will grow worldwide.' FROM games WHERE igdb_id = 87687 ON CONFLICT (game_id, language_code) DO NOTHING;
