INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('centration', 16566, '2014-03-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/fijxvgiihqxdnntb4fvb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Centration', 'Join your friends and dozens of other players from around the world to crew a space station in a far away solar system, working together to maintain, defend and manage everything from patrol schedules to the state of the fusion engines. Gain experience in your chosen field to earn more responsibility and command your own team or department. Reward good players with accolades to increase their reputation or give troublemakers a hard time with strictures that will keep them out of serious games. Teamwork is key to survival and doing your best and relying on your crewmates is the only way to succeed.' FROM games WHERE igdb_id = 16566 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 16566 AND c.slug = 'angry-engineers-entertainment' ON CONFLICT DO NOTHING;
