INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Piano Tiles', 'The Original Piano Tiles  game is back and better than ever! Don''t Tap The White Tile, tap only the black ones! Tap musical tiles to play piano songs in this classic addictive piano game. Make music with ease when you tap to the beat, getting faster and faster as piano levels progress. But be careful, DON''T TOUCH THE WHITE TILES! Tap the piano tile... Sounds easy? Tap to try and see how you stack up against friends. Tap musical tiles in the original classic tap tile arcade game!' FROM games WHERE igdb_id = 96587 ON CONFLICT (game_id, language_code) DO NOTHING;
