INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blocus', 313263, '2014-09-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8nyy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctlt4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blocus', 'Blocus is a Breakout variant with bright neon graphics. The gameplay builds on the classic formula of controlling a paddle near the bottom of the screen to bounce a ball and remove bricks from the field, but it adds some new elements. There are two types of paddles and they are divided into three parts. When the ball hits one of the paddle''s three sections, it becomes warmer and when it is hot, bullets are shot automatically, destroying the bricks above. Particles have physics and will collide with the paddle or the walls. The player is rewarded for clearing columns and that increases the speed of the ball. The game can be played in an endless mode or in a set of procedurally generated levels where the difficulty level is gradually increased. Destroyed bricks often leave behind power-ups such as additional balls or explosions. Diamonds can be collected as a currency to upgrade the paddle multiple times, improving the fire power. The game is free-to-play with an in-app purchase to remove the advertisements.' FROM games WHERE igdb_id = 313263 ON CONFLICT (game_id, language_code) DO NOTHING;
