INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witch''s Yarn', 'The Witch''s Yarn, is a brassy adventure about a witch who forswore magic for the love a mortal now passed away. Urged by her family to resume her natural talents, she instead opens a small shop, spinning and selling yarn, intent on a quiet life. However, life will be anything but quiet until Wednesday discovers her true purpose in the mortal world. How much trouble can you cause with a spinning wheel and a pot of mushrooms?' FROM games WHERE igdb_id = 9510 ON CONFLICT (game_id, language_code) DO NOTHING;
