INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MinuteQues‪t‬', 'MinuteQuest is a retro-styled, one-finger, time-killing RPG!  A 2D field where the only choice is to advance or die!  Kill fearsome enemies, crush immense bosses, level up, acquire riches, and collect ridiculous equipment whilst gradually advancing along the world towards your goal!  If you''ve got a bit of pesky time to kill, why not try it out?  Kill slime, kill time!' FROM games WHERE igdb_id = 144218 ON CONFLICT (game_id, language_code) DO NOTHING;
