INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PuppetShow: Lightning Strikes - Collector''s Edition', 'PuppetShow: Lightning Strikes, also known as Steam Heart during development, is the 6th game in the PuppetShow series, developed by ERS Games. Unlike the previous 5 games, Lightning Strikes does not focus on the story of Felicia. Instead, the game focuses on a new story arc of a mysterious Magic Puppet capable of animating life. The Collector''s Edition was released on August 21, 2014 while the Standard Edition was released on September 19, 2014.' FROM games WHERE igdb_id = 115259 ON CONFLICT (game_id, language_code) DO NOTHING;
