INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Lemonade Factory Part Two', 'Usually when you see a description of a sequel that starts with "The two main characters are back and bigger than ever" it''s a sure sign of a cash grab. Andre and Liselot are back, and this game is bigger than ever! Super Lemonade Factory Two has more of everything you loved about the first, more zany dialog, more gorgeous pixel art and more spikes. Taking place around the globe in Sydney Australia, New York City and a military base.' FROM games WHERE igdb_id = 61011 ON CONFLICT (game_id, language_code) DO NOTHING;
