INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OverPowered', 'From the creators of Tower of Heaven and Pause Ahead comes yet another challenging platforming adventure! Brave the mysterious Pit of True Heroes with the aid of friendly old sage Master Toh and take on the fearsome demon Lord Zenithius! There''s just one problem... you''re incredibly scrawny and underpowered, with barely enough strength to even lay one finger on a bunny. Can you really become a True Hero in time to save the world from apocalyptic destruction?' FROM games WHERE igdb_id = 146257 ON CONFLICT (game_id, language_code) DO NOTHING;
