INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flambo''s Inferno', 'Flambo''s coal is scattered everywhere and it''s the fault of the evil Mage. Guide Flambo through each of these fire levels at a brisk pace, remembering that while it can withstand the heat, it is vulnerable to the slightest drop of water. Collect all the coal pieces to earn a diamond that can be spent on cool clothes and hats for Flambo. You can even try to build your own level!' FROM games WHERE igdb_id = 196164 ON CONFLICT (game_id, language_code) DO NOTHING;
