INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ravensburger Puzzle', 'The best jigsaw puzzle app for iPhone and iPad - of course from Ravensburger. A huge selection of motifs, intuitive controls, original Ravensburger quality, beginner-friendly tutorials.  For more than 50 years, Ravensburger has been known as the European market leader for its high-quality jigsaw puzzles. We now offer a combination of the tradition and expertise of classical puzzles with the advantages and possibilities of digital puzzles for iPhone and iPad (from iPhone 4 and iPad 2 onwards).' FROM games WHERE igdb_id = 25495 ON CONFLICT (game_id, language_code) DO NOTHING;
