INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chucky Mendoza and the Curse of the Pharaoh', 'Chucky Men­doza and the Curse of the Pharaoh is a charm­ing old school plat­former inspired by 80''s 8-bit retro games on clas­sic com­put­ers. Run across screen, jump over obsta­cles, col­lect trea­sures through­out a cursed pyra­mid, avoid trip­mines, lava pits and var­i­ous deadly ene­mies (includ­ing bats, mum­mies, bugs, cobras) along the way.' FROM games WHERE igdb_id = 132720 ON CONFLICT (game_id, language_code) DO NOTHING;
