INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crumble Zone HD', 'Crumble Zone is an action-packed arcade game about a little, green alien who works hard just to fight for his tiny planet. The thing is to shoot down asteroids while rotating around a planet to get the highest score possible. Crash comets! Blow up meteoroids! Shatter and smash menacing asteroids with powerful weapons! Use a tremendous wave of explosions. Hurl missiles until nothing remains. Save the planet for as long as you can! Earn diamonds and precious gems to unlock special weapons!' FROM games WHERE igdb_id = 38866 ON CONFLICT (game_id, language_code) DO NOTHING;
