INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Surf', 'The sequel to the worlds first iPhone surfing game, Bobble Surfer, is here! Featuring amazing new wave physics, super easy controls and some of the most fluid water based action you''ve ever seen! Chill out in the Free Surf mode, or challenge your friends for the best scores and longest rides. Take on massive stormys, escape huge barrels and keep an eye out for sharks. Test yourself against a ranking system that will pit you against stacks of unique challenges, and customize the gear you unlock along the way.' FROM games WHERE igdb_id = 187827 ON CONFLICT (game_id, language_code) DO NOTHING;
