INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SkySaga: Infinite Isles', 'SkySaga: Infinite Isles was a free-to-play sandbox massively multiplayer online role-playing game for Microsoft Windows developed by Radiant Worlds and published by Korean online game publisher Smilegate.  Following an announcement on 22 August 2017, all production has stopped on Skysaga. Production has been put on indefinite suspension by publisher Smilegate. The website was locked from access besides the front page on September 28 with a final statement that the game has been put on hold.' FROM games WHERE igdb_id = 60733 ON CONFLICT (game_id, language_code) DO NOTHING;
