INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Illusia 2', 'Solve the mystery behind what is causing the nightmares!  An evil force has invaded the Dream World giving everyone nightmares! Help the heroes Angela, Chris and Ares vanquish evil and restore peace to their land in this sequel to the hit RPG, ILLUSIA.  With a thrilling storyline, full of twists and turns, ILLUSIA 2 takes the immersive gameplay of the original masterpiece and embellishes it with more colorful side scrolling adventures, diverse skill training and endless customizable options.' FROM games WHERE igdb_id = 38738 ON CONFLICT (game_id, language_code) DO NOTHING;
