INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims 4: Collector''s Edition', 'Unleash your imagination and create a unique world of Sims that''s an expression of you! Explore and customize every detail from Sims to homes, and much more with The Sims 4. Customize your unique Sims, design their homes & take them on wild adventures through celebdom, romance, holidays and more. The Sims 4: Collector’s Edition includes a copy of The Sims 4, Life of the Party digital content, Up All Night digital content, Awesome Animal Hats digital content, The Creator''s Guide hardcover book, and an exclusive interactive USB Plumbob by SteelSeries.' FROM games WHERE igdb_id = 159074 ON CONFLICT (game_id, language_code) DO NOTHING;
