INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Intake: Be Aggressive', 'Master your reflexes with the fast shooter Intake: Be Aggressive! Intake is the new retro-futuristic drugstep arcade shooter from Cipher Prime. In this psychedelic shooter, you battle a never-ending barrage of pills, pushing your skill and reflexes to the limit to avoid a lethal dosage. Blast and combo your way through an epic cascade of audiovisual mayhem so intoxicating it comes with its own warning label.' FROM games WHERE igdb_id = 174225 ON CONFLICT (game_id, language_code) DO NOTHING;
