INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Divinity: Original Sin - Collector''s Edition', 'This collector''s edition includes:  - Divinity: Original Sin (DVD + 2 Steam keys)  - Beyond Divinity (Steam key)  - Divine Divinity (Steam key)  - Cloth map of Rivellon  - Deck of 30 crafting recipe cards  - Deck of 54 playing cards with a Divinity theme  - Manual  - Set of stickers  - Soundtrack disc  - Two-sided A2 poster  - Two DLC items: Zingalore''s Trunks of Intelligence and The Golden Grail' FROM games WHERE igdb_id = 52924 ON CONFLICT (game_id, language_code) DO NOTHING;
