INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2048 Numbers Mania', '2048 Numbers Mania will test your mathematical skills and ability to problem solve, despite its simple design. Your ultimate impossible goal is to continually think about how to add pairs in order to clear more space on the board. Sounds simple? It''s not!' FROM games WHERE igdb_id = 233515 ON CONFLICT (game_id, language_code) DO NOTHING;
