INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa''s Donutria', 'You just got a job at Papa''s Donuteria in the whimsical town of Powder Point. Sure, the great pay and benefits are nice, but you took the job for that coveted Line-Jump Pass. Unfortunately, now you have to cook dozens of delicious donuts a day for all the crazy customers in this carnival-like town. Cut out the donuts, fry ''em up, and decorate them with a dizzying array of toppings.' FROM games WHERE igdb_id = 143040 ON CONFLICT (game_id, language_code) DO NOTHING;
