INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales Of Symphonia Chronicles: Collector''s Edition', 'Tales of Symphonia Chronicles is a compilation release of Tales of Symphonia and Tales of Symphonia: Dawn of the New World HD remasters with additional content. Box Content: Limited edition packaging with exclusive artwork from Japanese animation studio, ufotable -TALES OF SYMPHONIA CHRONICLES software -SteelBook case -Set of five Chibi Kyun Chara figures -4-disc CD soundtrack -TALES OF SYMPHONIA: Successors of Hope hardcover novel -Art booklet with PS3 custom theme download code' FROM games WHERE igdb_id = 42960 ON CONFLICT (game_id, language_code) DO NOTHING;
