INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Red Riding Hood''s Wolf', 'Rosetta is just a shy little girl that goes to visit her grandmother, Mary. However, Mary was murdered. While looking in the house for clues, she meets a boy named Camille, who wants to pay respects to the deceased Mary. Together, they must find the real perpetrator.' FROM games WHERE igdb_id = 125863 ON CONFLICT (game_id, language_code) DO NOTHING;
