INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ben 10 Ultimate Alien: Ultimate Crisis', 'Ben 10 Ultimate Alien: Ultimate Crisis - Aggregor villain and his robots are attacking Earth! Use the powers of the Ultimate Swampfire to defeat as many robots as you can. Why not punch, kick and throw balls of fire to protect the Earth from the invasion of Aggregor villain and his great army of robots. It''s hero time!' FROM games WHERE igdb_id = 302729 ON CONFLICT (game_id, language_code) DO NOTHING;
