INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('runaway-express-mystery', 10790, '2014-09-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jlh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gj5xh5ik0hqephlodymz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runaway Express Mystery', 'A young mother''s attending a train exhibition with her children, when something strange happens; the legendary Runaway Express starts moving while her children are still on board. Frightened, she jumps on the train and finds it full of unusual passengers--the ghosts of people who died on the Runaway Express over the 50 years it ran between Paris and Istanbul. Each ghost is a victim, his or her mysterious demise never fully investigated. These lost souls are cursed to ride the train until someone has the courage to go back in time and reveal the truth about their deaths. Do you dare to break the curse? Will you uncover the mysteries and free the souls? Do you have what it takes to face and defeat the terrible masked Engineer and if you do, what price will you have to pay? Jump on the Runaway Express and find out.' FROM games WHERE igdb_id = 10790 ON CONFLICT (game_id, language_code) DO NOTHING;
