INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anmynor Puzzles', 'Anmynor Puzzles is set in a world of magic where challenges await in the 100 levels that make up this adventure. Use and combine the abilities of 17 unique and charming characters, the Golems on a journey to gather all the Elemental Runes. Anmynor Puzzles is set in a world of magic and adventure. You will guide a group of Golems through 100 levels. The adventure takes place over 17 stages, each with new obstacles and new Golems. The Golems will need to combine their different abilities to overcome the challenges ahead.' FROM games WHERE igdb_id = 17040 ON CONFLICT (game_id, language_code) DO NOTHING;
