INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Delicatte', 'Delicatte is a game about a little girl named Chisaki, who wants to find her reason to live/happiness. She travels through a weird land and asks people for help. They appear as weird aliens or objects - look for them. The purpose of this game is to make someone feel better after playing. Especially if You are sad.' FROM games WHERE igdb_id = 151575 ON CONFLICT (game_id, language_code) DO NOTHING;
