INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Batman 3: Beyond Gotham - Deluxe Edition', 'LEGO Batman 3: Beyond Gotham is an action-adventure game developed by TT Games and released in 2014. The game features Batman and other DC Comics characters traveling beyond Earth to stop the villain Brainiac. Players explore various locations, solve puzzles, and engage in combat while collecting LEGO studs and unlocking characters. The game includes a large roster of DC heroes and villains, each with unique abilities. The Premium Edition includes the base game and the Season Pass. The Season Pass features six DLC packs, each with a unique themed mission level with story and free play modes. Players are also able to unlock a total of over 40 characters, vehicles, achievements and more.' FROM games WHERE igdb_id = 164684 ON CONFLICT (game_id, language_code) DO NOTHING;
