INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'We Slay Monsters', 'We Slay Monsters streamlines traditional roguelike RPG gameplay and introduces a unique poker-esque card based combat mechanic. Each class (Wizard, Rogue, Warrior) has a unique deck of cards; using this deck you will guide your hero through the dungeon. Each dungeon is designed to play in short bursts, with a single dungeon taking 15-25 minutes to complete (or even less if your hero dies).' FROM games WHERE igdb_id = 36183 ON CONFLICT (game_id, language_code) DO NOTHING;
