INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Rugby Manager 2015', 'Pro Rugby Manager 2015 covers all aspects of the challenges of a real rugby union manager: guarantee sporting success on the field and financial success off it and be the next Champion! Developed under license from the biggest rugby union leagues in the world: Aviva Premiership Rugby, PRO12 and Ligue Nationale de Rugby, Pro Rugby Manager 2015 will give you the opportunity to manage any of the 54 official teams from these leagues.' FROM games WHERE igdb_id = 10727 ON CONFLICT (game_id, language_code) DO NOTHING;
