INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Illumination Laser', 'Formally lost-media. Illumination Laser is a vertically scrolling shooter for the Sharp X68000. Originally developed near to completion in 1994, its creator TERRA released a finished build in 2014 in response to learning of an auction containing the older unfinished 1994 build.' FROM games WHERE igdb_id = 280690 ON CONFLICT (game_id, language_code) DO NOTHING;
