INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Few', 'Once combat is initiated the player can lead their squadrons to attack waves of German bombers utilizing simple touch or mouse commands. The game follows the historical timeline very closely, but at the same time - the game mechanics are easy to learn (yet hard to master) and it provides great entertainment for both seasoned and novice players.' FROM games WHERE igdb_id = 17385 ON CONFLICT (game_id, language_code) DO NOTHING;
