INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eagle-simulator', 86727, '2014-08-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hy2ptginu0emr5tmldlh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/esjiyqezge9wpty2hita.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eagle Simulator', 'Soar through the skies and live life as a majestic Bald Eagle! Survive on a massive island filled with dangerous animals! Start your own flock of eagles, raise baby birds, snatch fresh fish from the water, and battle for your life against forest predators like wolves, foxes, and bears! Download the Eagle Simulator today while it''s 50% OFF for a very limited time! Game Features + REALISTIC SIMULATOR - You''ll need to maintain your health, hunger, thirst, and energy if you''re going to survive on a wild and remote island! + EPIC BATTLES - Use your razor sharp talons, and swift speed to catch tasty fish and fight fierce forest animals! + START A FLOCK OF EAGLES - Find a mate to bond with and raise your very own family of eagles to help you hunt! Watch your babies hatch and grow in size as they assist you in combat! + LEVEL UP YOUR BIRD - Gain experience by defeating other animals and level up your eagles to increase their health, attack damage, and even unlock new eagle colors! + WILDLIFE SURVIVAL GUIDE - Look to your handy survival guide for information on enemy animals, a map of the forest, eagle customizations, and much more! + HUGE 3D ENVIRONMENT - Your eagle is free to explore the massive open-world island filled with wild animals, soaring mountains, and a sparkling pools of water! + HD GRAPHICS - Stunning High Definition graphics will transport you to a remote island with gorgeous views from epic heights! + GLUTEN-FREE PROMISE - With all of our games you will always get the full game with no ads or additional purchases! Download the Eagle Simulator and control the legendary bird of grey that reigns supreme at the top of the food chain, the Bald Eagle! If you liked living as an Eagle then you''ll love our other animal simulators! Download Jurassic World: Tyrannosaurus Rex Simulator to rule as the King of Lizards or check out the Safari Simulator: Lion and start your very own pride of lions! Follow us on Facebook for more awesome animal games and simulators! facebook.com/glutenfreegames  Follow us on Twitter too! We love hearing feedback and suggestions! twitter.com/glutenfreegames' FROM games WHERE igdb_id = 86727 ON CONFLICT (game_id, language_code) DO NOTHING;
