INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tank-battle-east-front-1944', 200227, '2014-05-22', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Battle: East Front 1944', 'Tank Battle: East Front 1944 is the penultimate title in the successful ‘Tank Battle: East Front’ series of games for iPhone and iPad, a game of tactical combat on the Russian Front during 1944. Fight as the Germans or the Soviets in a series of ever more complex missions. 1944 was to be a terrible year for the German armed forces. A year of continuous retreat as the Soviet war machine moved relentlessly west. The summer would see the destruction of Germanys Army Group Centre, a worse disaster than Stalingrad. 1944 was also a year of super tanks with the appearance of the Iosif Stalin 2 tank with its massive 122mm gun and the German King Tiger. Missions vary from straightforward wipe out the enemy missions, to capture key objectives, to protecting vital supply convoys and repairing broken heavy tanks. There is a whole range of missions to reflect the tactical complexity on warfare on the Eastern Front.' FROM games WHERE igdb_id = 200227 ON CONFLICT (game_id, language_code) DO NOTHING;
