INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supreme Ruler 1936', 'Supreme Ruler 1936 is Real Time Geo-Political/Military Strategy Game for PC (and soon Mac). Take control of a nation in the World War II era and guide it through a significant Military Campaign, or attempt one of many Set-Piece Historical Scenarios. Players can also customize their play experience with the Sandbox Mode and play as any Nation with their own preferred Victory Condition.' FROM games WHERE igdb_id = 16574 ON CONFLICT (game_id, language_code) DO NOTHING;
