INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runion', 'Runion is the first arcade on iPad that can be played by up to 8 players simultaneously and allows to control characters from the iPad or with remote iPhone or MFI controllers. It has nice hand-drawn graphics and music from award-winning composers. Gameplay is designed so that it is equally interesting for any amount of players (even one). The game is really addictive and is fun to be played in parties by friends or the whole family.' FROM games WHERE igdb_id = 25735 ON CONFLICT (game_id, language_code) DO NOTHING;
