INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sound-voltex-iii-gravity-wars', 39883, '2014-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2g1k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8jla.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sound Voltex III: Gravity Wars', 'FX and BT notes, both short and long ones, can now overlap. The FX notes have been made thinner as a result. Analog chains can start from anywhere and not just from the extremities of the chart lane anymore. Analog chains can now extend outside of the chart lane as well. New analog effects have also been added. You can now change the colors of the analog chain lines. There are four available colors: Blue, Pink, Green and Yellow. Both analog chain lines can be set to have the same color. EARLY/LATE indicators for timing judgment have been added. They work in the same way as in the beatmania IIDX and DanceDanceRevolution series. At the song result screen, it is possible to see how many EARLY and LATE "NEARs" you have hit. You can now change the Hi-SPEED value more accurately by pressing the START button twice. The maximum Hi-SPEED value has been increased from 6.0 to 7.0. By pressing the 6 button while holding the START button, you can permanently save your desired scrolling speed (the Hi-SPEED x BPM value), which will be shown in red below the current Hi-SPEED value. Songs can be sorted into additional new categories: SOUND VOLTEX game (BOOTH, infinite infection, and GRAVITY WARS). Cleared songs. ULTIMATE CHAIN cleared songs. PERFECT cleared songs. Charts by individual levels. Portions of certain charts will cause the entire chart to shake, zoom in and out, or be temporarily viewed from above. Each SKILL ANALYZER level now has three courses to choose from, instead of just one. New groups are added every month. SKILL ANALYZER courses can now have Nettou! BEMANI Stadium (熱闘！BEMANIスタジアム) event songs.' FROM games WHERE igdb_id = 39883 ON CONFLICT (game_id, language_code) DO NOTHING;
