INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiestru', 'Tiestru offers a new perspective to strategy games. The player has control all over the map and defines his strategy with the structures that he builds. Each structure, each connection, each location offer new and enhanced powers. In this deep and complex game everything is up to you! Define your strategy!' FROM games WHERE igdb_id = 36255 ON CONFLICT (game_id, language_code) DO NOTHING;
