INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('global-outbreak', 16853, '2014-07-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Global Outbreak', 'Take control of Blackhorne Industries, an international private military contractor. When the world is hit by a sudden and unexpected meteor shower that unleashes a deadly pathogen, Blackhorne are called in to clean up the mess. Can you lead your elite troops to victory before the mysterious meteorites destroy life as we know it? The fate of the world rests in your hands! Global Outbreak combines Real-Time Strategy and Top-Down Shooter in a unique and exciting package. Fight back the infection from above on the tactical globe, and then send in your troops to battle off the infected on the ground and destroy the devastating “Zompods” that are spreading the mutant plague throughout the world.' FROM games WHERE igdb_id = 16853 ON CONFLICT (game_id, language_code) DO NOTHING;
