INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murder', 'Murder is a small game about becoming the next King by sneakily removing the current ruler stab-a-roo-style. The game, disguised as a lighthearted and slapstick-fueled one-button-gimmick, subtly unfolds its core as an experimental contemplation about power, trust and mistrust and the infinite loop of greed and need as the player engages deeper in the daring loop of assassinations.' FROM games WHERE igdb_id = 226764 ON CONFLICT (game_id, language_code) DO NOTHING;
