INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Order of the Metal Glove', 'Charge around bunkers with your fellow Planetary Marines, fighting the vicious MechanoSpyders and their legions of metal-clad comrades! The Order of the Metal Glove is an old-school multiplayer action arcade game. Up to four players can join the robo-destruction together, so bring a friend, and have a blast! The initial worlds (13 total levels) are free. An in-game purchase unlocks the remainder of the game.' FROM games WHERE igdb_id = 51662 ON CONFLICT (game_id, language_code) DO NOTHING;
