INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Christmas Carol 2', 'The sequel to the first game. The player fights against four brand new bosses: Tiny Tim (alongside Bob Cratchit), Scrooge, Want, and Ignorance. It starts in a teleport room, in an unknown place (most likely in Wily''s fortress). After the player has defeated the Robot Masters, the final battle awaits. One possible ending to see, but with different characters.' FROM games WHERE igdb_id = 209265 ON CONFLICT (game_id, language_code) DO NOTHING;
