INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shark Game', 'You are a shark in a strange blue sea. As you begin to gather fish you are joined by fellow sharks, rays, and other creatures who help you collect a variety of resources and learn about the world around you. As you explore you discover something strange in the darkest depths of the sea floor.' FROM games WHERE igdb_id = 220256 ON CONFLICT (game_id, language_code) DO NOTHING;
