INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yaiba: Ninja Gaiden Z - Special Edition', 'A cyborg ninja rises from the dead, slaughtering hordes of twisted zombies in his quest for vengeance in this collaborative new franchise from famed developers Team NINJA and Keiji Inafune. In Yaiba: Ninja Gaiden Z, players will battle fierce zombies as Yaiba, a cyborg ninja who will do anything to get revenge and stay alive. In this exclusive special edition, you can get your hands on the following extra content: Exclusive full colour Yaiba: Ninja Gaiden Z comic book by Dark Horse (24 pages/3 editions) Original soundtrack (digital code) Exclusive Yaiba themed DLC costumes for Ryu Hayabusa and Momiji for DOA5 Ultimate game owners (digital code)' FROM games WHERE igdb_id = 42967 ON CONFLICT (game_id, language_code) DO NOTHING;
