INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Zombies Rave', 'Earth 2015 Our planet has been invaded by zombie scum, they''re coming to the rave parties! But there''s a little group of techno ravers decided to save the party, killing those furious zombies wherever be the situation to the rhythm to the hard electronic music. Each one has amazing exclusive powers, and powerful weapons.' FROM games WHERE igdb_id = 175103 ON CONFLICT (game_id, language_code) DO NOTHING;
