INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rote', 'Rote is a simple puzzle game that offers an unprecedented level of challenge, leaving you puzzled for days. The gameplay itself is simple, you push blocks left and right using the ball and you try to move to the exit on the right. The puzzles however, start easy and increase in difficulty as you progress, and it’s not all about the size of the level, nor the amount of moves it takes to finish them, it’s about the tricks used to solve them.' FROM games WHERE igdb_id = 105428 ON CONFLICT (game_id, language_code) DO NOTHING;
