INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Girl: RPG', 'Action, Adventure, Weapon Throwing RPG, set in a mystical ancient land & brought to life with anime inspired hilariously-awful hand-drawn art! Are you a skillful gamer, with a fast mind and reflexes? Rage-quitting is not in your vocabulary? Think you got what it takes to beat one of the hardest skill-based games on mobiles, ever?! Put your abilities to the test in this deceptively difficult game!' FROM games WHERE igdb_id = 175550 ON CONFLICT (game_id, language_code) DO NOTHING;
