INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sorceress of Fortune', 'Join the story as a diverse group of sorcerers are in search for a beacon of hope in the midst of darkness that has enshrouded Fortune World after the disappearance Meteor Dragon in this enhanced strategic puzzle battle system.' FROM games WHERE igdb_id = 200063 ON CONFLICT (game_id, language_code) DO NOTHING;
