INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Christmas Shopper Simulator', 'Ask anyone what their favourite bit of the festive season is, and they will all say the exact same thing; Christmas shopping. Being quite stressed and wandering round a vast shopping centre packed with expensive tat and angry, bitter people is what Christmas is all about. And now, you don''t even have to leave the house to experience those mild thrills and that dizzying normality, because Christmas Shopper Simulator is finally here.' FROM games WHERE igdb_id = 137466 ON CONFLICT (game_id, language_code) DO NOTHING;
