INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flight Sims Air Cavalry Pilots', 'Get into the cockpit of the most advanced helicopters in the world, including the UH-60 Black Hawk, MV-22B Osprey, CH-47 Chinook, AH-64 Apache, UH-1 Iroquois, OH-6 Cayuse, AH-1Z Cobra, CH-53 Super Stallion, Eurocopter Tiger, Kiowa Warrior, Mi-24 Hind, Ka-50 Black Shark or Mi-8 Hip helicopter in various regional environments, building on your flying skills and experience. Enjoy infinite flight in legendary helicopters like a real combat pilot or become a firefighter in Skycrane!' FROM games WHERE igdb_id = 175336 ON CONFLICT (game_id, language_code) DO NOTHING;
