INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bravely-default-collectors-edition', 44018, '2014-02-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6c80.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjmy7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bravely Default: Collector''s Edition', 'Square Enix’s highly-acclaimed fantasy RPG brings deep, strategic combat to the Nintendo 3DS system in an ambitious game that bolsters its turn-based combat with a compelling new risk/reward system RPG fans will obsess over. Explore Luxendarc as Tiz and other memorable characters on a visually stunning quest to restore balance to the world. Hand-drawn 3D backgrounds and a rousing score bring Luxendarc to life. Enter a brave new world of turn-based combat! Time your turns tactically and turn the tides in your favor with the new Brave and Default system. Flex your strategic muscle by combining more than twenty jobs with hundreds of different abilities. Summon friend’s characters to fight by your side, or borrow their abilities*. Recruit citizens with the StreetPass feature to rebuild Tiz’s destroyed village. Be part of the community in this fresh take on the single player RPG! Collectors Edition includes a Deluxe ArtBook (softcover), 34 Augmented Reality Cards, Soundtrack CD with Jewel Case and collectors box.' FROM games WHERE igdb_id = 44018 ON CONFLICT (game_id, language_code) DO NOTHING;
