INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metro-2033-wars', 59064, '2014-09-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5eko.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/n2o6gm9etapeictgvjxm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metro 2033: Wars', 'One of the most strategic and intense games on the App Store! Welcome to the Tunnels! Lights out! “Metro 2033: Wars” is a turn-based, open-world, strategy game, based on the story of Dmitry Glukhovsky''s best-selling novel series, “Metro 2033.” It’s the year 2033 and the entirety of the world has been reduced to nuclear rubble. Humanity is nearing extinction and radiation is making even the most basic surface dwelling, uninhabitable. New life forms have arisen that are far better adapted to this new dark, damp and alien-like world. Bands of survivors live on without ever knowing the warmth of sunlight, and whether or not they are the last ones left on Earth. The Moscow Metro is the reluctant home for this new humanity and one you protect at all costs. Metro Stations have become city-states run by new and emerging Factions, uniting its members around ideas, religions, water, or simply the need to survive. Your daily existence centers around gathering resources necessary for survival, repelling attacks of mutants, exploring and conquering new metro stations and developing armed mercenary units when the need arises. To survive, you''ll have to build necessary facilities at Stations, establish diplomatic relations with your neighbors and uphold the economy of your little underground state.' FROM games WHERE igdb_id = 59064 ON CONFLICT (game_id, language_code) DO NOTHING;
