INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guns GirlZ', 'The Global Server for Guns GirlZ was closed on October 11th 2021, while the JP and CN servers remain active. Guns GirlZ, also known as Houkai Gakuen 2, is a 2D side-scrolling shooter game developed by miHoYo. It follows Kiana Kaslana''s adventure through her three different incarnations, along with her companions such as Raiden Mei, Bronya Zaychik, and Houraiji Kyuushou, in a fight to defeat a world-destroying power known as the Honkai.' FROM games WHERE igdb_id = 79282 ON CONFLICT (game_id, language_code) DO NOTHING;
