INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Humanity Asset', 'Humanity Asset is a Metroid-style 3D platformer that pays homage to the traditional retro classic shoot ‘em up genre. Aliens have invaded Earth to strip the planet of its resources, to save their own dying planet. As in all classic shoot ''em ups, only you can save the day - now there’s a surprise!' FROM games WHERE igdb_id = 8952 ON CONFLICT (game_id, language_code) DO NOTHING;
