INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Skater', 'A meteor has hit the prehistoric earth! Help Dino kickflip, ollie, and grind his way to saving the dinosaurs from extinction! To stop the lava flood you must collect magical fire eggs strewn across Dino''s radical jurassic world...OR ELSE. Use your sick skateboard skills to grind along the backs of fellow dinosaurs while collecting fire eggs to help stop the flow of lava. Snag coins along the way to load up on powerful gear, souped up boards, and upgradeable powerups. From the creators of Pogo Plumber, Oldify, Fatify, Beardify, and more!' FROM games WHERE igdb_id = 175237 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 175237 AND p.igdb_id = 39 ON CONFLICT DO NOTHING;
