INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Popscene (Backstage Pass)', 'Bring your music collection to life with animated performances as you embark on a career in the industry. Form your own band by recruiting talent from over 100 artists across 6 unique labels. Then record hits that will top the charts and take them on the road to over 20 different venues - complete with real reviews that scrutinize your strengths and weaknesses. With an endless schedule of possibilities before you, and an ever-evolving industry to immerse yourself in, Popscene captures the highs and lows of music in the palm of your hand!' FROM games WHERE igdb_id = 91988 ON CONFLICT (game_id, language_code) DO NOTHING;
