INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SilverQuest: Gaiden', 'SilverQuest: Gaiden is retro dungeon crawling at it''s best. FM Synth sounds and music bring you deep into a world of dungeon exploration where each game is a new experience! All art, music, items, enemies … everything is exposed outside of the game, meaning anyone can add, remove or change anything in the game. Add color, release your own mod-pack, anything!' FROM games WHERE igdb_id = 36161 ON CONFLICT (game_id, language_code) DO NOTHING;
