INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Dream: Hospital', 'Bad Dream: Hospital is a third game in Bad Dream series. This time you are a patient in a very bizarre hospital. There''s a coloring book on the table.. Guess what you must to do.. ;)  This part is less scary and more .. dirty..  You should also try other games in the Bad Dream series:  -Part 01: Butcher  -Part 02: Graveyard  -Part 03: Hospital  -Part 04: Cyclops  -Part 05: Memories  -Part 06: Bridge' FROM games WHERE igdb_id = 133927 ON CONFLICT (game_id, language_code) DO NOTHING;
