INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Erth', 'Erth is a large 2D Sandbox RPG Exploration Top-Down Turn-Based Adventure game where you explore an infinite world socializing, exploring, fighting, mining and building! The game features a fully-fledged crafting and inventory system with over 600 items, along with over 400 crafts! The world is split into 64x64 areas that you can explore an unlimited number of! There are also tons of enemies, biomes, materials, and more!' FROM games WHERE igdb_id = 134673 ON CONFLICT (game_id, language_code) DO NOTHING;
