INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magica Wars: Zanbatsu', 'Magica Wars Zanbatsu is a free-to-play action game, based on the Magica Wars franchise, developed and published by Galat for the PlayStation Vita handheld console. Magica Wars: Zanbatsu is an extension of the Magica Wars series which focuses on 47 magical girls that represent the 47 prefectures in Japan. In Zanbatsu you play as Amane Sakaki (left) who has lost her memories aside . Yamada (middle) travels with her and Maki Inada (right), a magical girl, holds the key to the story. Maki realizes that Amane is a magical girl, gives Amane her name and the from her mission to defeat the Magatsuhi.' FROM games WHERE igdb_id = 62013 ON CONFLICT (game_id, language_code) DO NOTHING;
