INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circle the Dot', 'This is a simple game with simple rules. Just trap the the blue dot within the matrix of circles. This is one smart dot though... Just tap on the gray dots and they will turn to orange. The blue dot is blocked by these orange dots. Surround the blue dot with the orange dots before it escapes! But is it even possible?' FROM games WHERE igdb_id = 39200 ON CONFLICT (game_id, language_code) DO NOTHING;
