INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marginal-number-4-idol-of-supernova', 61943, '2014-11-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5r9c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch709.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marginal #4: Idol of Supernova', '"I want to see the shooting stars that fall onto the stage." That''s the dream of the manager of the agency. These four individualistic new idols were grouped for this purpose. Named "MARGINAL #4", they aim to debut as in idol group. Wild and self-assured, the confident Kirihara Atom has talent but is hard to handle. Even though he looks feminine and gentle, Aiba Rui leaves a somewhat a cold impression. Twins that are splitting images of each other, but exude differing auras. Nomura L is showy, very confident, and is the younger twin. In contrast, Nomura R acts like he''s hiding behind his younger brother''s shadow. Then there''s MARGINAL #4''s seniors, "LAGRANGE POINT". Though stoic with goals to reach the top, Mikishima Shy is a little proud. On one hand, Himuro Kira is cheerful and good at taking care of others, but on the other, he has a crude side to him. Those two as well, were grouped together with the same goal of "showering stars" and aim for the big stage. The one who holds the key to allow them to truly shine is their manager and protagonist, Kataoka Yue. How will she guide the scattered individuals of the group?' FROM games WHERE igdb_id = 61943 ON CONFLICT (game_id, language_code) DO NOTHING;
