INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sentou Danchi', '"Survivors stranded on an unknown planet. Dangerous creatures roam this planet at night. Fight to protect your escape ship to survive and return to your home planet. Survivors enter the capsule and drift to the planet. If you use the blocks that have fallen on the planet to make their homes, they will wake up from the capsule and become your allies. During the day they bring in new blocks, and at night they return to their homes and fight to protect their escape ships. Let''s make a good dwelling and slip through the enemy''s attack."' FROM games WHERE igdb_id = 237824 ON CONFLICT (game_id, language_code) DO NOTHING;
