INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mexicana: Deadly Holiday', 'Dia de Muertos, or the Day of the Dead, provides a stunning backdrop for a thrilling supernatural adventure in Mexicana: Deadly Holiday! Guide a young woman as she sets off on a desperate search for her fiancé amidst the annual celebration in Mexico. Moments after a spectral figure kidnaps her beloved during a card reading, she begins her journey to the afterworld, where demons will plot her demise and ancients gods will lend her a helping hand.' FROM games WHERE igdb_id = 53326 ON CONFLICT (game_id, language_code) DO NOTHING;
