INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atelier Questboard', 'Atelier Questboard was a casual game made by Koei Tecmo for Android and iOS. With a focus on locations from Atelier Rorona, it featured various characters from the Atelier franchise. The goal of the game was to collect various materials and to build relationships with other characters.' FROM games WHERE igdb_id = 130323 ON CONFLICT (game_id, language_code) DO NOTHING;
