INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('submachine-flf', 259983, '2014-12-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6vxx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnqs8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Submachine: FLF', 'This is the game about memories, how they fade away, trick us or straight up lie to us. Do you remember this game? Are you sure? Try this version – you might not recognize it. Did you really hear this music? Is it changed? Or maybe it was there all along… I don’t remember anymore. One thing I know for sure – those pictures… I recognize them, they’re… from my past, my ancestors. I’ve seen them so many times, but were they here before? Is it possible that somebody changed them? Did I change them? There’s a machine I haven’t seen before. There’s a room I haven’t been to, but I could swear I did. My memory about this game is murky. That’s how I see this game now. That’s the one I did so many years ago. Or is it?…' FROM games WHERE igdb_id = 259983 ON CONFLICT (game_id, language_code) DO NOTHING;
