INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Navi’s Quest', 'Zelda Navi''s Quest is an Open Source fan made 2D Zelda game that chronologically takes place after the ROTH trilogy, a series of fan made Zelda games made by Vincent Jouillat. The gameplay lies in the ability to play as both Link and Navi, the player being able to heal and survey the area with Navi’s powers. The game is available to play on PC, the PSP and the PS Vita' FROM games WHERE igdb_id = 330579 ON CONFLICT (game_id, language_code) DO NOTHING;
