INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Quests of the Hero', 'A one player action adventure with comedy elements! - Seven maidens have been kidnapped and held prisoner by an evil sorcerer... Your mission is to locate and rescue them back to the safety of the castle and then keep them amused for the duration of their stay!' FROM games WHERE igdb_id = 303207 ON CONFLICT (game_id, language_code) DO NOTHING;
