INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starlite: Astronaut Rescue', 'Experience the thrill of standing in the boots of a future astronaut on Mars in the world of Starlite. Participate with your crewmate in a single-player 20 minute mini-adventure that soon turns into more than you bargained for on the Red Planet. Players navigate a future Mars mission in which they must construct a habitat, craft tools and use advanced robots. The game contains hands-on science inquiry and problem solving in mathematics, physics and engineering. Starlite: Astronaut Rescue is the first release in the series leading up to alpha testing of the multiplayer online game Starlite: Astronaut Academy in summer 2014.' FROM games WHERE igdb_id = 16879 ON CONFLICT (game_id, language_code) DO NOTHING;
