INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fist of Jesus', 'Fist of Jesus is a hilarious gore beat’em up classic style arcade game with RPG depth. Life of Brian meets gore and humor, in the game based on the epic award-winner short-film Fist of Jesus. Fist of Jesus tells the adventures of Jesus and Judas, where the world is now full of Zombies caused by Lazarus’ resurrection. Cowboys, the Roman Army, Mythological Creatures and Steampunk technology in the 80''s style, all packed with lots of fun.' FROM games WHERE igdb_id = 10322 ON CONFLICT (game_id, language_code) DO NOTHING;
