INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen', 'A remake of the title was released digitally for the PlayStation 3 and PlayStation Vita in 2014 via PlayStation Network. While the game utilizes high-definition graphics, battle animations are rendered using immobile robots in a manner similar to titles released prior to Super Robot Wars Alpha. Gameplay changes include 13 new stages, Spirit Commands available for all units (though the Hero is given access to exclusive commands), the addition of Mazinger Z''s Boss Borot to the starting Mazinger team, and new units such as the Full Armor Gundam and Cybuster.' FROM games WHERE igdb_id = 240916 ON CONFLICT (game_id, language_code) DO NOTHING;
