INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirits of Spring', 'Chiwatin, a young Native boy stranded in the northern landscapes of Permanent Winter, is haunted by giant crows. To overcome their cruelty, Chiwatin goes on an inspiring quest to restore Springtime and find the courage to move on. Inspired by familiar struggles with bullies and isolation, Spirits of Spring is an empathy game rooted in deeply emotional storytelling. Experience the fiercest loyalty in the most unlikely of places' FROM games WHERE igdb_id = 63455 ON CONFLICT (game_id, language_code) DO NOTHING;
