INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('naval-tactics', 102593, '2014-05-14', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naval Tactics', 'From the hexagonal playing field to the potentially game changing Captain''s Cards, Naval Tactics is a board game to its very roots. To succeed you will need to take your time, think three moves ahead, and mind the weather gauge! Naval Tactics prides itself on striving to capture the spirit of traditional naval combat in board game form. Configure your fleet using a variety of ships, from nimble Naval Cutters to massive Ships of the Line. Should you disable an opponent with bar shot or blast through their hull with double shot? Enterprising Captains will need to understand their vessels, their armaments, how they sail in relation to the wind, and the advantages of naval formations to best their fellows on the high seas.' FROM games WHERE igdb_id = 102593 ON CONFLICT (game_id, language_code) DO NOTHING;
