INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GiDon Duet', 'Soar through intergalactic obstacle courses as the intrepid shooting star: grasp for the heavens as you come to learn of yourself and your universe, and let familiarity breed perfection. Don''t stop there though–use the course editor to create galaxies of your own and share them with the world. Experience the joy of gliding through space to the euphoric beat of your own rhythm.' FROM games WHERE igdb_id = 61830 ON CONFLICT (game_id, language_code) DO NOTHING;
