INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ground Gives Way', 'The Ground Gives Way is a coffee break roguelike with a simple interface, high variation, high replayability, and many items, monsters, and other stuff. Instead of experience levels, classes, or races, the character''s attributes and progression are defined by the equipment and items they find. Quality-of-life features such as auto-running, a map system, and a portal system can help speed your progress through the dungeon.' FROM games WHERE igdb_id = 109095 ON CONFLICT (game_id, language_code) DO NOTHING;
