INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ava''s Quest HD', 'Ava is all grown up and has made new friends, leaving behind her childhood dolls and toys. One of her dolls (called the witch) couldn’t accept this and sought revenge. The witch cast a spell on all her friends and imprisoned them leaving her all alone and now Ava has set out on a quest to rescue them.' FROM games WHERE igdb_id = 175753 ON CONFLICT (game_id, language_code) DO NOTHING;
