INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sit ''N Survive', 'See how many days you can survive while sitting alone in the wilderness! At the beginning of each day you can buy supplies for the night, and you''d better spend your money wisely because you''ll need protection from mosquitoes, bats, bears, snakes, zombies, rain, acid rain, meteors, lightning, ghosts, and more! Choose from three difficulty settings then see how long you can last!' FROM games WHERE igdb_id = 186113 ON CONFLICT (game_id, language_code) DO NOTHING;
