INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultraflow', 'Ultraflow is a minimalist yet complex puzzle game based on your agility. You have a limited number of bounces to complete each level. No score. No timer. The only challenge is your smoothness. The game is one player only, available on Android devices and Web browsers. It was made by five students during 6 months.' FROM games WHERE igdb_id = 11130 ON CONFLICT (game_id, language_code) DO NOTHING;
