INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snake-simulator', 87643, '2014-11-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/waei2ttxrspypwcjmzwv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/blzdjpvr4ojkjuun94pv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snake Simulator', 'Enter a tropical rainforest and live the life of a poisonous Snake! Explore a lush jungle filled with ferocious animals and insects of all shapes and sizes. Raise a family, hunt down food, and battle for your life against fierce predators like tigers, crocodiles, and gorillas! Download the Snake Simulator today while it''s 50% OFF for a very limited time! Game Features + REALISTIC SIMULATOR - You''ll need to maintain your health, hunger, thirst and energy if you''re going to survive in the hostile jungle! + EPIC BATTLES - Use your razor sharp fangs, swift speed, and hypnotic stare to hunt down tasty critters and fight dangerous rainforest animals like the silverback gorilla! + LEVEL UP YOUR SNAKE - Gain experience by defeating and devouring enemies and level up your snakes to increase their health, attack damage, and even unlock new abilities like Venom Shot! + DEADLY ATTACKS - Spit poisonous venom on your foes that will damage them over time or use your hypnotic stare to mind-control enemies into doing your bidding! + START A SNAKE FAMILY - Find a mate to bond with and raise your very own family of snakes! Hatch your eggs and watch your baby snakes grow in size and strength as they help you battle your enemies! + REPTILE SURVIVAL GUIDE - Look to your handy survival guide for information on enemy wildlife, a map of the jungle, snake customizations, and much more! + HUGE 3D ENVIRONMENT - Your snake is free to slither through a massive open-world environment that is more the double the size of the previous simulators and generated dynamically so that every hunt is unique! + NEW TOUCH-BASED CONTROLS - Brand new intuitive controls let you navigate your animal like never before! Pinch to zoom and play from your snake''s perspective or get a bird''s eye view of the action! + 24 UNIQUE JUNGLE SPECIES - Behold the largest collection of animals ever put into a single simulator! Hunt down rats, parrots, bats, elephants, hippopotamus, warthogs, crocodiles, gorillas, deer, tarantulas, tigers, jaguars and many more jungle animals! + HD GRAPHICS - Stunning High Definition graphics will transport you to a lush jungle ecosystem and surround you with the crisp colors of nature''s beauty! New Graphics Quality options allow you to customize the game to look amazing and perform great on any device! + OPTIONAL BLOOD EFFECTS - Looking for more realistic action? If you are of age or have your parents permission, turn on the blood effects for some added combat ferocity! + GLUTEN-FREE PROMISE - With all of our games you will always get the full game with no ads or additional purchases! Download the Snake Simulator to wield the powerful poison and razor sharp fangs of a venomous snake! If you liked living as a Snake then you''ll love our other animal simulators! Download our Eagle Simulator and soar through the skies as a beautiful Bald Eagle, or check out the Cheetah Simulator and pounce on your prey in the wild savanna! Follow us on Facebook for more awesome animal games and simulators! facebook.com/glutenfreegames  Follow us on Twitter too! We love hearing feedback and suggestions! twitter.com/glutenfreegames' FROM games WHERE igdb_id = 87643 ON CONFLICT (game_id, language_code) DO NOTHING;
