INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fairy Tail: Brave Saga', 'In this Puzzle RPG, a party of up to five characters from the Fairy Tail series are utilized to complete quests. Through a sequence of turn-based battles, the player uses their touchscreen to match the same color Lacrima to build up attacks. The greater number of Lacrima chained in a set amount of time, the stronger the units'' actions become.' FROM games WHERE igdb_id = 144095 ON CONFLICT (game_id, language_code) DO NOTHING;
