INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bunny Swordmaster Story', 'This is a VERY short, extremely unpolished very simple quick thing I made in 5 days, some years ago.  It''s a platformer featuring a bunny girl in a Japan-esque setting. Two stages, similar to Momodora games.  Boxart drawn by sesamecake (http://sesamecake.sakura.ne.jp/)  Hope you enjoy it!' FROM games WHERE igdb_id = 133954 ON CONFLICT (game_id, language_code) DO NOTHING;
