INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla: Strike Zone', 'Join a squadron of military heroes on a dangerous mission to face the ultimate force of nature: GODZILLA. Experience the breathtaking high-altitude sky jump from the movie as you air-drop into a devastated San Francisco and embark on a series of first-person rescue missions to evacuate survivors before it''s too late. Your courage has never been more needed than it is today.' FROM games WHERE igdb_id = 61543 ON CONFLICT (game_id, language_code) DO NOTHING;
