INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Graffiti Eraser', 'Available through the Pokémon Global Link website, Graffiti Eraser is a simple game in which the player wipes graffiti from a store window in order to reveal three Pokémon dolls. While most dolls are given a random point value, dolls of legendary Pokémon have a fixed value of 50 points. Upon revealing three dolls, the game ends, and the player will be given their score and will receive a random item or set of items that can be sent back to the player''s 3DS Pokémon RPG.' FROM games WHERE igdb_id = 116246 ON CONFLICT (game_id, language_code) DO NOTHING;
