INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto Shippuden: Ultimate Ninja Storm Revolution - Samurai Edition', 'Take your Naruto experience even further with the Samurai Edition, including a Naruto figurine, in-game costumes and more! Take part in amazing battles between the most skilled ninjas in the Naruto universe! Choose from over 100 playable and support characters to fit your playing style perfectly. Enter the Ninja World Tournament and battle against 3 ninjas with the aim to earn the most battle orbs. Master the new gameplay mechanics and dominate your opponents with your superior skill.' FROM games WHERE igdb_id = 47455 ON CONFLICT (game_id, language_code) DO NOTHING;
