INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bike Mayhem', 'Downhill mountain bike racing like never before. Race down beautiful trails, smashing over rocks and roots, boosting huge jumps, scoring insane trick combos, unlocking better bikes and gear for bragging rights as the King of the Mountain! Compete in timed races or freestyle trick events on 19 different mountains and over 100 trails inspired by real world locations.' FROM games WHERE igdb_id = 200072 ON CONFLICT (game_id, language_code) DO NOTHING;
