INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball League: Hardhat Zone', 'Pinball League: HardHat Zone is a 3D pinball game that allows players to experience this classic game in a whole new way. although the construction theme is not as glamorous as it could be and the sound effects tend to lag behind a little, the graphics are highly polished and really help to draw players into the game. the two player mode also helps to ramp up the fun factor by allowing friends to go head to head to see who has the best skills.' FROM games WHERE igdb_id = 296220 ON CONFLICT (game_id, language_code) DO NOTHING;
