INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('skyline-skaters', 6029, '2014-03-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/c1ti7skmnjjetxripfgj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lg1qpspto3es00ecgnor.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skyline Skaters', 'Skate across the rooftops of the world! Join the awesome Skyline Skaters in their flight from the authorities. Perform hazardous jumps from building to building with only your skateboard to save you! Choose between daring Skaters, each with their own unique abilities and tricks! Ollie off ramps as you avoid pitfalls and obstacles strewn about the rooftops! The vigilant rooftop police are always on your tail in their chopper and will stop at nothing to nab you. Get as far as you can before they catch you! Compete against your friends to get the best high score. Unlock and upgrade new boards to give you new advantages and ways to beat the high scores of the competition. Get out of the subway and feel the joy of Skyline Skating! • Action packed adrenalin runner with easy tap controls! • Escape the Rooftop Police across the Skylines of the World! • Unlock new cool Skaters with their own unique tricks! • Compete against friends across platforms: iPhone, iPod and iPad! • Get special top tuned Boards and blast past the competition!' FROM games WHERE igdb_id = 6029 ON CONFLICT (game_id, language_code) DO NOTHING;
