INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mugogy Jump', 'Meet the fun Mugogy monsters, who lived peacefully in the ocean, until the evil ZZ Corporation decided to invade their home! It''s your turn to help them fight back! Jump through 60 levels in four different worlds, using different Mugogy Monsters. Destroy enemies and orbs with 8 unique and crazy power-ups. Earn your reward! Collect as many coins as you can among the destruction you cause.' FROM games WHERE igdb_id = 298300 ON CONFLICT (game_id, language_code) DO NOTHING;
