INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go home, you''re drunk!', 'Created by ETeeski (code), DanielSND (Art), and PXLDJ (Music & Sound) in 15 hours! (including polish, it was more like 20 hours). We created this game in a self-proclaimed game jam for the purpose of promoting the Ultimate GameDev Tutorials Kickstarter. The theme of this game jam was chosen by the audience of the livestream, which was "Parkour".' FROM games WHERE igdb_id = 134345 ON CONFLICT (game_id, language_code) DO NOTHING;
