INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bitfighter', 'Bitfighter is a fast-paced team-based outer-space multi-player combat game. There are many game modes and unique maps. Players can (and do) create maps by using the built-in map editor. Space exploration for warfare, construction, and beyond! It''s fast, fun, and frenetic.' FROM games WHERE igdb_id = 47275 ON CONFLICT (game_id, language_code) DO NOTHING;
