INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Somme Trench', 'Somme Trench is an interactive historical-military novel by Andrew J. Schaefer, where your choices control the story. It''s entirely text-based, without graphics or sound effects. You play as a fresh British infantryman at the Battle of the Somme, one of the longest and bloodiest battles of World War One.' FROM games WHERE igdb_id = 275653 ON CONFLICT (game_id, language_code) DO NOTHING;
