INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sea of Lies: Nemesis - Collector''s Edition', 'Another intriguing whodunit brought to you by Eipix, the makers of Hidden Expedition: Smithsonian Hope Diamond, and the successful Final Cut series... Authorities are baffled by the death of a prominent citizen, and the Governor himself has asked you to investigate. Can you find out how these men died, how they’re all connected, and most importantly, who killed them? This murderer’s calling card is your nemesis in this exciting continuation of the Sea of Lies series.' FROM games WHERE igdb_id = 22081 ON CONFLICT (game_id, language_code) DO NOTHING;
