INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'La Tale', 'Welcome to the world of La Tale! Be part of an exciting story that unfolds all around you, while choosing your own unique path! La Tale is a free-to-play, massive multi-player, online role-playing game (MMORPG), with classic 2D side-scrolling action. The game features over 40 character classes, each with unique skills and weapons. There are near-endless character customization options, pets, crafting, guilds, and much more.' FROM games WHERE igdb_id = 16856 ON CONFLICT (game_id, language_code) DO NOTHING;
