INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rope''n''Fly 4', 'Use your ropes to swing a destructible ragdoll from one skyscraper to the others. You have full control over your ropes, touch on a building or object to throw your rope there, touch again to release it and fly through the sky. Perform various kinds of jumps to get achievements, attach to flying planes, jets or ballons and try to beat your friends or all other players by competing with them for the best score.' FROM games WHERE igdb_id = 288879 ON CONFLICT (game_id, language_code) DO NOTHING;
