INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghostbusters Pinball', 'Ghostbusters Pinball is fully licensed and based on the movies Ghostbusters and Ghostbusters 2 with music, sound effects, actor likenesses and quotes from both movies. The pinball table is beautifully detailed. Gameplay is a token based, free to play experience where the player receives ten free tokens to start and earns several free tokens each day. Pinball fans with FarSight’s Pinball Arcade installed on their device will free tokens twice as fast!' FROM games WHERE igdb_id = 58665 ON CONFLICT (game_id, language_code) DO NOTHING;
