INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Briquid Mini', 'BREAK. BUILD. SOLVE... again! Press Play Media - "An absolute steal for puzzle fans at less than 1 cent per puzzle" Indie Game Magazine - "Briquid Mini is a great title for any puzzle enthusiast" Gaming Cyhper - "The game is so addicting that we’ve found ourselves spending several hours trying to get 100% on each and every level" Briquid Mini is the sequel to the critically acclaimed iPad puzzle game Briquid. You can now also enjoy it on your iPhone! Break bricks, build new ones and solve 100 unique and challenging levels in this ingenious puzzle game. Some puzzles will take minutes to solve, others will take hours!' FROM games WHERE igdb_id = 106169 ON CONFLICT (game_id, language_code) DO NOTHING;
