INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Link', 'Tales of Link was a mobile game with a puzzle combat system instead of a variation on the Linear Motion Battle System (LMBS) the series is known for. The combat involved linking units on a 3x3 grid by color or type to unleash attacks and Artes that would be stronger based on their place in the chain, It featured characters from most of the past Tales of games as well as crossover characters and events from God Eater 2: Rage Burst, Brave Frontier, Kai-ri-Sei Million Arthur and Sword Art Online: Code Register. The game was shutdown in 2018.' FROM games WHERE igdb_id = 18813 ON CONFLICT (game_id, language_code) DO NOTHING;
