INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Across the Table Hockey', 'Across the Table – Hockey is a same-screen 2-player game that combines air hockey and table hockey. Imagine playing table hockey, but with the added speed and freedom of air hockey. This is a completely new way to play the world’s coolest sport. Across the Table - Hockey was built from the ground up for two players. We believe that true multiplayer games are meant to played in-person with your family and friends – whether it be at a coffee shop, cafeteria, or at home during game night. So grab a buddy, put your game face on and score some goals!' FROM games WHERE igdb_id = 175087 ON CONFLICT (game_id, language_code) DO NOTHING;
