INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curtain', 'CURTAIN is an interactive first-person narrative about Kaci & Ally, two queer women in a Glasgow punk band, which gives you a first hand experience of their destructive relationship. Players embody Ally coming home to their apartment after a successful gig as Kaci, your partner, watches and comments on every thought and action, creating an overwhelming, stifling atmosphere It takes about half an hour to finish, the game will exit itself.' FROM games WHERE igdb_id = 159075 ON CONFLICT (game_id, language_code) DO NOTHING;
