INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Growing Pains', 'Growing pains is a fast and furious platformer which gives the genre a shake up with sleek graphics, a thumping soundtrack and an ingenious twist that you’ve never seen before. The "Vessel" which you control continually grows and expands leaving you in a permanent race to clear the area and escape before you get too big and find your butt wedged in a tight spot. Combine this with tight controls and levels crammed with devious traps and you''ve got a heart-pounding race guaranteed to leave you with sweaty palms and a sense of overwhelming satisfaction when you reach the goal.' FROM games WHERE igdb_id = 17203 ON CONFLICT (game_id, language_code) DO NOTHING;
