INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frontline: The Longest Day', 'In Frontline: The Longest Day, players command the Allied forces through some of the most famous battles of the war, freeing Europe from the hands of the German Army. The game takes place over five massive, engaging and challenging missions, all inspired by historical missions which took place during operation Overlord: Utah, Omaha, Gold, Cherbourg, Sword & Juno.' FROM games WHERE igdb_id = 17610 ON CONFLICT (game_id, language_code) DO NOTHING;
