INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cow Evolution', 'In Cow Evolution, you evolve cows to get even bigger cows. The game combines elements of strategy, simulation, and incremental clicker mechanics. Starting with a humble cow, players breed and evolve their livestock through successive generations, unlocking new species and mutations along the way.' FROM games WHERE igdb_id = 203205 ON CONFLICT (game_id, language_code) DO NOTHING;
