INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('strawberry-shortcake-berry-rush', 259535, '2014-09-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8svy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnoud.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strawberry Shortcake: Berry Rush', 'Get ready for some Strawberry Shortcake fun! Strawberry and her friends want to bake fruitilicious cakes, but they need your help! Run, slide and leap through the wonderful world of Berry Bitty City and grab all the strawberries, cherries, oranges and other yummy fruit you can find! Then it’s time to decorate your cake, and snap a picture to show your friends! Collect as many sticker packs as you can and fill the amazing sticker book! Play as Strawberry Shortcake or one of her friends! Look: Cherry Jam, Orange Blossom, Blueberry Muffin, Lemon Meringue, Raspberry Torte, Plum Pudding and Huckleberry Pie… they’re all here! Run along with the super-adorable and cute puppy pals! Every day is a special occasion for Strawberry Shortcake, and that calls for a fresh and fruity look. Each character has her own set of stylish outfits. Come join the fun and play Strawberry Shortcake’s berry exciting Berry Rush adventure!' FROM games WHERE igdb_id = 259535 ON CONFLICT (game_id, language_code) DO NOTHING;
