INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cheetah Simulator', 'Enter into the wild savanna and live the life of a Cheetah with Cheetah Simulator, an indie adventure simulator! Explore a vast grassy plain filled with ferocious animals of all shapes and sizes. Raise a family, hunt down food, and battle for your life against fierce predators like hyenas, crocodiles, and lions.' FROM games WHERE igdb_id = 88155 ON CONFLICT (game_id, language_code) DO NOTHING;
