INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('destiny-limited-edition', 147699, '2014-09-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30ev.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8pt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destiny: Limited Edition', 'The Limited Edition includes everything that''s in the Ghost Edition minus the Ghost replica, letter of introduction and Golden Age Relics pack. The contents is as follows: - Limited Edition SteelBook Case and Game Disc - Guardian Folio, containing: - “Arms and Armament” Field Guide: Many believe the weapons and armor featured in this record are a myth. You will learn the truth. - Postcards from the Golden Age: Our worlds have been claimed by our enemies. Now, it’s time to take them back. - Antique Star Chart: Explore the wild frontiers of our solar system. Discover all that we have lost. Collector’s Edition Digital Content: The City has provided you with a cache of items to start you on your journey, including: - A Unique Ghost Casing - An Exclusive Player Emblem - An Exclusive Player Ship Skin Destiny Expansion Pass - The Destiny Limited Edition also includes the Destiny Expansion Pass. Vanguard Armory - As an added incentive to pre-order, players will gain early access to the Vanguard Armory which includes nine weapons, three helmets and an emblem. According to the Bungie, these items will be attainable through gameplay for those that choose not to pre-order.' FROM games WHERE igdb_id = 147699 ON CONFLICT (game_id, language_code) DO NOTHING;
