INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Souls II: Black Armor Edition', 'Dark Souls II: Black Armor Edition is a special edition released in March 2014. It includes the base game packaged in a collectable steel bookcase and comes with a bonus soundtrack CD. The steel bookcase features unique artwork, providing a more premium presentation for the game. It also provides early access to the following weapons and shields: - Black Flamestone Dagger and Black Flamestone Parma - Bound Hand Axe and Bound Wooden Shield - Homunculus Mace and Homunculus Wooden Shield - Transgressor''s Staff and Transgressor''s Leather Shield - Yellow Quartz Longsword and Yellow Quartz Shield' FROM games WHERE igdb_id = 222664 ON CONFLICT (game_id, language_code) DO NOTHING;
