INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Voice Commander, a Microsoft Garage project', 'Voice Commander, a Microsoft Garage project, is a fast paced, space themed, RTS and top-down shooter combo. Pick up a controller and work with Vox using voice commands to try to stop relentless attacks. Voice Commander can be played with up to eight controllers, and anyone in the room can issue voice commands. Microsoft Garage turns fresh ideas into real projects. Learn more at microsoft.com/garage' FROM games WHERE igdb_id = 82404 ON CONFLICT (game_id, language_code) DO NOTHING;
