INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supercars Racing', 'Enjoy dizzying races on the world’s most varied and exotic racetracks. Challenge the most desperate and ruthless racers on the planet and become the undisputed champion. This free game offers speed, risk, adrenaline, uncompromising opponents, and half-a-dozen roaring monsters on wheels! Take a prize-winning place in thunderous races and win valuable prizes. Buy new cars and upgrades to get even more speed and beat the toughest rival racers on your way to becoming champion! Modern graphics and an awesome soundtrack will help you have a blast in Supercars Racing. On your mark, get set, go! Free Game features: - Six original sports cars; - Vehicle upgrade system; - Over 30 unique racetracks in various international locales; - Championship and one-on-one races; - Four racing modes; - Dynamic gameplay; - Modern graphics and atmospheric music.' FROM games WHERE igdb_id = 87147 ON CONFLICT (game_id, language_code) DO NOTHING;
