INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dogforce', 'It''s time for walkies! You''ve been let off your leash for 45 seconds in the park, so it''s time to cram in all the dog business you can before it''s time to go home. Use your super DOGFORCE powers to score as many points as you can - scare off birds, show the world how much you love it, and catch every ball and frisbee you can.' FROM games WHERE igdb_id = 128421 ON CONFLICT (game_id, language_code) DO NOTHING;
