INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '9 Elefants', 'After arriving in Paris to present his latest invention, the Time Camera, at the Universal Science Congress, Professor Weissmann disappeared without a trace. His daughter, Laura, believes he has been kidnapped. Aided by Eustache, the Professor’s cat, Laura sets out on the trail of a mysterious sect, whose symbol is 9 elephants. The intrepid duo is confronted by a series of challenges, and each has to draw on their powers of invention and deduction to unravel the plot at the heart of this extraordinary adventure.' FROM games WHERE igdb_id = 68999 ON CONFLICT (game_id, language_code) DO NOTHING;
