INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angels of Fasaria', 'What is Angels of Fasaria?:  Angels of Fasaria was originally released in 2005. With thousands of downloads and over 48 thousand active users in the browser based game, Angels of Fasaria maintained a loyal following and support base. After the release of "Fasaria World" and later the "Ancients of Fasaria" mmorpg, Angels of Fasaria RPG and the browser based game community was closed and discontinued.' FROM games WHERE igdb_id = 36110 ON CONFLICT (game_id, language_code) DO NOTHING;
