INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Challenge 2015', 'Ski Challenge 2015 is the 11th edition of the alpine skiing series Ski Challenge. The game includes the famous alpine downhill tracks of Bormio, Val Gardena, Kitzbühel, Wengen, Val-d’Isère, Garmisch-Partenkirchen, Beaver Creek, Sochi and Schladming. The goal for the players is to climb the leaderboards by getting the fastest times. Three day events were held on each track to determine race winners who would win physical prizes.' FROM games WHERE igdb_id = 87794 ON CONFLICT (game_id, language_code) DO NOTHING;
