INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lasy Legacy: Null Space', 'Last Legacy is a side-scrolling, platformer-puzzle game series for PC currently with 2 installments. You play as an adventurer with a magical terraforming ability where you can manipulate the environment around you as you explore new areas, battle enemies, and discover secrets. Released for free in flash player summer 2014, Last Legacy: Null Space is the 2nd game under the Last Legacy series. Your character falls into a wormhole and finds himself in a mysterious universe called the Null Space, and visits 15 alternate dimensions on his way to get back to his own dimension. This game introduces upgradeable equipment and offers an optional hard version of each level.' FROM games WHERE igdb_id = 277673 ON CONFLICT (game_id, language_code) DO NOTHING;
