INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medarot 8: Kabuto Version', 'Medarot 8 is the eighth main installment in the Medarot series. The game features a new cast of characters and over 200 Medarots to collect. Like previous games, it was released in Kabuto and Kuwagata versions where the player starts with Metabee or Rokusho, respectively. The story follows a new protagonist named Salt and his adventures as part of the Laurel Detective Bureau, which investigates Medarot-related crimes.' FROM games WHERE igdb_id = 138117 ON CONFLICT (game_id, language_code) DO NOTHING;
