INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laza Knitez!!', 'Laza Knitez!! is a fast-paced jousting deathmatch game for up to 4 players. Teleport to the neon-lit ALL CAPS technofuture and challenge your friends to mind-blowing hypercombat. Fire your laser-lance from a distance, get up close and personal to empale your foes and use 7 different power-ups to your' FROM games WHERE igdb_id = 134513 ON CONFLICT (game_id, language_code) DO NOTHING;
