INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sea Has No Claim', '1 Wreck - 10 People - 502 km of ocean 1 Wreck - 20 People - 982 km of ocean 2 Wrecks - 100 People - 2002 km of ocean 3 Wrecks - 180 People - 4502 km of ocean 1 Wreck - 45 People - 6482 km of ocean 3 Wrecks - 300 People - 12502 km of ocean 2 Wrecks - 80 People - 18002 km of ocean This is my entry for Ludum Dare 29. Developed in 48 hours for the theme ''Beneath the surface''.' FROM games WHERE igdb_id = 185646 ON CONFLICT (game_id, language_code) DO NOTHING;
