INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-very-hungry-caterpillar', 321784, '2014-10-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9168.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scueev.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Very Hungry Caterpillar', 'It begins with a tiny egg. Tap it and marvel as it hatches into a Very Hungry Caterpillar. Can you find him some food to eat? Eric Carle’s much-loved character, The Very Hungry Caterpillar, has won the hearts of millions of children around the world for more than 50 years. Equally My Very Hungry Caterpillar app has been enthralling and teaching new generations of children in this award-winning toddler-friendly game. With over 6 million downloads to date this multi-award winning app has now been fully updated for this special 5th anniversary release. The Very Hungry Caterpillar loves food and fun. Feed him, play with him, and make sure to tuck him up under his cosy leaf so he gets plenty of rest. The more the caterpillar grows the more new activities you unlock. Grow flowers, sort shapes, paint pictures, pick fruit, go sailing alongside cute rubber ducks and goldfish. You can even hunt for buried treasure with him. Push him on a swing. Have fun playing together. Help him explore, pick him up, or take a peek into his colourful toy box. If you care for him, the caterpillar turns into a cocoon. Tap it and help transform him into a beautiful butterfly. Then do it all again when a new egg appears. It''s a world of beauty and colour you''ll return to again and again.' FROM games WHERE igdb_id = 321784 ON CONFLICT (game_id, language_code) DO NOTHING;
