INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enemy Mind', 'Built for PC, Enemy Mind lets you battle your way through 70+ waves of challenging enemies. Deftly maneuver over twenty unique ships, each with different abilities for you to harness. Backed by an all-new chip-emulated soundtrack by the psychoacoustic artist Rainbow Kitten, Enemy Mind features an adaptive story system as innovative as its gameplay. Are you ready to unlock the secrets of Enemy Mind?' FROM games WHERE igdb_id = 17157 ON CONFLICT (game_id, language_code) DO NOTHING;
