INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flappy Golf', 'Be aware! This is not your average ''flappy'' game! INSANELY addictive so download at your own risk! Flap your way to the hole with this unique spin on our famous golf game! Using the now famous "flap" mechanic you must get to the hole in the fewest flaps as possible! Featuring the courses from Super Stickman Golf 2, Flappy Golf is a fun little project we put together for the Flappy Jam game jam. Can you get gold stars on all the holes?' FROM games WHERE igdb_id = 107648 ON CONFLICT (game_id, language_code) DO NOTHING;
