INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Dice Dungeon', 'Adventure with tiny heroes through dark dungeons full of giant monsters to capture the ultimate treasure. Use strength and strategy to tame evil creatures to fight by your side, building a powerful army to take over this fantasy universe. If you love pure roleplaying games full of super-awesomeness, Tiny Dice Dungeon is for you. Fight legendary battles against hundreds of different monsters and bosses, while strengthening your characters to complete your quest of world-domination!' FROM games WHERE igdb_id = 62086 ON CONFLICT (game_id, language_code) DO NOTHING;
