INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abyss', 'An Expanded version of the original on Nintendo DSi. Abyss is an arcade-adventure game telling the story of a teenager who sets off on a dangerous and obstacle-filled journey. Take part in this thrilling adventure, explore 21 different levels, from the gloomy streets of ód to the infernal dungeons. You will be lead by the guide all the way, which will help you to complete all tasks. This one will not be easy...' FROM games WHERE igdb_id = 210669 ON CONFLICT (game_id, language_code) DO NOTHING;
