INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('think--3', 175547, '2014-02-06', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sce52y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Think', 'A minimalistic, beautifully designed visual puzzle game. In the beginning, human beings communicated only using symbols. Language complicated things. Suddenly, there were many words to describe the same idea. Think attempts to slowly teach the player to think visually and uses these learnings to construct more complicated ideas further into the game. Can you take a look at a bunch of images and figure out what ideas we are trying to communicate? The game uses a smart, contextually aware hint system and AI which will guide you to the correct answer - instead of just opening out few letters on the keyboard as most other games do. You will find yourself having delightful conversations with the game and trying out various combinations - just to elicit a response from the AI. With over 500+ puzzles spread over 40+ chapters, this game is sure to pull you in. Best played with friends and family together. You will rediscover the delight and joy in solving puzzles together - huddled around a small screen for hours together.' FROM games WHERE igdb_id = 175547 ON CONFLICT (game_id, language_code) DO NOTHING;
