INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abducted Toad', 'Abducted Toad is an unofficial fan game starring Toad from the Mario series. Toad has been abducted by aliens! Now, with the help of a friendly alien who grants him spectacular powers, Toad must overthrow the evil King Purplius and restore peace to the alien world! But there may be more to the situation than meets the eye... Blast your way through over 30 levels as you explore the strange world of Planet Purplius on your quest to bring down the evil king! Collect all the info discs hidden throughout the levels! Featuring an original soundtrack by K16!' FROM games WHERE igdb_id = 135096 ON CONFLICT (game_id, language_code) DO NOTHING;
