INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallen Sanctum', 'With many skills, quests and achievements what''s there to miss. Come join all your friends in the epic battle against mankind''s worst nightmare. Raise guilds and fight against the most epic monsters on the planet and go on the worlds deadliest adventures beneath the Earths crust and find some of the rarest items! Can you make it to the top? Above all your friends!? Do you have what it takes to beat the best?' FROM games WHERE igdb_id = 26886 ON CONFLICT (game_id, language_code) DO NOTHING;
