INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paganitzu', 'Journey into an Aztec pyramid and survive the adventure of a lifetime! No other game forces you to die in order to complete it! That''s just one of many incredible plot twists in this excellent puzzle-oriented arcade-adventure game. Guide Alabama Smith (Al) into a vast and dangerous Aztec pyramid. Confront traps of increasing perplexity and face unfathomable creatures in this innovative arcade game that tests your mind more than your finger speed.' FROM games WHERE igdb_id = 35549 ON CONFLICT (game_id, language_code) DO NOTHING;
