INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bentley Bear’s Crystal Quest', 'Crystal Quest is a homebrew game and an unofficial sequel to Crystal Castles, with very different gameplay. You play as Bentley Bear in a side-scrolling platform game. Your task is to retrieve the five crystals of life that were stolen by your enemy Berthilda. There are various enemies along the way to avoid and various power-ups that will help in your quest. The title was bundled with the Atari 7800+.' FROM games WHERE igdb_id = 314440 ON CONFLICT (game_id, language_code) DO NOTHING;
