INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Math Sudoku', 'Test your math skills and solve the puzzles using addition, subtraction, multiplication and division. Math Sudoku combines Sudoku and Math which creates entertaining and challenging puzzles. Math Sudoku was created as a fun way to increase students logic and problem-solving skills, but Math Sudoku is for everyone. There are over 632 puzzles!' FROM games WHERE igdb_id = 324062 ON CONFLICT (game_id, language_code) DO NOTHING;
