INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moratheia', 'Moratheia is a King''s Field-inspired game. It will take you to the land of Pelmora, a torn land where savage beasts await those who would dare explore its depths, where allies are few and trickery and temptation attempt to knock you off balance... A story so daring it will take you to some of the strangest and eeriest places imaginable, testing your resolve and commitment at every turn.' FROM games WHERE igdb_id = 171835 ON CONFLICT (game_id, language_code) DO NOTHING;
