INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Dynamo', 'The people of the Mushroom Kingdom have finally embraced industrialization, and it is all thanks to everyone''s favorite plumber, Luigi! Unfortunately, Luigi''s greed got the best of him, and the entire kingdom became shrouded in darkness. The thick smog emanating from Luigi''s accomplishments have darkened the once bright and colorful kingdom. It is now up to Mario to try and solve this dilemma!' FROM games WHERE igdb_id = 320230 ON CONFLICT (game_id, language_code) DO NOTHING;
